local config = {
  ui_story_5040_50400101_1_dialog_content = "(Ahh... Las vacaciones son difíciles de conseguir...)",
  ui_story_5040_50400101_2_dialog_content = "(¡No, cálmate!)",
  ui_story_5040_50400101_3_dialog_content = "\"(Bip) 3 días hasta <color=#FFB400>Día de la corona de luna</color>.\"",
  ui_story_5040_50400101_4_dialog_content = "\"El Día de la Corona de la Luna es una fiesta tradicional en Astra. Es un día para que las parejas expresen su amor y un día popular para las bodas\".",
  ui_story_5040_50400101_5_dialog_content = "¡Ya lo sabia! Si no hubiera estado tan ocupado que me lo perdí el año pasado, no estaría...",
  ui_story_5040_50400101_6_dialog_content = "De todos modos, tengo que volver a comprar ese tocadiscos en relieve, en el que Vice y Carleen tenían la vista puesta. ¡Será una agradable sorpresa navideña!",
  ui_story_5040_50400101_7_dialog_content = "(Recientemente dijeron que tenían la intención de tomar un mini descanso, y no tengo idea de adónde han ido. Lo que sea, ¡tendré que ir a buscarlo solo!)",
  ui_story_5040_50400101_8_dialog_content = "PlayerName, ha sido un tiempo. ¿Algo en lo que pueda ayudarte?",
  ui_story_5040_50400101_9_dialog_content = "Lo siento, pero el Sindicato de Mensajeros está abrumado con el festival que se acerca, así que realmente no tengo tiempo para charlar.",
  ui_story_5040_50400101_10_dialog_content = "Sin mencionar que mi colega en la división Rediesel Wrench arruinó un montón de cartas que se dirigían a Lumopolis...",
  ui_story_5040_50400101_11_dialog_content = "Vaya... ¿Puedo ayudar en algo?",
  ui_story_5040_50400101_12_dialog_content = "Quiero comprar algo para las vacaciones, así que estoy aceptando trabajos ocasionales para ganar dinero.",
  ui_story_5040_50400101_13_dialog_content = "Realmente no quería molestarte de nuevo, especialmente porque ayudaste a Piolín la última vez.",
  ui_story_5040_50400101_14_dialog_content = "Pero ya que preguntaste, hay una cosa. ¿Crees que podrías pasarte por la división Rediesel Wrench?",
  ui_story_5040_50400101_15_dialog_content = "Un viejo amigo de Northland se casará el Día de la Corona de la Luna, al igual que muchos otros.",
  ui_story_5040_50400101_16_dialog_content = "Es solo que su prometida tuvo un pequeño accidente en el desierto de Rediesel hace un tiempo, y les preocupa que no haya suficiente tiempo para llegar a Northland una vez que se recupere.",
  ui_story_5040_50400101_17_dialog_content = "Y quieres pedir prestado el Coloso para asegurarte de que llegue allí, ¿verdad? No hay problema, eso es fácil de hacer.",
  ui_story_5040_50400101_18_dialog_content = "(Hablando de la boda de su amiga, ¿no irá Naroxel sola?)",
  ui_story_5040_50400101_19_dialog_content = "(De todos modos, siempre es mejor preguntarle los detalles a la persona involucrada. Esta debe ser la división de llaves Rediesel).",
  ui_story_5040_50400101_20_dialog_content = "<color=#e8d9bb>TOC Toc-</color>",
  ui_story_5040_50400101_21_dialog_content = "Discúlpame...",
  ui_story_5040_50400101_22_dialog_content = "¡Debes ser el joven Caelestite aquí para ayudar! ¡Te estaba esperando!",
  ui_story_5040_50400101_23_dialog_content = "Pensé que llegarías antes, de la forma en que Naroxel siempre habla de lo rápido que es el Coloso.",
  ui_story_5040_50400101_X23_dialog_content = "(¡Q-Qué serpiente tan enorme! ¿¡Esta cosa es un altavoz!? ¡Es increíble!)",
  ui_story_5040_50400101_X24_dialog_content = "(Y esta oficina... Refinada no suele ser del estilo Rediesel Wrench).",
  ui_story_5040_50400101_24_dialog_content = "(Vaya, esta oficina... El refinamiento no suele ser el estilo Rediesel Wrench).",
  ui_story_5040_50400101_25_dialog_content = "Encantado de conocerte. Soy PlayerName, aquí en nombre de Naroxel.",
  ui_story_5040_50400101_26_dialog_content = "¿Quienes son ustedes?",
  ui_story_5040_50400101_27_dialog_content = "Eres más joven de lo que imaginaba. De todos modos, déjame presentarme.",
  ui_story_5040_50400101_28_dialog_content = "Soy <color=#FFB400>Jerías</color>, miembro sénior de la División de Llaves Rediesel de Courier Union. Esto es <color=#FFB400>Tara</color>, nuestro cliente para este encargo.",
  ui_story_5040_50400101_29_dialog_content = "¡Hola, soy Tara! Nunca esperé encontrarme con la legendaria Caelestite. ¡Que suerte!",
  ui_story_5040_50400101_30_dialog_content = "¡Me halaga! ¿Vienes con nosotros a Northland también, Lady Jeriah?",
  ui_story_5040_50400101_31_dialog_content = "Solo Jeriah servirá. Jejeje, hubo una confusión con el correo, y no tuve más remedio que pedirle ayuda a Naroxel.",
  ui_story_5040_50400101_32_dialog_content = "Así que la representaré como testigo del matrimonio.",
  ui_story_5040_50400101_33_dialog_content = "(Me pregunto si ella es la colega que mencionó Naroxel, ¿quién es responsable del alboroto del correo?)",
  ui_story_5040_50400101_34_dialog_content = "¿Testigo? Escuché que tener a alguien de Courier Union asistiendo a una boda trae buena suerte a los recién casados.",
  ui_story_5040_50400101_35_dialog_content = "¡Ciertamente! No fue fácil encontrar un mensajero para una boda el Día de la Corona de Luna. ¡Naroxel tuvo que pedir un favor solo para nosotros!",
  ui_story_5040_50400101_36_dialog_content = "¿Está Naroxel realmente tan ocupada que no puede tener un solo día libre?",
  ui_story_5040_50400101_37_dialog_content = "Los períodos justo antes y después del Día de la Corona de la Luna son siempre los más ocupados para el Sindicato de Mensajeros, con todo tipo de invitaciones y cartas volando.",
  ui_story_5040_50400101_38_dialog_content = "El momento perfecto para que la encantadora Jeriah \"accidentalmente\" arruine un montón de paquetes con destino a Northland.",
  ui_story_5040_50400101_39_dialog_content = "Me imagino que invitaste aquí a nuestro amigo Caelestita para asuntos más importantes que para burlarte de mí. Vámonos. ¿No extrañas a tu prometido?",
  ui_story_5040_50400101_40_dialog_content = "Buena idea. Tan rápido como es el Coloso, será mejor que partamos lo antes posible.",
  ui_story_5040_50400101_41_dialog_content = "¡Guau! ¡Tu Coloso es tan diferente del Lagarto Gigante!",
  ui_story_5040_50400101_42_dialog_content = "Jaja, solo espera hasta que subas a bordo.",
  ui_story_5040_50400101_43_dialog_content = "Una novia del desierto y un novio norteño es una pareja interesante, por cierto. ¿Son comunes este tipo de uniones entre países?",
  ui_story_5040_50400101_44_dialog_content = "Hmm, bueno... ¡Yo diría que son bastante raros!",
  ui_story_5040_50400101_45_dialog_content = "El mundo es un lugar grande y todo es posible. Pero para los Aurorianos, es un poco extraño.",
  ui_story_5040_50400101_46_dialog_content = "¿Wow en serio?",
  ui_story_5040_50400101_47_dialog_content = "Muchacho... Jeriah, ¿tú también eres del desierto de Rediesel?",
  ui_story_5040_50400101_48_dialog_content = "No me gusta admitirlo, pero es verdad.",
  ui_story_5040_50400101_49_dialog_content = "Es bastante extraño que claramente hayas nacido y crecido en el desierto, pero no pareces tener muchos amigos en Rediesel Wrench.",
  ui_story_5040_50400101_50_dialog_content = "Tuve que preguntarle a mucha gente solo para encontrar tu oficina.",
  ui_story_5040_50400101_51_dialog_content = "Bueno, ahora, cada uno camina por su propio camino en la vida.",
  ui_story_5040_50400101_52_dialog_content = "De todos modos, la historia de mi vida no importa. Eres la estrella del espectáculo de hoy.",
  ui_story_5040_50400101_53_dialog_content = "¡Así es! ¡Nunca antes había conocido a una futura novia!",
  ui_story_5040_50400101_54_dialog_content = "No es tan grande de un acuerdo. Nosotros, los habitantes del desierto, somos bastante abiertos de mente cuando se trata de amor.",
  ui_story_5040_50400101_55_dialog_content = "De todos modos, no tenemos mucho tiempo, así que realmente quiero echar un vistazo al Coloso.",
  ui_story_5040_50400101_56_dialog_content = "Llévame de gira, PlayerName!",
  ui_story_5040_50400101_57_dialog_content = "Ah bien. ¡Espérame!",
  ui_story_5040_50400101_58_dialog_content = "Esto puede sonar mal, pero Tara realmente no me parece muy... como una novia.",
  ui_story_5040_50400101_59_dialog_content = "Cada quien tiene su estilo, pequeña Caelestite. No es bueno chismear a espaldas de la gente.",
  ui_story_5040_50400101_60_dialog_content = "Sí, supongo que tienes razón.",
  ui_story_5040_50400101_61_dialog_content = "(Jeriah parece completamente indiferente a la boda...)",
  ui_story_5040_50400101_62_dialog_content = "¡Uf! Finalmente estamos aquí.",
  ui_story_5040_50400101_63_dialog_content = "¿Se fue Tara a buscar a su prometido? Recuerdo haber visto lo que parecía un pueblo cercano.",
  ui_story_5040_50400101_64_dialog_content = "Origin Town, en la frontera de Northland. La mayoría de la gente allí es tradicional y celebra sus ceremonias de boda en el templo.",
  ui_story_5040_50400101_65_dialog_content = "¿Deberíamos ir allí entonces?",
  ui_story_5040_50400101_66_dialog_content = "Creo que esos dos probablemente estén en otro lugar ahora mismo.",
  ui_story_5040_50400101_67_dialog_content = "(Ahora que ya han dejado al cliente, ¿debo quedarme para la boda en sí?)",
  ui_story_5040_50400101_68_dialog_content = "¿Te estás preguntando si puedes volver ahora?",
  ui_story_5040_50400101_69_dialog_content = "(Ella me leyó como un libro.)",
  ui_story_5040_50400101_70_dialog_content = "Como eres amigo de Naroxel, sin duda te invitarán a la boda.",
  ui_story_5040_50400101_71_dialog_content = "Ya estás aquí, después de todo. Si bien las bodas de Northland pueden no ser tan animadas como las de Lumopolis, ciertamente tienen su propio carácter.",
  ui_story_5040_50400101_72_dialog_content = "Buen punto. Por cierto, pareces estar muy familiarizado con Northland para ser alguien de la División de Llaves Rediesel.",
  ui_story_5040_50400101_73_dialog_content = "¡No solo Northland! Ella sabe todo lo que hay que saber sobre el mundo, excepto las cosas relacionadas con el trabajo.",
  ui_story_5040_50400101_74_dialog_content = "¡Ajaja, has vuelto! ¿Dónde está el novio?",
  ui_story_5040_50400101_75_dialog_content = "¿Tara?",
  ui_story_5040_50400101_76_dialog_content = "Perdon por haberte hecho esperar...!",
  ui_story_5040_50400101_77_dialog_content = "Realmente eres un perezoso—",
  ui_story_5040_50400101_78_dialog_content = "Este es Jeriah de la División de Llaves Rediesel de Courier Union. Te hablé de ella.",
  ui_story_5040_50400101_79_dialog_content = "¡Y esta es la persona que nos trajo aquí! Encontrarse PlayerName, un Caelestita! Ese Coloso es realmente algo.",
  ui_story_5040_50400101_80_dialog_content = "Él es <color=#FFB400>Adonis</color>, mi prometido... Eh, es un poco raro decir eso. Usualmente solo uso su nombre.",
  ui_story_5040_50400101_81_dialog_content = "Encantado de conocerlos a ambos, Lady Jeriah, PlayerName.",
  ui_story_5040_50400101_82_dialog_content = "Perdón por la prisa de hoy. Naroxel es un viejo amigo mío de la escuela. Ella siempre está ahí para ayudar en una emergencia.",
  ui_story_5040_50400101_83_dialog_content = "Si me hiciera el honor de asistir, PlayerName, nos encantaría tenerte en la boda también.",
  ui_story_5040_50400101_84_dialog_content = "Oh sí, ¿ya has estado en casa?",
  ui_story_5040_50400101_85_dialog_content = "Er, todavía no.",
  ui_story_5040_50400101_86_dialog_content = "¿Aún no les has dicho?",
  ui_story_5040_50400101_87_dialog_content = "¿Cuánto tiempo exactamente planeas alargar esto?",
  ui_story_5040_50400101_88_dialog_content = "¡Solo un par de días! Iré mañana, lo prometo!",
  ui_story_5040_50400101_89_dialog_content = "¡Y mañana será pasado! ¡Mañana nunca llega! ¿Incluso QUIERES decírselo a tus padres?",
  ui_story_5040_50400101_90_dialog_content = "...",
  ui_story_5040_50400101_91_dialog_content = "(¿Que está pasando aqui?)",
  ui_story_5040_50400101_92_dialog_content = "Parece que nos estamos perdiendo la historia de fondo aquí.",
  ui_story_5040_50400101_93_dialog_content = "Ya que nos preguntaron a la joven Caelestite ya mí, ¿no deberías decirnos qué está pasando?",
  ui_story_5040_50400101_94_dialog_content = "Hmph. ¡Tú diles!",
  ui_story_5040_50400101_95_dialog_content = "... Probablemente encuentres esto ridículo, pero para ser honesto... vamos a tener una ceremonia privada y secreta.",
  ui_story_5040_50400101_96_dialog_content = "Mis padres nunca quisieron que me casara con Tara.",
  ui_story_5040_50400101_97_dialog_content = "ah Veo.",
  ui_story_5040_50400101_98_dialog_content = "El matrimonio entre un habitante del norte y un habitante del desierto es bastante poco común.",
  ui_story_5040_50400101_99_dialog_content = "¡Lo digo en serio, les diré esta vez!",
  ui_story_5040_50400101_100_dialog_content = "¡Y luego larguémonos de aquí! Podemos ir al Desierto de Rediesel oa cualquier otro lugar.",
  ui_story_5040_50400101_101_dialog_content = "¿Quieres decir que te estás fugando?",
  ui_story_5040_50400101_102_dialog_content = "Me encantaría poder convencer a mis padres, pero...",
  ui_story_5040_50400101_103_dialog_content = "¿Pero que? Ni siquiera lo has intentado.",
  ui_story_5040_50400101_104_dialog_content = "¿Es realmente tan difícil para ti hablar por ti mismo?",
  ui_story_5040_50400101_105_dialog_content = "Yo...",
  ui_story_5040_50400101_106_dialog_content = "Tengo curiosidad, Adonis, si alguna vez has dejado Northland antes.",
  ui_story_5040_50400101_107_dialog_content = "N-No. Tara y yo nos conocimos aquí.",
  ui_story_5040_50400101_108_dialog_content = "¡Ay! La flor de invernadero desea vivir la vida de una flor silvestre. Que valiente.",
  ui_story_5040_50400101_109_dialog_content = "¡Estoy listo! ¡Mientras dos personas se mantengan juntas, no hay nada que no se pueda superar!",
  ui_story_5040_50400101_110_dialog_content = "¿En realidad? ¿Qué tal si superas tu incapacidad para decírselo a tus padres?",
  ui_story_5040_50400101_111_dialog_content = "Um, siento interrumpir...",
  ui_story_5040_50400101_112_dialog_content = "Tengo un paquete para ti, Adonis. Dijiste que era urgente, así que lo traje directamente.",
  ui_story_5040_50400101_113_dialog_content = "¡Vaya, si no es el pajarito de Northland!",
  ui_story_5040_50400101_114_dialog_content = "¿D-Lady Jeriah?",
  ui_story_5040_50400101_115_dialog_content = "Gracias por su ayuda para ordenar esas pocas cartas que se enviaron aquí por accidente.",
  ui_story_5040_50400101_116_dialog_content = "¡Fue mucho más que unos pocos! Por favor, tenga más cuidado la próxima vez.",
  ui_story_5040_50400101_117_dialog_content = "<size=33>No quiero tener que manejar una carga de trabajo de pesadilla nunca más...</size>",
  ui_story_5040_50400101_118_dialog_content = "Gracias, <color=#FFB400>Kya</color>.",
  ui_story_5040_50400101_119_dialog_content = "¿Qué es eso?",
  ui_story_5040_50400101_120_dialog_content = "Oh, sí, el psíquico que envió esta poción dijo que tuviera mucho cuidado al usarla. Aparentemente es algo bastante potente.",
  ui_story_5040_50400101_121_dialog_content = "¿Poción? ¿Qué tipo de poción?",
  ui_story_5040_50400101_122_dialog_content = "Oh, er... te lo diré más tarde.",
  ui_story_5040_50400101_123_dialog_content = "¡Solo dime ahora! ¡¿Qué pasa con todos tus murmullos?!",
  ui_story_5040_50400101_124_dialog_content = "Suspiro...",
  ui_story_5040_50400101_125_dialog_content = "Se trata de un <color=#FFB400>poción para todo uso</color> hecho por un psíquico súper místico. Se puede usar para ayudar a cambiar el estado mental de uno de varias maneras, como aumentar la valentía.",
  ui_story_5040_50400101_126_dialog_content = "Pensé que me daría más confianza al tratar con mis padres.",
  ui_story_5040_50400101_127_dialog_content = "(¡Nunca antes había oído hablar de este tipo de poción!)",
  ui_story_5040_50400101_128_dialog_content = "¡¿Eh?! ¿Qué sucede contigo? ¿De verdad crees esa basura? Démelo aquí, déjeme ver.",
  ui_story_5040_50400101_129_dialog_content = "No puedo creer que todavía haya tontos que se enamoren de los psíquicos en estos días.",
  ui_story_5040_50400101_130_dialog_content = "Hemos estado juntos durante tres años, ¿y TODAVÍA tienes que confiar en una poción de aceite de serpiente para contarles a tus padres sobre nosotros?",
  ui_story_5040_50400101_131_dialog_content = "¡Tengo esto para ayudarnos!",
  ui_story_5040_50400101_132_dialog_content = "¿De verdad eres tan cobarde? ¿O tienes tan poca fe en nuestro futuro?",
  ui_story_5040_50400101_133_dialog_content = "Adonis, ¿realmente necesitamos confiar en la fuerza externa para mantener nuestra relación?",
  ui_story_5040_50400101_134_dialog_content = "Si debes ser así, tal vez sea mejor simplemente no...",
  ui_story_5040_50400101_135_dialog_content = "<color=#e8d9bb>Ruido... Ruido...</color>",
  ui_story_5040_50400101_136_dialog_content = "<size=45>Graaagh!</size>",
  ui_story_5040_50400101_137_dialog_content = "<size=45>Graa-!!</size>",
  ui_story_5040_50400101_138_dialog_content = "¿Eclipsitos? ¿De dónde vienen ellos?",
  ui_story_5040_50400101_139_dialog_content = "¡¿Qué están haciendo los eclipses aquí?!",
  ui_story_5040_50400101_140_dialog_content = "Bueno, esto es inesperado. Que molesto.",
  ui_story_5040_50400201_1_dialog_content = "<color=#e8d9bb>... ¡¡¡Chasquido!!!</color>",
  ui_story_5040_50400201_2_dialog_content = "¡Graaah—!",
  ui_story_5040_50400201_3_dialog_content = "¡Gra-!",
  ui_story_5040_50400201_4_dialog_content = "¿Qué está sucediendo? ¡¿Dónde están todos ellos procedentes de?!",
  ui_story_5040_50400201_5_dialog_content = "Tan molesto como esto es, es mejor ser cauteloso.",
  ui_story_5040_50400201_6_dialog_content = "Hay algo extraño en ese Eclipsite en el medio.",
  ui_story_5040_50400201_7_dialog_content = "Huff... Huff...",
  ui_story_5040_50400201_8_dialog_content = "¡Tara! ¡Detrás de ti!",
  ui_story_5040_50400201_9_dialog_content = "¡Adonis, quédate atrás! ¡Déjenos manejar esto!",
  ui_story_5040_50400201_10_dialog_content = "¡Cuidado, Tara! ¡Ese extraño Eclipsite parece tener sus ojos puestos en ti!",
  ui_story_5040_50400201_11_dialog_content = "Dar...",
  ui_story_5040_50400201_12_dialog_content = "Dame...",
  ui_story_5040_50400201_13_dialog_content = "quiero... quiero...",
  ui_story_5040_50400201_14_dialog_content = "¡¿Qué dijiste?!",
  ui_story_5040_50400201_15_dialog_content = "(¿Está hablando Universese?)",
  ui_story_5040_50400201_16_dialog_content = "¡Tara! ¡Deshazte de esa poción en tu mano!",
  ui_story_5040_50400201_17_dialog_content = "¿Qué-",
  ui_story_5040_50400201_18_dialog_content = "<color=#e8d9bb>¡Whoosh, golpe!</color>",
  ui_story_5040_50400201_19_dialog_content = "Tara!!",
  ui_story_5040_50400201_20_dialog_content = "Esto es peligroso. ¡Encuentra cobertura!",
  ui_story_5040_50400201_21_dialog_content = "<color=#e8d9bb>¡Bum!</color>",
  ui_story_5040_50400201_22_dialog_content = "¡Ahhhhh!",
  ui_story_5040_50400201_23_dialog_content = "Suspiro...! Poción...",
  ui_story_5040_50400201_24_dialog_content = "Grah...",
  ui_story_5040_50400201_25_dialog_content = "Grah! Graaaaah!",
  ui_story_5040_50400201_27_dialog_content = "¿Se acaban de despegar?",
  ui_story_5040_50400201_28_dialog_content = "Todavía quedan algunos más pequeños.",
  ui_story_5040_50400201_29_dialog_content = "Cuida de tu prometida, Adonis.",
  ui_story_5040_50400202_1_dialog_content = "Finalmente. ¿Todos están bien?",
  ui_story_5040_50400202_2_dialog_content = "¡Tara! Tara!!",
  ui_story_5040_50400202_3_dialog_content = "¡Oh, no! ¡Está fuera de combate!",
  ui_story_5040_50400202_4_dialog_content = "Ustedes dos, fuera del camino. Déjame ver.",
  ui_story_5040_50400202_5_dialog_content = "No hay herida grave. No parece que Eclipsite le haya hecho mucho daño.",
  ui_story_5040_50400202_6_dialog_content = "Solo algunos rasguños.",
  ui_story_5040_50400202_7_dialog_content = "Pero, ¿por qué se desmayaría, entonces? ¿Podría haberse golpeado la cabeza?",
  ui_story_5040_50400202_8_dialog_content = "En primer lugar, cálmate. Parece estar bien ahora, pero tenemos que llevarla a un lugar seguro.",
  ui_story_5040_50400202_9_dialog_content = "Um, ella parece haber recibido algo de esa poción en ella.",
  ui_story_5040_50400202_10_dialog_content = "No hay nada malo en ello, ¿verdad?",
  ui_story_5040_50400202_11_dialog_content = "¡No lo sé! ¡Tú eres el que lo quería, Adonis! Lo acabo de entregar en nombre de ese psíquico.",
  ui_story_5040_50400202_12_dialog_content = "No te pongas nervioso. Lo más importante en este momento es llevarla a algún lugar para descansar.",
  ui_story_5040_50400202_13_dialog_content = "Sí. Lo siento por el problema, todos. ¿Podríamos traerla a mi casa, por favor?",
  ui_story_5040_50400202_14_dialog_content = "Pues bien, me voy a terminar el resto de mis entregas. Cuiden a Tara, muchachos.",
  ui_story_5040_50400202_15_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc!</color>",
  ui_story_5040_50400202_16_dialog_content = "¿Adonis? ¿Sabes a qué hora es—",
  ui_story_5040_50400202_17_dialog_content = "¿Qué es esto? ¡¿Qué ha pasado?!",
  ui_story_5040_50400202_18_dialog_content = "Es una larga historia, padre. Entremos primero.",
  ui_story_5040_50400202_19_dialog_content = "¿Estos son amigos tuyos, Adonis? Y esta chica... ¿Es esa Tara?",
  ui_story_5040_50400202_20_dialog_content = "Lo siento por los inconvenientes ocasionados.",
  ui_story_5040_50400202_21_dialog_content = "Está herida, madre. Nos encontramos con algunos eclipses... ¿Podemos instalarla en algún lugar primero? Luego te cuento toda la historia.",
  ui_story_5040_50400202_22_dialog_content = "¿Eclipsitos? Deberíamos tener un botiquín de primeros auxilios en alguna parte. ¿Hay alguna herida que necesite ser atendida? ¡¿Estás lastimado?!",
  ui_story_5040_50400202_23_dialog_content = "No hay motivo de alarma. Tiene algunos rasguños y probablemente esté en estado de shock. Todos los demás están bien.",
  ui_story_5040_50400202_24_dialog_content = "Iré a cuidarla. Ustedes chatean.",
  ui_story_5040_50400202_25_dialog_content = "Entonces, eso fue lo que pasó...",
  ui_story_5040_50400202_26_dialog_content = "¡Absurdo!",
  ui_story_5040_50400202_27_dialog_content = "¿Cómo no nos contaste a tu madre y a mí sobre esto?",
  ui_story_5040_50400202_28_dialog_content = "Si ella no hubiera resultado herida, ¿simplemente ibas a fugarte y luego dejar Northland?",
  ui_story_5040_50400202_29_dialog_content = "Yo...",
  ui_story_5040_50400202_30_dialog_content = "Siempre pensé que eras un poco denso, ¡pero no pensé que fueras un completo idiota!",
  ui_story_5040_50400202_31_dialog_content = "¡¿Todo lo que Novio te enseñó te entró por un oído y te salió por el otro?!",
  ui_story_5040_50400202_32_dialog_content = "¿De verdad crees que puedes arreglártelas solo si te vas de Northland? Entonces bien, vete! ¡Y nunca volvio!",
  ui_story_5040_50400202_33_dialog_content = "¡Pretenderemos que nunca tuvimos un hijo!",
  ui_story_5040_50400202_34_dialog_content = "Papá, mamá, por favor... ¡Yo no quise decir eso!",
  ui_story_5040_50400202_35_dialog_content = "Ahórrate tus patéticas excusas, ¡no quiero escuchar nada de eso!",
  ui_story_5040_50400202_36_dialog_content = "Tu padre solo está enojado, hijo.",
  ui_story_5040_50400202_37_dialog_content = "Pero realmente, Adonis, estamos al final de nuestro juicio contigo.",
  ui_story_5040_50400202_38_dialog_content = "...",
  ui_story_5040_50400202_39_dialog_content = "Oh...",
  ui_story_5040_50400202_40_dialog_content = "(... No puedo decir que haya presenciado algo así antes).",
  ui_story_5040_50400202_41_option_content = "Confort Adonis",
  ui_story_5040_50400202_42_dialog_content = "No te lo tomes a pecho. Solo están un poco molestos.",
  ui_story_5040_50400202_43_dialog_content = "Quiero decir, es normal que se emocionen un poco al escuchar todo esto de repente.",
  ui_story_5040_50400202_44_dialog_content = "Pero siguen siendo tus padres. Solo habla con ellos más tarde, y estoy seguro de que todo saldrá bien.",
  ui_story_5040_50400202_45_dialog_content = "Suspiro... mis padres no me perdonarán, y Tara también está herida.",
  ui_story_5040_50400202_46_dialog_content = "Soy realmente un fracaso.",
  ui_story_5040_50400202_47_dialog_content = "(Esto no es bueno. Parece estar atrapado en un ciclo de pensamientos negativos sobre sí mismo...)",
  ui_story_5040_50400202_48_option_content = "Pídele ayuda a Jeriah",
  ui_story_5040_50400202_49_dialog_content = "¿Qué debemos hacer, Jeriah?",
  ui_story_5040_50400202_50_dialog_content = "¿Eh? ¿Qué?",
  ui_story_5040_50400202_51_dialog_content = "(¿Estaba distraída? ¡¿En un momento como este?!)",
  ui_story_5040_50400202_52_dialog_content = "¿Qué dices en estas circunstancias?",
  ui_story_5040_50400202_53_dialog_content = "Este es su problema. No importa lo que digan los demás.",
  ui_story_5040_50400202_54_dialog_content = "De todos modos, incluso si ofrece algunos tópicos amables, en realidad no resuelve nada.",
  ui_story_5040_50400202_55_dialog_content = "(Ella no está equivocada, ¡pero seguramente no puedo decir nada!)",
  ui_story_5040_50400202_56_dialog_content = "(Esto es tan incómodo... La atmósfera es tan rígida e incómoda.)",
  ui_story_5040_50400202_57_dialog_content = "Lo siento mucho, chicos. No puedo imaginar lo que debes pensar.",
  ui_story_5040_50400202_58_dialog_content = "Está totalmente bien. Háganos saber si hay algo que podamos hacer para ayudar.",
  ui_story_5040_50400202_59_dialog_content = "Eh... He traído todo esto sobre mí mismo.",
  ui_story_5040_50400202_60_dialog_content = "Tú también has recorrido un largo camino y yo he sido un anfitrión terrible.",
  ui_story_5040_50400202_61_dialog_content = "No te preocupes por eso ahora.",
  ui_story_5040_50400202_62_dialog_content = "¿Por qué no lo sacas para despejarle la cabeza? PlayerName? Atenderé a Tara.",
  ui_story_5040_50400202_63_dialog_content = "Bueno. Vamos a tomar un poco de aire fresco.",
  ui_story_5040_50400202_64_dialog_content = "Seguro...",
  ui_story_5040_50400202_65_dialog_content = "...",
  ui_story_5040_50400202_66_dialog_content = "Ya era hora de que te levantaras, creo.",
  ui_story_5040_50400202_67_dialog_content = "¡¿?!",
  ui_story_5040_50400202_68_dialog_content = "¿Cómo sabías que estaba despierto?",
  ui_story_5040_50400202_69_dialog_content = "Ese Eclipsite ni siquiera te atacó realmente.",
  ui_story_5040_50400202_70_dialog_content = "Dudaba mucho que pudieras haber estado inconsciente durante tanto tiempo.",
  ui_story_5040_50400202_71_dialog_content = "...",
  ui_story_5040_50400202_72_dialog_content = "Solo estoy aquí para ayudar a Naroxel, así que no perderé mucho tiempo involucrándome.",
  ui_story_5040_50400202_73_dialog_content = "Este no es mi negocio de todos modos.",
  ui_story_5040_50400202_74_dialog_content = "Pero como le estoy haciendo un favor, solo aventuraré una pregunta. ¿Que planeas hacer?",
  ui_story_5040_50400202_75_dialog_content = "Yo...",
  ui_story_5040_50400202_76_dialog_content = "¿Honestamente? No tengo ni idea. La vida en el desierto nunca fue tan complicada. Estoy tan molesto.",
  ui_story_5040_50400202_77_dialog_content = "No puedo negar que Adonis me trae mucha felicidad. Pero su falta de agallas me hace preguntarme si realmente puedo casarme con él.",
  ui_story_5040_50400202_78_dialog_content = "El carácter de alguien no se forma ni se puede cambiar de la noche a la mañana. Han estado juntos durante tanto tiempo, ¿realmente descubrieron este problema ahora?",
  ui_story_5040_50400202_79_dialog_content = "Claro que no.",
  ui_story_5040_50400202_80_dialog_content = "Hace tres años, fui atacado por Eclipsites mientras buscaba ruinas en Northland. Logré escapar, pero me desmayé al costado del camino.",
  ui_story_5040_50400202_80X1_dialog_content = "Él es quien me encontró y me trajo a casa.",
  ui_story_5040_50400202_81_dialog_content = "También hubo fuertes nevadas ese día. No quiero pensar en lo que podría haber pasado si él no me hubiera encontrado.",
  ui_story_5040_50400202_82_dialog_content = "*Suspiro* Después de eso, hablamos de cualquier cosa y de todo, de cosas que el otro nunca había visto.",
  ui_story_5040_50400202_83_dialog_content = "Nos mantuvimos en contacto después de que regresé al desierto, enviándonos cartas de un lado a otro.",
  ui_story_5040_50400202_84_dialog_content = "Fue tan atento y considerado. Crecí sin padres, y nadie me había mostrado ese tipo de cuidado antes.",
  ui_story_5040_50400202_85_dialog_content = "Realmente me conmovió.",
  ui_story_5040_50400202_86_dialog_content = "Ah, así es como sucedió.",
  ui_story_5040_50400202_87_dialog_content = "Pero más tarde, cada vez que se mencionaba el tema de dejar Northland, siempre parecía vacilante. Siento que realmente ha cambiado.",
  ui_story_5040_50400202_88_dialog_content = "No es como solía ser. ¿Es realmente tan difícil decidirse?",
  ui_story_5040_50400202_89_dialog_content = "¡Nunca conocí a un hombre tan tímido, tan indeciso! ¿Realmente le gusto?",
  ui_story_5040_50400202_90_dialog_content = "He estado planeando nuestra boda durante mucho tiempo e incluso preparé un regalo muy especial. Pero ahora... Meh.",
  ui_story_5040_50400202_91_dialog_content = "Probablemente esto no sea apropiado, pero ¿alguna vez has estado enamorada antes que él?",
  ui_story_5040_50400202_92_dialog_content = "¿Antes de Adonis? No, es mi primer amor.",
  ui_story_5040_50400202_93_dialog_content = "Bueno, no es de extrañar entonces. Parece que tienes algunas expectativas poco realistas de él.",
  ui_story_5040_50400202_94_dialog_content = "El amor puede ser algo hermoso, pero también hay que respetar quién es alguien. Cada individuo es una criatura complicada y matizada; nadie es simplemente blanco o negro.",
  ui_story_5040_50400202_95_dialog_content = "¿Q-Qué quieres decir? No estoy seguro de seguir.",
  ui_story_5040_50400202_96_dialog_content = "Jejeje... Algún día, puede que lo entiendas.",
  ui_story_5040_50400202_97_dialog_content = "...",
  ui_story_5040_50400202_98_dialog_content = "¡Esperar! ¡Lo tengo! ¡Tengo una idea!",
  ui_story_5040_50400202_99_dialog_content = "?",
  ui_story_5040_50400202_102_dialog_content = "¡Eso es todo!",
  ui_story_5040_50400202_103_dialog_content = "¡Pretenderé tener amnesia! ¡Comienza todo de nuevo, mira cómo actúa conmigo!",
  ui_story_5040_50400202_104_dialog_content = "...",
  ui_story_5040_50400202_105_dialog_content = "¿Hablas en serio?",
  ui_story_5040_50400202_106_dialog_content = "¡Por favor, te lo ruego! ¡Ayúdame!",
  ui_story_5040_50400202_107_dialog_content = "Si ustedes dos no se van a casar, probablemente yo debería irme.",
  ui_story_5040_50400202_108_dialog_content = "¡Oh vamos! ¡No te vayas! ¿Qué le dirías al Naroxel?",
  ui_story_5040_50400202_109_dialog_content = "¿Estás tratando de amenazarme?",
  ui_story_5040_50400202_110_dialog_content = "¡Ay! ¡No, no, claro que no! ¿Cómo podría? Has sido tan amable conmigo... ¡Por favor, te lo ruego!",
  ui_story_5040_50400202_111_dialog_content = "¡Por favor, hágalo no solo por Naroxel, sino por una compañera de Rediesel Wrench!",
  ui_story_5040_50400202_112_dialog_content = "Seguro que sabes cómo manipular a la gente.",
  ui_story_5040_50400202_113_dialog_content = "Que dolor.",
  ui_story_5040_50400202_114_dialog_content = "¡Por favor! ¡Usted es el mejor!",
  ui_story_5040_50400202_115_dialog_content = "Ustedes dos deben resolver sus propios problemas. Solo soy un espectador.",
  ui_story_5040_50400202_116_dialog_content = "Depende de ti cómo se desarrolla tu teatralidad.",
  ui_story_5040_50400202_117_dialog_content = "<color=#e8d9bb>El siguiente día...</color>",
  ui_story_5040_50400202_118_dialog_content = "Buenos días, Jeriah, Adonis.",
  ui_story_5040_50400202_119_dialog_content = "Buenos días, joven Caelestite.",
  ui_story_5040_50400202_120_dialog_content = "Mañana. Voy a ir a ver si Tara está despierta...",
  ui_story_5040_50400202_121_dialog_content = "*Bostezos*",
  ui_story_5040_50400202_122_dialog_content = "¡Tara! ¡Estas despierto! ¿Estás bien?",
  ui_story_5040_50400202_123_dialog_content = "¿...?",
  ui_story_5040_50400202_124_dialog_content = "¿Qué ocurre? ¿Por qué me miras así?",
  ui_story_5040_50400202_125_dialog_content = "¿Quién eres?",
  ui_story_5040_50400202_126_dialog_content = "¿De qué estás hablando? ¿Tara?",
  ui_story_5040_50400202_127_dialog_content = "no te conozco ¡No me toques!",
  ui_story_5040_50400202_128_dialog_content = "¿Dónde estoy? ¿Quién es usted?",
  ui_story_5040_50400202_129_dialog_content = "Recuerdo haber venido ayer a Northland con Jeriah en el Coloso, pero... Qué extraño, no recuerdo por qué.",
  ui_story_5040_50400202_130_dialog_content = "Esto no es divertido, Tara...",
  ui_story_5040_50400202_131_dialog_content = "¡No es divertido en absoluto!",
  ui_story_5040_50400202_132_dialog_content = "¿Estás bien, Adonis?",
  ui_story_5040_50400202_133_dialog_content = "(Es gracioso, Tara suena extrañamente tranquila, considerando todas las cosas. ¿Dijo eso a propósito?)",
  ui_story_5040_50400202_134_dialog_content = "(Realmente no entiendo los asuntos del corazón. Las cosas podrían empeorar si me entrometo, así que es mejor no entrometerse en este momento).",
  ui_story_5040_50400202_135_dialog_content = "¡Esto es mi culpa! ¡Todo culpa mía!",
  ui_story_5040_50400202_136_dialog_content = "¡Esa maldita poción! ¡Ojalá nunca lo hubiera pensado!",
  ui_story_5040_50400202_137_dialog_content = "¿Crees que la poción es responsable de su amnesia?",
  ui_story_5040_50400202_138_dialog_content = "¡El psíquico dijo que era capaz de producir todo tipo de efectos! ¡No puedo pensar en ninguna otra razón para esto!",
  ui_story_5040_50400202_139_dialog_content = "Tiene que ser eso. ¡La poción se derramó sobre ella, justo cuando estaba enfadada conmigo y deseando poder olvidarse de mí! ¡Así que eso fue lo que hizo la poción!",
  ui_story_5040_50400202_140_dialog_content = "¡Todo es mi culpa!",
  ui_story_5040_50400202_141_dialog_content = "Si realmente es eso, ¿por qué no ir a preguntarle al psíquico?",
  ui_story_5040_50400202_142_dialog_content = "No tiene sentido quedarse aquí llorando sobre la leche derramada.",
  ui_story_5040_50400202_143_dialog_content = "¿Psíquico?",
  ui_story_5040_50400202_144_dialog_content = "¡Sí tienes razón! ¡Y acabo de recordar que a veces montan un puesto en el mercado!",
  ui_story_5040_50400202_145_dialog_content = "¡Iré! ¡Iré ahora mismo!",
  ui_story_5040_50400202_146_dialog_content = "*Jadeando*... ¡A-Allá!",
  ui_story_5040_50400202_147_dialog_content = "(Wow, está corriendo tan rápido...)",
  ui_story_5040_50400202_148_dialog_content = "¿Mmm? ¿Quién podrías ser?",
  ui_story_5040_50400202_149_dialog_content = "¡Soy el tipo que compró esa poción multiusos! ¡Tengo una pregunta urgente para ti!",
  ui_story_5040_50400202_150_dialog_content = "Eh...? ¡Oh sí! ¡Ese tipo!",
  ui_story_5040_50400202_151_dialog_content = "¿Cómo fue? Derramo mi corazón y mi alma en todas y cada una de las botellas, así que confío en que los resultados fueron los esperados.",
  ui_story_5040_50400202_152_dialog_content = "Es una larga historia, pero mi prometida usó la poción accidentalmente, ¡y ahora no puede recordar nada! ¡Por favor, tienes que darme el antídoto!",
  ui_story_5040_50400202_153_dialog_content = "¡¿Eh?! Pero eso no es posible...",
  ui_story_5040_50400202_154_dialog_content = "¿No dijiste que podía hacer cualquier cosa? ¡¿Lo que el corazón deseaba?!",
  ui_story_5040_50400202_155_dialog_content = "Sí dije eso, sí.",
  ui_story_5040_50400202_156_dialog_content = "Pero si lo que buscas es un antídoto... Me temo que podría requerir un poco de esfuerzo.",
  ui_story_5040_50400202_157_dialog_content = "¿Eh? ¡¿Cómo?!",
  ui_story_5040_50400202_158_dialog_content = "Porque está hecho de algo que muy pocas personas han visto. El tesoro más raro de Rediesel Desert, ¡las brillantes escamas del legendario gusano de arena rosa!",
  ui_story_5040_50400202_159_dialog_content = "Yo mismo soy del desierto. ¿Cómo es que nunca he oído hablar de esto antes?",
  ui_story_5040_50400202_160_dialog_content = "!",
  ui_story_5040_50400202_161_dialog_content = "Bueno, dime... Si todos los plebeyos lo supieran, ¿seguiría siendo raro?",
  ui_story_5040_50400202_162_dialog_content = "La mayoría de las personas nunca verán el misterioso gusano de arena rosa ni una sola vez en sus vidas.",
  ui_story_5040_50400202_163_dialog_content = "(Creo que este psíquico está lleno de eso. ¿Y quién querría ver tal cosa de todos modos?)",
  ui_story_5040_50400202_164_dialog_content = "¡Sus escamas brillan con todos los colores del arco iris, mientras que su cuerpo rosado es tan magnífico y deslumbrante como la concha más hermosa!",
  ui_story_5040_50400202_165_dialog_content = "Si insistes en este antídoto, no se puede prescindir de alguna de sus escamas. ¡Quizás deberías pensar en cómo conseguir algunos!",
  ui_story_5040_50400202_166_dialog_content = "¡¿E-Estás haciendo las cosas difíciles intencionalmente, verdad?!",
  ui_story_5040_50400202_167_dialog_content = "Oye, yo no soy el que quiere el antídoto. Te lo he dicho de buena fe, ahora déjame en paz. No quiero que afectes mi negocio.",
  ui_story_5040_50400202_168_dialog_content = "...",
  ui_story_5040_50400202_169_dialog_content = "Eso es todo. Se acabó.",
  ui_story_5040_50400202_170_dialog_content = "Estoy dispuesto y puedo hacer lo que sea necesario, pero ¿luchar contra un gusano de arena...? Imposible.",
  ui_story_5040_50400202_171_dialog_content = "Hasta los gusanos de mi jardín me aterrorizan. ¡No hay forma de que pueda ir a buscar un gusano de arena del desierto!",
  ui_story_5040_50400202_172_dialog_content = "Sabes... No suelo conocer a hombres con tan poca columna vertebral como tú.",
  ui_story_5040_50400202_173_dialog_content = "(¡Por favor, no empeores esto!)",
  ui_story_5040_50400202_174_dialog_content = "Mirar el lado bueno. Al menos está viva y saludable, y por lo que entiendo acaba de perder la memoria de su relación.",
  ui_story_5040_50400202_175_dialog_content = "En lugar de emprender una búsqueda inútil, tal vez sea mejor pensar en cómo reavivar ese fuego romántico.",
  ui_story_5040_50400202_176_dialog_content = "Y de todos modos, ella no ha olvidado todo. Mientras ella esté bien, entonces todavía hay una posibilidad.",
  ui_story_5040_50400202_177_dialog_content = "Debe haber una razón por la que ustedes dos estuvieron juntos durante tanto tiempo. No creo que sea demasiado difícil empezar de nuevo, por así decirlo.",
  ui_story_5040_50400202_178_dialog_content = "Sí... Supongo que tienes razón.",
  ui_story_5040_50400202_179_dialog_content = "La cosa es que no tengo la menor idea por donde empezar. Ella me ve como un completo extraño.",
  ui_story_5040_50400202_180_dialog_content = "Por cierto, estoy seguro de que ambos recuerdan que me enviaron aquí para la boda en nombre de Naroxel.",
  ui_story_5040_50400202_181_dialog_content = "Mucha gente se casa el Día de la Corona de Luna y la mayoría quiere un mensajero para asistir a su boda.",
  ui_story_5040_50400202_182_dialog_content = "He oído hablar de esa tradición. Aparentemente, tener un mensajero en tu boda puede traer felicidad y esperanza.",
  ui_story_5040_50400202_183_dialog_content = "Correcto. Es por eso que Union ha estado organizando eventos especiales del Día de la Corona de Luna en los últimos años, dirigidos a recién casados y parejas.",
  ui_story_5040_50400202_184_dialog_content = "También ayuda a aliviar parte de la presión sobre los mensajeros. Es uno de los momentos más ocupados del año, después de todo.",
  ui_story_5040_50400202_185_dialog_content = "¿En realidad? Nunca lo supe.",
  ui_story_5040_50400202_186_dialog_content = "Cierto, eso es obvio, porque están dirigidos a parejas. Dudo mucho que estén en el radar de los solteros perpetuos.",
  ui_story_5040_50400202_187_dialog_content = "¡Oye!",
  ui_story_5040_50400202_188_dialog_content = "¿A qué te refieres?",
  ui_story_5040_50400202_189_dialog_content = "En bastantes lugares, este evento ya ha reemplazado la costumbre de que los mensajeros asistan a la boda como una bendición de la suerte para las parejas felices.",
  ui_story_5040_50400202_190_dialog_content = "Cada rama tiene su propio evento, y aquellos que lo experimentan con éxito reciben el Sello de Plumas del Sindicato de Mensajeros.",
  ui_story_5040_50400202_191_dialog_content = "Debería considerar asistir a uno de estos eventos con Tara. Podrías ver el mundo exterior mientras lo haces.",
  ui_story_5040_50400202_192_dialog_content = "¿Quieres decir... dejar Northland?",
  ui_story_5040_50400202_193_dialog_content = "Los amnésicos a menudo pueden tener recuerdos del pasado que se agitan a través de eventos externos. Eso es en realidad un viejo remedio popular.",
  ui_story_5040_50400202_194_dialog_content = "Todo lo que digo es que el evento de Courier Union podría ser una gran oportunidad. Lo que haga con él, en todo caso, depende de usted.",
  ui_story_5040_50400202_195_dialog_content = "No lograrás mucho encerrándote y preocupándote en casa. Si no sales a ver el mundo, ¿cómo sabrás si hay una solución?",
  ui_story_5040_50400202_196_dialog_content = "No es de mi incumbencia, pero ¿quién puede decir que no descubras alguna forma de recuperar sus recuerdos saliendo y viajando?",
  ui_story_5040_50400202_197_dialog_content = "Estoy de acuerdo!",
  ui_story_5040_50400202_198_dialog_content = "También pasé mucho tiempo solo en soledad antes. Me enseñaron todo lo que sabía sobre el mundo.",
  ui_story_5040_50400202_199_dialog_content = "Fue solo cuando salí que me di cuenta de que el mundo más amplio contenía tantas cosas de las que no sabía nada.",
  ui_story_5040_50400202_200_dialog_content = "Si sales y exploras, ¡puedes refrescar los recuerdos de Tara y aprender más sobre su condición!",
  ui_story_5040_50400202_201_dialog_content = "Tipo...!",
  ui_story_5040_50400202_202_dialog_content = "En realidad, yo... um, realmente no sé qué decir.",
  ui_story_5040_50400202_203_dialog_content = "Le agradezco que me ayude a pensar en ideas. En este momento, la condición de Tara es lo único en lo que puedo pensar.",
  ui_story_5040_50400202_204_dialog_content = "¡Tienes razón! Yo creo en nuestro amor. ¡Todo lo que hemos perdido se puede encontrar de nuevo!",
  ui_story_5040_50400202_205_dialog_content = "...",
  ui_story_5040_50400202_206_dialog_content = "...",
  ui_story_5040_50400202_207_dialog_content = "¡Eso es lo que estoy pensando!",
  ui_story_5040_50400202_208_dialog_content = "Sé que puede que no estés de acuerdo, pero...",
  ui_story_5040_50400202_209_dialog_content = "Vete entonces.",
  ui_story_5040_50400202_210_dialog_content = "¿Ah?",
  ui_story_5040_50400202_211_dialog_content = "Si ustedes dos regresan de sus viajes y aún desean tener una vida juntos, bueno... podríamos considerarlo seriamente.",
  ui_story_5040_50400202_212_dialog_content = "¡¿D-De verdad?!",
  ui_story_5040_50400202_213_dialog_content = "¡No puedo creerlo! Madre, Padre, ¡muchas gracias!",
  ui_story_5040_50400202_214_dialog_content = "Solo recuerda que nunca has estado fuera de Northland antes. Es un mundo peligroso ahí fuera, así que tienes que tener mucho cuidado.",
  ui_story_5040_50400202_215_dialog_content = "<size=33>¿Qué pasa con su repentino cambio de opinión, Jeriah?</size>",
  ui_story_5040_50400202_216_dialog_content = "Me pregunto...",
  ui_story_5040_50400202_217_dialog_content = "¿Puedo hablar con usted, señor?",
  ui_story_5040_50400202_218_dialog_content = "¿Mmm? ¿Quién eres tú?",
  ui_story_5040_50400202_219_dialog_content = "Soy Jeriah, un miembro senior de la Unión de Mensajeros.",
  ui_story_5040_50400202_220_dialog_content = "Oh. ¿Puedo ayudarle con algo? Si tiene que ver con ese desagradecido malcriado hijo de—",
  ui_story_5040_50400202_221_dialog_content = "Entiendo totalmente cómo te sientes.",
  ui_story_5040_50400202_222_dialog_content = "Lo único que quieren los padres es que sus hijos sean felices. Tal vez sus preocupaciones se deban al temor de que sea demasiado ingenuo e infantil.",
  ui_story_5040_50400202_223_dialog_content = "Alguien que nunca ha salido de su casa y que de repente quiere vivir una vida romántica y errante.",
  ui_story_5040_50400202_224_dialog_content = "No creo que yo sea capaz de aceptarlo, tampoco.",
  ui_story_5040_50400202_225_dialog_content = "Es como dices. ¡Nada en la vida es tan fácil!",
  ui_story_5040_50400202_226_dialog_content = "Adonis estudió bajo la tutela del Sr. Novio cuando era niño. Es atento e inteligente, solo un poco demasiado ingenuo.",
  ui_story_5040_50400202_227_dialog_content = "No ha experimentado mucho, por lo que tiene una tendencia a ver el mundo a través de lentes color de rosa.",
  ui_story_5040_50400202_228_dialog_content = "Entonces, ¿qué tal si le damos la oportunidad de experimentar cosas?",
  ui_story_5040_50400202_229_dialog_content = "Cuanto más tiempo permanece el polluelo en el nido, menos capacidad tiene para sobrevivir por sí mismo.",
  ui_story_5040_50400202_230_dialog_content = "Aquellos que no son tan fuertes como los demás nunca aprovecharán activamente la felicidad, solo la recibirán pasivamente.",
  ui_story_5040_50400202_231_dialog_content = "Realmente no importa a dónde vayan, o con quién.",
  ui_story_5040_50400202_232_dialog_content = "Pareces un padre sensato. ¿Qué opinas?",
  ui_story_5040_50400202_233_dialog_content = "No sé lo que dijiste, pero mientras todo salga bien.",
  ui_story_5040_50400301_1_dialog_content = "¡Carta para ti! ¡Aquí tienes!",
  ui_story_5040_50400301_2_dialog_content = "Gracias, Kya. ¿Cómo es que estás trabajando hasta tan tarde?",
  ui_story_5040_50400301_3_dialog_content = "El festival está a la vuelta de la esquina. Espero poder entregar más, ya que estoy seguro de que la gente está esperando ansiosamente.",
  ui_story_5040_50400301_4_dialog_content = "Los novatos son siempre los más trabajadores. ¡Todo lo mejor para usted!",
  ui_story_5040_50400301_5_dialog_content = "Uf, es tan tarde.",
  ui_story_5040_50400301_6_dialog_content = "Todo entregado, por fin. Supongo que lo llamaré un día hoy.",
  ui_story_5040_50400301_7_dialog_content = "(Esta tarde escuché a Adonis decir que a Tara le dio amnesia... ¿Podría estar relacionado con el ataque del Eclipsite de ayer?)",
  ui_story_5040_50400301_8_dialog_content = "(Es preocupante. Tal vez debería volver a donde sucedió y mirar alrededor).",
  ui_story_5040_50400301_9_dialog_content = "(Creo que estaba justo por aquí.)",
  ui_story_5040_50400301_10_dialog_content = "¿Eh?",
  ui_story_5040_50400301_11_dialog_content = "¿Por qué es morado aquí? ¿Es por esa poción?",
  ui_story_5040_50400301_12_dialog_content = "Y parece que hay huellas violetas que se adentran en el bosque.",
  ui_story_5040_50400301_13_dialog_content = "Bueno, será mejor que lo compruebe.",
  ui_story_5040_50400301_14_dialog_content = "<color=#e8d9bb>Graznido, graznido—</color>",
  ui_story_5040_50400301_15_dialog_content = "(¡Está tan oscuro! Tal vez debería regresar. Esto da un poco de miedo).",
  ui_story_5040_50400301_16_dialog_content = "Espera... ¿Las pistas acaban de terminar aquí?",
  ui_story_5040_50400301_17_dialog_content = "Ah...",
  ui_story_5040_50400301_18_dialog_content = "<size=50>¡Aaaaaah!</size>",
  ui_story_5040_50400301_19_dialog_content = "¡¿Quién está ahí?!",
  ui_story_5040_50400301_20_dialog_content = "H-Ayuda...",
  ui_story_5040_50400301_21_dialog_content = "Ayúdame...",
  ui_story_5040_50400301_22_dialog_content = "¡¿Q-Quién habla?!",
  ui_story_5040_50400301_23_dialog_content = "Yo... ¡Yo!",
  ui_story_5040_50400301_24_dialog_content = "¡¿Un E-Eclipsito?!",
  ui_story_5040_50400301_25_dialog_content = "N-No... No...",
  ui_story_5040_50400301_26_dialog_content = "Yo... No... Daño...",
  ui_story_5040_50400301_27_dialog_content = "¿Qué? ¿Es eso Universese? ¡Pero tú eres el Eclipsite que atacó a Tara ayer!",
  ui_story_5040_50400301_28_dialog_content = "Yo... No... Herí... Tú...",
  ui_story_5040_50400301_29_dialog_content = "¡Quedarse atrás! ¿Qué estás haciendo?",
  ui_story_5040_50400301_30_dialog_content = "Por favor... tu...",
  ui_story_5040_50400301_31_dialog_content = "Ayúdame...",
  ui_story_5040_50400301_32_dialog_content = "¿Qué dijiste?",
  ui_story_5040_50400301_33_dialog_content = "Mi... memoria... se ha ido...",
  ui_story_5040_50400301_34_dialog_content = "Yo... olvidé... quién... soy yo...",
  ui_story_5040_50400301_35_dialog_content = "Asustado...",
  ui_story_5040_50400301_36_dialog_content = "Muy asustado...",
  ui_story_5040_50400301_37_dialog_content = "¿No sabes quién eres? Entonces, ¿por qué nos atacaste ayer?",
  ui_story_5040_50400301_38_dialog_content = "Yo... No... Ataco...",
  ui_story_5040_50400301_39_dialog_content = "Quiero... poción...",
  ui_story_5040_50400301_40_dialog_content = "¿Poción?",
  ui_story_5040_50400301_41_dialog_content = "Yo... escondo... mercado...",
  ui_story_5040_50400301_42_dialog_content = "Escucha... poción... poderosa...",
  ui_story_5040_50400301_43_dialog_content = "Quiere... usar... restaurar... memoria...",
  ui_story_5040_50400301_44_dialog_content = "Pero... ellos... tomaron...",
  ui_story_5040_50400301_45_dialog_content = "Así que eso fue lo que pasó.",
  ui_story_5040_50400301_46_dialog_content = "Pero, ¿cómo podría un Eclipsite tener recuerdos? ¿Podrías haber sido alguna vez un auroriano?",
  ui_story_5040_50400301_47_dialog_content = "Piensa... entonces... pero... olvidé...",
  ui_story_5040_50400301_48_dialog_content = "Tengo miedo...",
  ui_story_5040_50400301_49_dialog_content = "(Todos desprecian a los Eclipsites, pero no parece que esté mintiendo...)",
  ui_story_5040_50400301_50_dialog_content = "(Si alguien se entera de que estoy ayudando a un Eclipsite, definitivamente perderé mi trabajo como mensajero. Incluso podría ser arrestado).",
  ui_story_5040_50400301_51_dialog_content = "Frío…",
  ui_story_5040_50400301_52_dialog_content = "¡Es!",
  ui_story_5040_50400301_53_dialog_content = "Está bien. Ven entonces.",
  ui_story_5040_50400301_54_dialog_content = "Agradecer...!",
  ui_story_5040_50400301_55_dialog_content = "Para que quede claro, ¡cualquier asunto extraño y alertaré al Portavoz!",
  ui_story_5040_50400301_56_dialog_content = "¡Sí!",
  ui_story_5040_50400301_57_dialog_content = "Bien, ¿y ahora qué...?",
  ui_story_5040_50400301_58_dialog_content = "Escóndete aquí un poco más.",
  ui_story_5040_50400301_59_dialog_content = "¡Sí, esto debería funcionar!",
  ui_story_5040_50400301_60_dialog_content = "Puedo...?",
  ui_story_5040_50400301_61_dialog_content = "¿Estás seguro de que quieres ponerte esto? Es mi viejo vestido de dama de honor.",
  ui_story_5040_50400301_62_dialog_content = "Pareces un auroriano con él, aunque el vestido sobresale un poco.",
  ui_story_5040_50400301_63_dialog_content = "Gracias... Tú... Vestido... Bien...",
  ui_story_5040_50400301_64_dialog_content = "No importa. Puedes ponértelo si te gusta. Mi nombre es Kya, por cierto. ¿Cómo debo llamarte en público? ¿Recuerdas tu nombre?",
  ui_story_5040_50400301_65_dialog_content = "No... sé...",
  ui_story_5040_50400301_66_dialog_content = "Supongo que te llamaré Sable por ahora, entonces. ¿Como es que?",
  ui_story_5040_50400301_67_dialog_content = "E... Está bien...",
  ui_story_5040_50400301_68_dialog_content = "¿De verdad no recuerdas nada en absoluto?",
  ui_story_5040_50400301_69_dialog_content = "No...",
  ui_story_5040_50400301_70_dialog_content = "¿Siempre has estado en Northland?",
  ui_story_5040_50400301_71_dialog_content = "No... creo... vengo de... muy lejos...",
  ui_story_5040_50400301_72_dialog_content = "Hmm, ok. Déjame pensar.",
  ui_story_5040_50400301_73_dialog_content = "<color=#e8d9bb>El día siguiente-</color>",
  ui_story_5040_50400301_74_dialog_content = "¿Listo?",
  ui_story_5040_50400301_75_dialog_content = "Ustedes van a hacer un largo viaje. Asegúrate de tener todo lo que necesitas.",
  ui_story_5040_50400301_76_dialog_content = "¡Sí! Tenemos suficiente carne de arenque, venado y tiburón en lata para al menos un mes.",
  ui_story_5040_50400301_77_dialog_content = "En cuanto a los productos secos, tenemos foca, camarones y pescado liofilizados suficientes para dos meses.",
  ui_story_5040_50400301_78_dialog_content = "Luego, en caso de emergencia, hay una estufa portátil, un martillo de diez libras, cuchillos, una pala, tetera, botas, impermeables...",
  ui_story_5040_50400301_79_dialog_content = "Espera un segundo. Vas a Lumopolis, ¿verdad? ¿Y no sobrevivir en el desierto del Territorio Secreto?",
  ui_story_5040_50400301_80_dialog_content = "¿Seguramente eso es un poco exagerado? ¿Qué tipo de lugar crees que es Lumopolis?",
  ui_story_5040_50400301_81_dialog_content = "Visitaremos Lumopolis, la ciudad de Gannon y el desierto de Rediesel en este viaje. Quiero estar lo más preparado posible.",
  ui_story_5040_50400301_82_dialog_content = "Esa es la idea correcta, pero piensa en lo que realmente usarás. No es como si pudieras morir de hambre en cualquiera de los lugares a los que vas.",
  ui_story_5040_50400301_83_dialog_content = "...",
  ui_story_5040_50400301_84_dialog_content = "¿Qué? ¿De viaje? ¡¿Con un desconocido?!",
  ui_story_5040_50400301_85_dialog_content = "Tranquila, Tara. Es un viaje, pero esperamos que te ayude a recuperar la memoria.",
  ui_story_5040_50400301_86_dialog_content = "¿Seguro que quieres recordar?",
  ui_story_5040_50400301_87_dialog_content = "Por supuesto que sí, pero esto es una locura.",
  ui_story_5040_50400301_88_dialog_content = "Y de todos modos, solo he olvidado cosas relacionadas contigo.",
  ui_story_5040_50400301_89_dialog_content = "Dices eso, pero nuestros recuerdos juntos son importantes tanto para ti como para mí.",
  ui_story_5040_50400301_90_dialog_content = "Mmm...",
  ui_story_5040_50400301_91_dialog_content = "Respeto tu opinión, por supuesto que sí, pero tengo muchas ganas de al menos intentar recuperar tu memoria viajando.",
  ui_story_5040_50400301_92_dialog_content = "¿Qué opinas? No te obligaré a ir si realmente no quieres.",
  ui_story_5040_50400301_93_dialog_content = "(Oh chico, no puedo creer que vayamos a hacer esto. ¿Por qué soy tan blando?)",
  ui_story_5040_50400301_94_dialog_content = "Relájate, Tara. ¡Te cuidaré! ¡No hay nada de que preocuparse!",
  ui_story_5040_50400301_95_dialog_content = "¡Tu trabajo en este viaje es divertirte!",
  ui_story_5040_50400301_96_dialog_content = "Ni siquiera sé quién eres. No creas que puedes ser amable conmigo y me conmoveré o algo así.",
  ui_story_5040_50400301_97_dialog_content = "Quiero ir a casa.",
  ui_story_5040_50400301_98_dialog_content = "Te llevaré a casa. Nuestra última parada es el desierto.",
  ui_story_5040_50400301_99_dialog_content = "¡Solo nos divertiremos en el camino! Y mientras tanto, pensaremos en maneras de refrescar su memoria.",
  ui_story_5040_50400301_100_dialog_content = "Bien. Lo que sea.",
  ui_story_5040_50400301_101_dialog_content = "Bueno, entonces, si está todo listo, entonces es hora de irse. Te llevaré a Lumopolis, ya que de todos modos necesito informar a Naroxel.",
  ui_story_5040_50400301_102_dialog_content = "PlayerName! ¡Esperar!",
  ui_story_5040_50400301_103_dialog_content = "¿Ah?",
  ui_story_5040_50400301_104_dialog_content = "*Jadeo* ¡Uf, me alegro de haberte puesto al día!",
  ui_story_5040_50400301_105_dialog_content = "¡Si no es el pajarito de Northland! Tan lindo, incluso cuando estás sin aliento.",
  ui_story_5040_50400301_106_dialog_content = "¡Por favor, no se burle de mí, Lady Jeriah! Entonces, um... Escuché que todos irán a Lumopolis. ¿Podrías llevarnos a nosotros también?",
  ui_story_5040_50400301_107_dialog_content = "\"A nosotros\"?",
  ui_story_5040_50400301_108_dialog_content = "¿Es posible que se esté refiriendo a este extraño individuo que se parece sospechosamente a un eclipse?",
  ui_story_5040_50400301_109_dialog_content = "¡N-No puedes simplemente decirle a alguien que parece un Eclipsite!",
  ui_story_5040_50400301_110_dialog_content = "¡Este es mi, eh, pariente lejano! Ella se llama Sable.",
  ui_story_5040_50400301_111_dialog_content = "H-Hola... a todos...",
  ui_story_5040_50400301_112_dialog_content = "(Estoy absolutamente seguro de que este Sable está emitiendo Darkflow serio...)",
  ui_story_5040_50400301_113_dialog_content = "(Pero no suenan otras campanas de alarma. Es mejor esperar y ver).",
  ui_story_5040_50400301_114_dialog_content = "Un mirlo pequeño, ¿eh? Interesante atuendo el que llevas.",
  ui_story_5040_50400301_115_dialog_content = "¡A S-Sable le gusta la ropa formal! No sale mucho, así que quería vestirse un poco.",
  ui_story_5040_50400301_116_dialog_content = "(Por alguna razón inexplicable, parece que le gusta mucho ese vestido. Mucho. ¿Podría ser algún fetiche extraño?)",
  ui_story_5040_50400301_117_dialog_content = "¿Y ustedes también quieren ir a Lumopolis?",
  ui_story_5040_50400301_118_dialog_content = "Quiero mostrarle los alrededores durante el festival. ¿Puedes llevarnos contigo, por favor? También tengo algunas cartas que necesito entregar a Lumopolis.",
  ui_story_5040_50400301_119_dialog_content = "¡Por supuesto! Si está todo listo, podemos irnos ahora mismo.",
  ui_story_5040_50400301_120_dialog_content = "<color=#e8d9bb>Soroz</color>",
  ui_story_5040_50400301_121_dialog_content = "¿No vas a descansar un poco, Jeriah?",
  ui_story_5040_50400301_122_dialog_content = "Jeje... Leer es descansar para mí.",
  ui_story_5040_50400301_123_dialog_content = "Y no estoy cansado.",
  ui_story_5040_50400301_124_dialog_content = "Ve a dormir un poco si estás cansada, pequeña Caelestite.",
  ui_story_5040_50400301_125_dialog_content = "Vaya, eso es impresionante. Ni siquiera puedo entender lo que estás leyendo.",
  ui_story_5040_50400301_126_dialog_content = "Cada uno tenemos nuestros intereses. Disfruto leyendo textos antiguos.",
  ui_story_5040_50400301_127_dialog_content = "Es mucho más relajante que tratar con aurorianos.",
  ui_story_5040_50400301_128_dialog_content = "¿Ah?",
  ui_story_5040_50400301_129_dialog_content = "Por cierto, cuando lleguemos a Lumopolis, ¿irás a buscar Naroxel?",
  ui_story_5040_50400301_130_dialog_content = "Todavía tenemos cosas que hacer; Iré a hablar con ella primero una vez que lleguemos allí.",
  ui_story_5040_50400301_131_dialog_content = "¡Yaaa!",
  ui_story_5040_50400301_132_dialog_content = "¡¿?!",
  ui_story_5040_50400301_133_dialog_content = "¡Eclipsitos! Señora Jeriah, PlayerName, ¡Cuidado!",
  ui_story_5040_50400301_134_dialog_content = "¡Ayuda... ne...!",
  ui_story_5040_50400301_135_dialog_content = "¿Cómo subió a bordo Eclipsites? ¿Siguieron a alguien adentro?",
  ui_story_5040_50400301_136_dialog_content = "Podemos hablar de eso más tarde. Abordemos primero esas cosas antiestéticas.",
  ui_story_5040_50400302_1_dialog_content = "<color=#e8d9bb>Después de lidiar con los Eclipsites, todos logran descansar. Llegaron sanos y salvos a Lumopolis...</color>",
  ui_story_5040_50400302_2_dialog_content = "Uf, esa fue una estricta inspección de aduanas, pero afortunadamente, no hicieron las cosas demasiado difíciles.",
  ui_story_5040_50400302_3_dialog_content = "(Si Caelestite no hubiera respondido por nosotros, la tapadera de Sable habría desaparecido. Gracias a Dios que pudimos acompañarnos para llegar a la ciudad).",
  ui_story_5040_50400302_4_dialog_content = "PlayerName! ¡Señora Jeriah! ¡Le mostraré a mi pariente la ciudad y le entregaré algunas cartas mientras estoy en eso! ¡Hasta luego!",
  ui_story_5040_50400302_5_dialog_content = "¡Ella acaba de despegar!",
  ui_story_5040_50400302_6_dialog_content = "...",
  ui_story_5040_50400302_7_dialog_content = "Guau... ¡Así que esto es Lumopolis! Ciertamente tiene un ambiente bastante diferente.",
  ui_story_5040_50400302_8_dialog_content = "¿Qué opinas, Tara?",
  ui_story_5040_50400302_9_dialog_content = "...No es mi primera vez aquí.",
  ui_story_5040_50400302_10_dialog_content = "R-Correcto...",
  ui_story_5040_50400302_11_dialog_content = "No perdamos tiempo. Deberíamos ir a buscar Naroxel.",
  ui_story_5040_50400302_12_dialog_content = "¡naroxel! ¡Ha sido para siempre!",
  ui_story_5040_50400302_13_dialog_content = "Espera, ¿quién... Adonis?",
  ui_story_5040_50400302_14_dialog_content = "¡Ha sido un largo tiempo! ¿Qué te trae a Lumópolis? ¿Tus padres y el Sr. Novio están bien?",
  ui_story_5040_50400302_15_dialog_content = "Todo el mundo lo está haciendo muy bien.",
  ui_story_5040_50400302_16_dialog_content = "Y este es el que siempre menciono en mis cartas, Tara.",
  ui_story_5040_50400302_17_dialog_content = "...",
  ui_story_5040_50400302_18_dialog_content = "En realidad, Naroxel, hemos vuelto a Lumopolis porque tenemos un pequeño problema...",
  ui_story_5040_50400302_19_dialog_content = "<color=#e8d9bb>Después de contarle la historia a Naroxel...</color>",
  ui_story_5040_50400302_20_dialog_content = "¿Cómo es eso posible?",
  ui_story_5040_50400302_21_dialog_content = "Nunca he oído hablar de una poción que pueda borrar los recuerdos de las personas.",
  ui_story_5040_50400302_22_dialog_content = "Sí, también me resulta difícil entenderlo.",
  ui_story_5040_50400302_23_dialog_content = "¿Hay algo que pueda hacer para ayudar? ¿Nada en absoluto? Somos viejos amigos, así que no tengas miedo de preguntar.",
  ui_story_5040_50400302_24_dialog_content = "En realidad, Jeriah sugirió que participáramos en los eventos del Día de la Corona de la Luna que la Unión de Mensajeros organiza en diferentes ciudades para obtener focas de plumas.",
  ui_story_5040_50400302_25_dialog_content = "Es una gran oportunidad para visitar nuevos lugares y tal vez encontrar algunas pistas para curar la amnesia de Tara.",
  ui_story_5040_50400302_26_dialog_content = "Focas de plumas?",
  ui_story_5040_50400302_27_dialog_content = "Es cierto, el Courier Union ofrece un desafío especial a las parejas cada Día de la Corona de la Luna.",
  ui_story_5040_50400302_28_dialog_content = "Pero...",
  ui_story_5040_50400302_29_dialog_content = "¿Pero que? ¿Hay algún problema?",
  ui_story_5040_50400302_30_dialog_content = "Somos viejos amigos. Recuerdo verlos a usted y al Sr. Novio muy a menudo cuando estaba estudiando con la reina en el Palacio de Invierno.",
  ui_story_5040_50400302_31_dialog_content = "Y es por eso que espero que tu elección de enfrentar los desafíos de la vida con Tara haya sido considerada, por encima de todo.",
  ui_story_5040_50400302_32_dialog_content = "El Día de la Corona de la Luna, los eventos de la Unión de Mensajeros, cualquier otra cosa... Son todos superficiales.",
  ui_story_5040_50400302_33_dialog_content = "Si entiendo.",
  ui_story_5040_50400302_34_dialog_content = "Te apoyaré, si deseas aprovechar esta oportunidad.",
  ui_story_5040_50400302_35_dialog_content = "¡Gracias, Naroxel!",
  ui_story_5040_50400302_36_dialog_content = "En cuanto al evento del Día de la Corona de Luna...",
  ui_story_5040_50400302_37_dialog_content = "Este es un libro de estampillas conmemorativas especiales, emitidas por Courier Union para celebrar el Día de la Corona de Luna de este año. Véndelos todos y pasarás la prueba.",
  ui_story_5040_50400302_38_dialog_content = "¡Eso será fácil! ¿Verdad, Tara?",
  ui_story_5040_50400302_39_dialog_content = "Probablemente.",
  ui_story_5040_50400302_40_dialog_content = "Pero nunca antes había hecho un trabajo tan complicado.",
  ui_story_5040_50400302_41_dialog_content = "Si trabajamos juntos, no tendremos ningún problema. ¡Vamos! Empecemos.",
  ui_story_5040_50400302_42_dialog_content = "¡Buena suerte!",
  ui_story_5040_50400302_43_dialog_content = "Gracias, PlayerName. Y tú también, Jeriah.",
  ui_story_5040_50400302_44_dialog_content = "Pero parece que tienen la intención de ir a otras divisiones de Courier Union. ¿Puedo molestarte en escoltarlos unas cuantas veces más? PlayerName?",
  ui_story_5040_50400302_45_dialog_content = "¡Seguro! Cualquier cosa que pueda hacer para ayudar.",
  ui_story_5040_50400302_46_dialog_content = "Ve a descansar un poco primero, sin embargo.",
  ui_story_5040_50400302_47_dialog_content = "Los acompañaré durante los desafíos.",
  ui_story_5040_50400302_48_dialog_content = "¿Si pudiera tener una palabra, Jeriah?",
  ui_story_5040_50400302_49_dialog_content = "...",
  ui_story_5040_50400302_50_dialog_content = "¿Hay algo que quieras decirme?",
  ui_story_5040_50400302_51_dialog_content = "Jeje... ¿Te refieres a algo en particular?",
  ui_story_5040_50400302_52_dialog_content = "Ahora, no te hagas el tonto conmigo. ¿Sabes qué había en todos esos paquetes enviados a Lumopolis desde Rediesel?",
  ui_story_5040_50400302_53_dialog_content = "Hm, me pregunto? Realmente no revisé.",
  ui_story_5040_50400302_54_dialog_content = "¿Cómo pudiste reenviarlos sin verificar...? Eho y yo ya tenemos mucho en nuestros platos.",
  ui_story_5040_50400302_55_dialog_content = "Incluso antes del festival, las cosas se estaban acumulando, pero ahora el Sindicato de Mensajeros de Lumopolis está realmente desesperado.",
  ui_story_5040_50400302_56_dialog_content = "No le dije a ningún superior sobre esto, de lo contrario, estoy bastante seguro de que tendrías que enfrentarte a una conferencia cuando volvieras.",
  ui_story_5040_50400302_57_dialog_content = "Así que te debo una. Pero es por eso que he estado corriendo por Northland para ti.",
  ui_story_5040_50400302_58_dialog_content = "Suspiro, nunca esperé que algo así le pasara a Adonis.",
  ui_story_5040_50400302_59_dialog_content = "Hazme un favor y sigue ayudándolos.",
  ui_story_5040_50400302_60_dialog_content = "Qué molestia... y no tengo idea de por qué están tan decididos a encadenarse cuando claramente no son una buena pareja.",
  ui_story_5040_50400302_61_dialog_content = "¿No dices a menudo que cada individuo es complicado?",
  ui_story_5040_50400302_62_dialog_content = "Lo entenderás algún día, Jeriah. Nadie va por la vida solo para siempre.",
  ui_story_5040_50400302_63_dialog_content = "Aquí están los sellos que necesitamos repartir, Tara.",
  ui_story_5040_50400302_64_dialog_content = "Solías enviarme la estampilla del Día de la Corona de la Luna todos los años, ¿recuerdas? Salvé a todos y cada uno de ellos.",
  ui_story_5040_50400302_65_dialog_content = "¿En realidad? no recuerdo",
  ui_story_5040_50400302_66_dialog_content = "Eso está bien. ¡De ahora en adelante, seré yo quien te los dé! ¿No es genial el diseño de este año?",
  ui_story_5040_50400302_67_dialog_content = "¡Ay...! ¡El embalaje!",
  ui_story_5040_50400302_68_dialog_content = "¡Cuidado!",
  ui_story_5040_50400302_69_dialog_content = "Menos mal que no se cayó al suelo.",
  ui_story_5040_50400302_70_dialog_content = "Te dije que no era bueno en este tipo de trabajo delicado. Vender armamento y esas cosas, ahora eso está más en mi callejón.",
  ui_story_5040_50400302_71_dialog_content = "Es totalmente normal que las personas tengan diferentes talentos. Ningún individuo es igual.",
  ui_story_5040_50400302_72_dialog_content = "No se preocupe por embolsar la mercancía. Yo me ocuparé de eso, tú te encargas de los clientes.",
  ui_story_5040_50400302_73_dialog_content = "Debería ser capaz de hacer eso, al menos.",
  ui_story_5040_50400302_74_dialog_content = "<color=#e8d9bb>Un rato después ...</color>",
  ui_story_5040_50400302_75_dialog_content = "¿Podría también tener algunos de los sellos conmemorativos de este año, por favor?",
  ui_story_5040_50400302_76_dialog_content = "¿Cómo es que los míos todavía no están listos?",
  ui_story_5040_50400302_77_dialog_content = "Por favor, no te preocupes. Los sellos del Día de la Corona de la Luna son especiales, por lo que debemos asegurarnos de que estén perfectamente presentados y bien envueltos. ¿No estás de acuerdo?",
  ui_story_5040_50400302_78_dialog_content = "¡Aquí estás!",
  ui_story_5040_50400302_79_dialog_content = "¿Estás bien allí, Tara?",
  ui_story_5040_50400302_80_dialog_content = "Creo que deberías preocuparte más por los sellos que estás manejando. Sólo estoy hablando, después de todo.",
  ui_story_5040_50400302_81_dialog_content = "Parece que el negocio va bien por aquí.",
  ui_story_5040_50400302_82_dialog_content = "¡Sí! Ha sido bastante suave hasta ahora.",
  ui_story_5040_50400302_83_dialog_content = "Déjame ver... ¡no queda mucho! Las felicitaciones están en orden.",
  ui_story_5040_50400302_84_dialog_content = "¡Sí! El último se vendió, ¡hemos terminado!",
  ui_story_5040_50400302_85_dialog_content = "Uf, eso fue un trabajo duro.",
  ui_story_5040_50400302_86_dialog_content = "Bien hecho a los dos.",
  ui_story_5040_50400302_87_dialog_content = "Al menos podrías pretender sonar un poco más sincero.",
  ui_story_5040_50400302_88_dialog_content = "*Bostezo* Disculpe, ¿está vendiendo esos sellos de Courier Union aquí?",
  ui_story_5040_50400302_89_dialog_content = "Sí, pero desafortunadamente nos acabamos de vender.",
  ui_story_5040_50400302_90_dialog_content = "Son super lindos este año, pero no vine aquí a comprar sellos.",
  ui_story_5040_50400302_91_dialog_content = "Me preguntaba si tenía alguna de las estampillas del Día de la Corona de la Luna del año pasado por ahí. Si lo haces... pagaré una prima por ellos.",
  ui_story_5040_50400302_92_dialog_content = "Oh...",
  ui_story_5040_50400302_93_dialog_content = "Solo somos ayuda temporal. Jeria, ¿sabes?",
  ui_story_5040_50400302_94_dialog_content = "Esas estampillas de Courier Union son todas ediciones limitadas y no mantenemos copias de seguridad.",
  ui_story_5040_50400302_95_dialog_content = "Me temo que no podrá obtener ninguno de los canales oficiales.",
  ui_story_5040_50400302_96_dialog_content = "Ah, claro. Que voy a hacer...?",
  ui_story_5040_50400302_97_dialog_content = "Lo que parece ser el problema?",
  ui_story_5040_50400302_98_dialog_content = "Eh... Honestamente, un amigo me pidió que los consiguiera.",
  ui_story_5040_50400302_99_dialog_content = "Envía sellos del Día de la Corona de la Luna a su socio en Illumina todos los años.",
  ui_story_5040_50400302_100_dialog_content = "Sin embargo, su familia es un poco conservadora y se opone rotundamente a su relación.",
  ui_story_5040_50400302_101_dialog_content = "Por eso me pidió que le comprara los sellos y la papelería en secreto.",
  ui_story_5040_50400302_102_dialog_content = "¡Decir ah! Que muy Lumopolis.",
  ui_story_5040_50400302_103_dialog_content = "¿Eh? ¿Es costumbre en Lumopolis dar sellos?",
  ui_story_5040_50400302_104_dialog_content = "Las parejas de Lumopolis se las envían el Día de la Corona de Luna, pero creo que los nobles tienen prácticas más extravagantes.",
  ui_story_5040_50400302_105_dialog_content = "En efecto. Prefiero acurrucarme en la cama para dormir que participar en esta farsa.",
  ui_story_5040_50400302_106_dialog_content = "Pero el problema es que su pareja perdió los sellos conmemorativos del año pasado...",
  ui_story_5040_50400302_107_dialog_content = "Se sentía tan culpable y triste por eso. Mi amigo no podía soportar verla tan alterada, así que me pidió que le buscara otra copia de esos sellos.",
  ui_story_5040_50400302_108_dialog_content = "Son solo sellos. ¿No puede conseguirle algo más?",
  ui_story_5040_50400302_109_dialog_content = "¡No es lo mismo en absoluto! No puedes simplemente reemplazar algo que está lleno de recuerdos compartidos con otra cosa.",
  ui_story_5040_50400302_110_dialog_content = "Un noble Lumo y una chica Illuminan... Interesante.",
  ui_story_5040_50400302_111_dialog_content = "Deben encontrar todo tipo de obstáculos en su relación.",
  ui_story_5040_50400302_112_dialog_content = "Bueno, todavía hay luz al final del túnel para ellos. Pero supongo que se podría decir que tienen un camino rocoso por delante.",
  ui_story_5040_50400302_113_dialog_content = "Ha estado trabajando lentamente para convencer a sus padres y otros parientes, tratando de convencerlos.",
  ui_story_5040_50400302_114_dialog_content = "Sin embargo, probablemente todavía llevará algún tiempo.",
  ui_story_5040_50400302_115_dialog_content = "Lumopolis realmente hace honor a su reputación como un lugar donde las familias se obsesionan con casarse dentro de su clase.",
  ui_story_5040_50400302_116_dialog_content = "¿Sí? Si me preguntas, ni siquiera dos personas de familias nobles tienen automáticamente garantizada la felicidad juntos.",
  ui_story_5040_50400302_117_dialog_content = "El Salón de Justicia donde trabajo recibe peticiones de divorcio de los nobles todo el tiempo.",
  ui_story_5040_50400302_118_dialog_content = "Cada caso tiene sus propios giros extraños, y nunca son claros, gracias a la disputa de intereses entre los nobles.",
  ui_story_5040_50400302_119_dialog_content = "Todo el mundo trata de evitar tomar esos casos.",
  ui_story_5040_50400302_120_dialog_content = "Así que incluso los nobles pueden tener problemas en el paraíso...",
  ui_story_5040_50400302_121_dialog_content = "¡Ay, seguro! Así que mi consejo es siempre seguir tu corazón.",
  ui_story_5040_50400302_122_dialog_content = "Después de todo, incluso conformarse con alguien de estatus similar no garantiza la felicidad.",
  ui_story_5040_50400302_123_dialog_content = "¡Qué raro es escuchar tales palabras de la boca del noble Lumopolis!",
  ui_story_5040_50400302_124_dialog_content = "Solo puedo decir que cada uno toma sus propias decisiones. Los sentimientos no se pueden controlar. El amor es el amor.",
  ui_story_5040_50400302_125_dialog_content = "Enamorarse de alguien no es algo que cualquiera pueda controlar. No importa quiénes sean o de dónde sean.",
  ui_story_5040_50400302_126_dialog_content = "Lo sé muy bien.",
  ui_story_5040_50400302_127_dialog_content = "Bien dicho de hecho! ¡Estoy totalmente de acuerdo!",
  ui_story_5040_50400302_128_dialog_content = "¿Oh? ¿Puede que tengas a alguien en mente?",
  ui_story_5040_50400302_129_dialog_content = "No... Es solo que conocí a un pequeño tan divertido y borroso hace un tiempo.",
  ui_story_5040_50400302_130_dialog_content = "¡También podría hablar Universese! No podía creerlo.",
  ui_story_5040_50400302_131_dialog_content = "De hecho, le envié una carta ayer. Sin embargo, no sé cuándo podría recibir una respuesta.",
  ui_story_5040_50400302_132_dialog_content = "¿Realmente no hay nada que podamos hacer para ayudar a su amigo, Jeriah?",
  ui_story_5040_50400302_133_dialog_content = "...",
  ui_story_5040_50400302_134_dialog_content = "Bueno, en realidad no lo sé, pero...",
  ui_story_5040_50400302_135_dialog_content = "Si está dispuesto a pagar, podría ser una buena idea invitar a Allura a Umbraton. Ella tiene bastante la colección.",
  ui_story_5040_50400302_136_dialog_content = "Estoy seguro de que una cosa tan pequeña no sería un problema.",
  ui_story_5040_50400302_137_dialog_content = "¡Veo! ¡Muchas gracias por su ayuda!",
  ui_story_5040_50400302_138_dialog_content = "Bien podría ir a Umbraton ahora, mientras aún no tengo sueño.",
  ui_story_5040_50400302_139_dialog_content = "Eres como una enciclopedia ambulante, Jeriah.",
  ui_story_5040_50400302_140_dialog_content = "Espero que encuentre lo que está buscando.",
  ui_story_5040_50400302_141_dialog_content = "De cualquier manera, ¡hemos completado la tarea! ¡Vamos a buscar ese sello!",
  ui_story_5040_50400302_142_dialog_content = "Seguro...",
  ui_story_5040_50400302_143_dialog_content = "¿Qué pasa, Tara? ¿Se siente bien?",
  ui_story_5040_50400302_144_dialog_content = "No es nada, estoy bien.",
  ui_story_5040_50400302_145_dialog_content = "...",
  ui_story_5040_50400302_146_dialog_content = "<color=#e8d9bb>Mientras tanto...</color>",
  ui_story_5040_50400302_147_dialog_content = "Nada en absoluto...?",
  ui_story_5040_50400302_148_dialog_content = "¿Todavía no recuerdas nada?",
  ui_story_5040_50400302_149_dialog_content = "No... Nada... Lo siento...",
  ui_story_5040_50400302_150_dialog_content = "No necesitas disculparte, no has hecho nada malo.",
  ui_story_5040_50400302_151_dialog_content = "¿Qué más podría darnos una pista...?",
  ui_story_5040_50400302_152_dialog_content = "Ah... Eso...",
  ui_story_5040_50400302_153_dialog_content = "¿Qué?",
  ui_story_5040_50400302_154_dialog_content = "Sosteniendo... en... la mano...",
  ui_story_5040_50400302_155_dialog_content = "¿OMS? Sosteniendo que?",
  ui_story_5040_50400302_156_dialog_content = "A él...",
  ui_story_5040_50400302_157_dialog_content = "Sellos...",
  ui_story_5040_50400302_158_dialog_content = "Sellos?? ¿Ese tipo que acaba de pasar? Sí, tenía esas estampillas del Día de la Corona de la Luna.",
  ui_story_5040_50400302_159_dialog_content = "¿Te recuerdan a algo?",
  ui_story_5040_50400302_160_dialog_content = "Parece... si...",
  ui_story_5040_50400302_161_dialog_content = "¿Eh? ¿De dónde sacaste esto? ¡Todos estos parecen ser viejos sellos del Día de la Corona de la Luna!",
  ui_story_5040_50400302_162_dialog_content = "Piensa... tengo... muchos...",
  ui_story_5040_50400302_163_dialog_content = "¿Cuántos qué? Sellos como este?",
  ui_story_5040_50400302_164_dialog_content = "Si...",
  ui_story_5040_50400302_165_dialog_content = "Por lo general, cuando las personas tienen muchas estampillas, significa que envían mucho correo, ¿no?",
  ui_story_5040_50400302_166_dialog_content = "¡Eso me da una idea! ¿Por qué no te llevo a echar un vistazo al correo no reclamado de la Unión? Quizás encontremos algo.",
  ui_story_5040_50400302_167_dialog_content = "Gracias... Kya...",
  ui_story_5040_50400302_168_dialog_content = "<color=#e8d9bb>Un rato después ...</color>",
  ui_story_5040_50400302_169_dialog_content = "¿Nada?",
  ui_story_5040_50400302_170_dialog_content = "No...",
  ui_story_5040_50400302_171_dialog_content = "Mmm. Bueno, tal vez estabas en una región de la Unión diferente a la de Lumopolis.",
  ui_story_5040_50400302_172_dialog_content = "Sin embargo, al menos ahora tenemos una pista. Es mejor que simplemente deambular sin rumbo fijo como antes.",
  ui_story_5040_50400302_173_dialog_content = "Vamos a etiquetar junto con PlayerName y los demás y verifique las divisiones Illumina y Rediesel Wrench.",
  ui_story_5040_50400302_174_dialog_content = "no te preocupes ¡Lo encontraremos!",
  ui_story_5040_50400302_175_dialog_content = "K... Kya...",
  ui_story_5040_50400302_176_dialog_content = "Gracias...",
  ui_story_5040_50400302_177_dialog_content = "¿Por qué tú... me ayudas...?",
  ui_story_5040_50400302_178_dialog_content = "Realmente no me conozco a mí mismo. Tal vez simplemente no puedo pasar cuando alguien necesita ayuda.",
  ui_story_5040_50400302_179_dialog_content = "(¡Debo estar loco ayudando a un Eclipsite! ¡¿Qué diablos estoy pensando?!)",
  ui_story_5040_50400302_180_dialog_content = "(¿Qué haría Esmeralda?)",
  ui_story_5040_50400401_1_dialog_content = "<color=#e8d9bb>Después de que Adonis y los demás informaran a Naroxel...</color>",
  ui_story_5040_50400401_2_dialog_content = "¿Así que este es el sello de plumas de Courier Union? Nunca he visto uno antes.",
  ui_story_5040_50400401_3_dialog_content = "¡Se ve tan bien hecho!",
  ui_story_5040_50400401_4_dialog_content = "¡Ven a ver, Tara!",
  ui_story_5040_50400401_5_dialog_content = "... No actúes de repente como si fuéramos tan íntimos o algo así.",
  ui_story_5040_50400401_6_dialog_content = "Las focas de plumas son en su mayoría objetos conmemorativos. Tienen muy poco valor monetario por sí mismos.",
  ui_story_5040_50400401_7_dialog_content = "Incluso antes de que existiera la Unión, los correos eran bienvenidos como portadores de buenas noticias dondequiera que fueran.",
  ui_story_5040_50400401_8_dialog_content = "¿Los nobles también contrataban mensajeros para bodas?",
  ui_story_5040_50400401_9_dialog_content = "Sí, pero especialmente los nobles de Lumopolis. De hecho, muchos gastarían extravagantemente para contratar mensajeros que sirvieran como testigos en sus bodas.",
  ui_story_5040_50400401_10_dialog_content = "Esta es también la razón por la cual el Sindicato de Mensajeros buscó eliminar gradualmente esta tradición con algo más.",
  ui_story_5040_50400401_11_dialog_content = "Especialmente en Lumópolis. El Día de la Corona de Luna se originó aquí, por lo que la gente aquí se toma en serio sus tradiciones.",
  ui_story_5040_50400401_12_dialog_content = "Qué montón de bichos raros. No celebramos fiestas sin sentido como estas en el desierto.",
  ui_story_5040_50400401_13_dialog_content = "¿Qué hay de malo en observar las vacaciones? Además, este es tan romántico.",
  ui_story_5040_50400401_14_dialog_content = "En Lumopolis, donde toda la sociedad está tan fuertemente estratificada, este tipo de formalidades son solo un medio para controlar a las clases bajas.",
  ui_story_5040_50400401_15_dialog_content = "Esta, a su vez, es la razón por la cual se enfatiza tanto su importancia.",
  ui_story_5040_50400401_16_dialog_content = "Eso es mucho para asimilar...",
  ui_story_5040_50400401_17_dialog_content = "Ella siempre habla de cosas que no puedo entender.",
  ui_story_5040_50400401_18_dialog_content = "Entonces, ¿qué debemos hacer saber?",
  ui_story_5040_50400401_19_dialog_content = "Jeriah, vamos a dar un paseo. Necesito dejar de pensar en cosas.",
  ui_story_5040_50400401_20_dialog_content = "Entonces iré con—",
  ui_story_5040_50400401_21_dialog_content = "PlayerName, ¿qué tal si te asocias con él por el momento? Necesito un poco de paz y tranquilidad en este momento.",
  ui_story_5040_50400401_22_dialog_content = "Claro, eso funciona.",
  ui_story_5040_50400401_23_dialog_content = "...",
  ui_story_5040_50400401_24_dialog_content = "Suspiro...",
  ui_story_5040_50400401_25_dialog_content = "¿Estás cansado de tu pequeño acto?",
  ui_story_5040_50400401_26_dialog_content = "Yo sólo... No sé si estoy haciendo lo correcto. Adonis realmente parece creer que perdí mis recuerdos.",
  ui_story_5040_50400401_27_dialog_content = "Estoy tan en conflicto. Antes, cuando vendíamos sellos juntos, sentía que seguía siendo la misma persona amable y gentil que siempre había conocido.",
  ui_story_5040_50400401_28_dialog_content = "Pero eso no resuelve todos los problemas entre nosotros. Sé que en cuanto suceda algo grande, volverá a ser un cobarde.",
  ui_story_5040_50400401_29_dialog_content = "Tal vez realmente somos demasiado diferentes para estar juntos.",
  ui_story_5040_50400401_30_dialog_content = "Excepto que como me gusta tanto, es difícil para mí aceptar ese hecho.",
  ui_story_5040_50400401_31_dialog_content = "Podemos elegir convertirnos en quien queramos, pero no podemos obligar a los demás a ser quienes queremos que sean.",
  ui_story_5040_50400401_32_dialog_content = "Cuando eliges estar con alguien, tienes que aceptar todo lo que viene después.",
  ui_story_5040_50400401_33_dialog_content = "Cuanto más amas a alguien, más doloroso es dejarlo ir.",
  ui_story_5040_50400401_34_dialog_content = "... ¿Hablas por experiencia?",
  ui_story_5040_50400401_35_dialog_content = "Por supuesto que no. ¿Por qué me sometería a sabiendas a ese tipo de dolor?",
  ui_story_5040_50400401_36_dialog_content = "Aún así, estar con él me trajo mucha alegría. La mayor parte del tiempo que pasamos juntos fue feliz.",
  ui_story_5040_50400401_37_dialog_content = "Simplemente podría estar proyectando debido a que se siente inseguro acerca de su relación. Al final, las relaciones se tratan de intercambiar valores.",
  ui_story_5040_50400401_38_dialog_content = "Y en este momento, lo que está ofreciendo no está cumpliendo con sus expectativas. ¿No es así?",
  ui_story_5040_50400401_39_dialog_content = "Yo...",
  ui_story_5040_50400401_40_dialog_content = "No sé... No quiero ver nuestra relación así, como si no fuera más que una transacción.",
  ui_story_5040_50400401_41_dialog_content = "Lo que digas.",
  ui_story_5040_50400401_42_dialog_content = "Necesitamos experiencia para saber lo que realmente queremos en el fondo. Dado que las cosas ya están donde están ahora, no me preocuparía demasiado.",
  ui_story_5040_50400401_43_dialog_content = "Este es su negocio, después de todo. Lo que digan los demás no importa.",
  ui_story_5040_50400401_44_dialog_content = "Tómate todo el tiempo que necesites para resolverlo y escucha a tu corazón cuando finalmente tomes una decisión.",
  ui_story_5040_50400401_45_dialog_content = "...",
  ui_story_5040_50400401_46_dialog_content = "¡Bienvenido a Umbratón! Se siente muy diferente de Lumopolis, ¿eh?",
  ui_story_5040_50400401_47_dialog_content = "Sí...",
  ui_story_5040_50400401_48_dialog_content = "¿Ves esa isla flotando justo encima de nosotros? Eso es Lumópolis.",
  ui_story_5040_50400401_49_dialog_content = "Para muchas personas en Umbraton, estas vacaciones son la oportunidad perfecta para obtener ganancias.",
  ui_story_5040_50400401_50_dialog_content = "Hay mucha gente extraña aquí, pero también hay muchas cosas fascinantes e interesantes.",
  ui_story_5040_50400401_51_dialog_content = "¿Algo que te interese revisar?",
  ui_story_5040_50400401_52_dialog_content = "...",
  ui_story_5040_50400401_53_dialog_content = "(Se acabó... Parece haber perdido toda su energía.)",
  ui_story_5040_50400401_54_dialog_content = "Suspiro... Simplemente ya no sé qué hacer.",
  ui_story_5040_50400401_55_dialog_content = "Nada de lo que hago está bien... ¡Si ella me diera una pista! Entonces tal vez sabría qué hacer...",
  ui_story_5040_50400401_56_dialog_content = "Er...",
  ui_story_5040_50400401_57_dialog_content = "Solíamos hablar de todo, especialmente cuando se trataba de las cosas que no entendíamos sobre nuestro mundo. Pero ahora... ¿cómo han terminado así las cosas?",
  ui_story_5040_50400401_58_dialog_content = "PlayerName, eres un caelestita, debes tener chicas haciendo fila afuera de tu puerta principal. ¿Entiendes por lo que estoy pasando?",
  ui_story_5040_50400401_59_dialog_content = "U-Uh, eso es un poco exagerado.",
  ui_story_5040_50400401_60_dialog_content = "Pero creo que mientras los sentimientos mutuos de dos personas sean lo suficientemente fuertes, pueden superar cualquier dificultad.",
  ui_story_5040_50400401_61_dialog_content = "Mis dos buenos amigos y yo hemos pasado por muchas cosas juntos. ¡Incluso nos hemos rescatado unos a otros de las puertas de la muerte unas cuantas veces!",
  ui_story_5040_50400401_62_dialog_content = "Pero todas esas experiencias fortalecieron nuestra confianza mutua. Estamos dispuestos a hacer cualquier cosa el uno por el otro, incluso si eso significa ponernos en peligro.",
  ui_story_5040_50400401_63_dialog_content = "Estoy seguro de que tú y Tara sois iguales.",
  ui_story_5040_50400401_64_dialog_content = "¡O-Por supuesto que haría cualquier cosa por ella! ¡Incluso arriesgaría mi vida, si tuviera que hacerlo!",
  ui_story_5040_50400401_65_dialog_content = "Es solo que a veces soy tan indeciso... No puedo tomar decisiones en una fracción de segundo como otras personas. Esa podría ser la razón por la que ella piensa que me falta como hombre...",
  ui_story_5040_50400401_66_dialog_content = "¡No digas eso, Adonis! ¿Quién dice que un hombre tiene que ser de una forma u otra? Todos somos diferentes, y eso está bien.",
  ui_story_5040_50400401_67_dialog_content = "Nadie es perfecto, pero si todavía están juntos... ¡Eso significa que hay algo en ti que ella encuentra lo suficientemente atractivo como para quedarse!",
  ui_story_5040_50400401_68_dialog_content = "*Sollozando* Yo... ¡Solo espero que ella realmente se sienta así!",
  ui_story_5040_50400401_69_dialog_content = "Ahí, ahí, no llores...",
  ui_story_5040_50400401_70_dialog_content = "¡Oooooh!",
  ui_story_5040_50400401_71_dialog_content = "¿Estamos interrumpiendo un momento hermoso y elegante?",
  ui_story_5040_50400401_72_dialog_content = "¡Gin, me siento tan inspirada!",
  ui_story_5040_50400401_73_dialog_content = "Esclavizados por las expectativas de la sociedad, dos amantes que no pueden verse juntos—",
  ui_story_5040_50400401_74_dialog_content = "Claramente se están abrazando a plena luz del día.",
  ui_story_5040_50400401_75_dialog_content = "A pesar de que es el Día de la Corona de la Luna, los dos amantes no tienen más remedio que encontrarse en un rincón apartado de Umbraton, lejos de miradas indiscretas.",
  ui_story_5040_50400401_76_dialog_content = "Hay gente por todas partes...",
  ui_story_5040_50400401_77_dialog_content = "¿No es esto lo más hermoso que has visto, Gin? ¡Quiero hacer todo lo que esté a mi alcance para ayudarlos! ¡Y tal vez gane algo para mí, mientras estoy en eso!",
  ui_story_5040_50400401_78_dialog_content = "Eso suena como una idea maravillosa.",
  ui_story_5040_50400401_79_dialog_content = "Er, creo que estás malinterpretando—",
  ui_story_5040_50400401_80_dialog_content = "Admiro tu coraje, mi hombre. ¿Puedo preguntarte cómo te llamas?",
  ui_story_5040_50400401_81_dialog_content = "¿M-Yo? Mi nombre es Adonis...",
  ui_story_5040_50400401_82_dialog_content = "Tienes un aire de grandeza sobre ti, Adonis. Uno que te pone muy por encima de los demás, especialmente de ese tipo a tu lado.",
  ui_story_5040_50400401_83_dialog_content = "¡¿Por qué me disparas de repente?!",
  ui_story_5040_50400401_84_dialog_content = "Debes ser del tipo que haría cualquier cosa por amor. Puedo decirlo con solo mirarte.",
  ui_story_5040_50400401_85_dialog_content = "Mi piruleta también se siente de la misma manera.",
  ui_story_5040_50400401_86_dialog_content = "Pero prescindamos de la charla trivial innecesaria. Para el Día de la Corona de la Luna de este año, tenemos a la venta una pintura muy rara, una que creo que se adapta perfectamente a ti.",
  ui_story_5040_50400401_87_dialog_content = "Representa la trágica historia de un amor prohibido entre dos amantes desafortunados...",
  ui_story_5040_50400401_88_dialog_content = "Esta rara y hermosa pintura puede ser tuya por un precio muy razonable, ¡pero solo por hoy!",
  ui_story_5040_50400401_89_dialog_content = "¿Cómo? I...",
  ui_story_5040_50400401_90_dialog_content = "¡Ah ah ah! ¡Ni una palabra más! ¡Está claro como el día que simplemente te mueres por comprar esta pintura!",
  ui_story_5040_50400401_91_dialog_content = "Estoy de acuerdo.",
  ui_story_5040_50400401_92_dialog_content = "Yo...",
  ui_story_5040_50400401_93_dialog_content = "¡Ya basta, ustedes dos!",
  ui_story_5040_50400401_94_dialog_content = "¡No arruines su primera vez aquí en Umbraton!",
  ui_story_5040_50400401_95_dialog_content = "Por favor, solo estamos tratando de ganarnos la vida aquí. Solo estábamos realizando una transacción razonable con este buen caballero, nada más.",
  ui_story_5040_50400401_96_dialog_content = "¡¡No había nada razonable al respecto!!",
  ui_story_5040_50400401_97_dialog_content = "Me encantaría demostrar que te equivocas... pero creo que acabo de escuchar algo.",
  ui_story_5040_50400401_98_dialog_content = "<size=45>Aaaah!!</size>",
  ui_story_5040_50400401_99_dialog_content = "¡¿Qué ocurre?!",
  ui_story_5040_50400401_100_dialog_content = "EE-Eclipsitos!",
  ui_story_5040_50400401_101_dialog_content = "¡¿Qué están haciendo los eclipses aquí?!",
  ui_story_5040_50400401_102_dialog_content = "<size=45>Graah!</size>",
  ui_story_5040_50400401_103_dialog_content = "Ponerse en el camino de mi negocio, qué molesto.",
  ui_story_5040_50400401_104_dialog_content = "E-Eclipsitos!",
  ui_story_5040_50400401_105_dialog_content = "¡Cúbrete, Adonis! ¡Encontraremos una manera de manejar esto!",
  ui_story_5040_50400402_1_dialog_content = "... Hombre, esos dos no perdieron un segundo, ¿verdad?",
  ui_story_5040_50400402_2_dialog_content = "¿Estás bien, Adonis?",
  ui_story_5040_50400402_3_dialog_content = "S-Sí, estoy bien.",
  ui_story_5040_50400402_4_dialog_content = "Perdón por ser tan inútil... Solo la vista de esos Eclipsites hizo que mis piernas se aflojaran debajo de mí.",
  ui_story_5040_50400402_5_dialog_content = "No te preocupes por eso. La mayoría de la gente no está acostumbrada a luchar contra esos monstruos.",
  ui_story_5040_50400402_6_dialog_content = "Al menos Hachi y Gin se han escapado. Son imposibles.",
  ui_story_5040_50400402_7_dialog_content = "Esos tipos tienden a buscar los objetivos más fáciles, así que recuerda rechazarlos sin rodeos la próxima vez que te encuentres con ellos.",
  ui_story_5040_50400402_8_dialog_content = "Suspiro... ¿Por qué siempre soy así?",
  ui_story_5040_50400402_9_dialog_content = "Disculpe, pero ¿no estaba vendiendo sellos del Día de la Corona de la Luna antes?",
  ui_story_5040_50400402_10_dialog_content = "¿Ah?",
  ui_story_5040_50400402_11_dialog_content = "¿Estás hablando de Adonis? Estuvo con Tara y Jeriah de Courier Union antes.",
  ui_story_5040_50400402_12_dialog_content = "Ah, entonces ese es tu nombre.",
  ui_story_5040_50400402_13_dialog_content = "Y usted es...?",
  ui_story_5040_50400402_14_dialog_content = "¡Saludos! Mi nombre es Tina y soy jueza del Salón de Justicia de Lumo. Por favor, disculpe por olvidar presentarme antes.",
  ui_story_5040_50400402_15_dialog_content = "Encantado de conocerte, Tina. Soy PlayerName.",
  ui_story_5040_50400402_16_dialog_content = "Acabo de preguntarles a esos amigos suyos sobre las estampillas del Día de la Corona de la Luna del año pasado esta mañana.",
  ui_story_5040_50400402_17_dialog_content = "Gracias a ese mensajero, encontré lo que buscaba aquí en Umbraton.",
  ui_story_5040_50400402_18_dialog_content = "¿En realidad? Todo es gracias a Jeriah... Me alegro de que haya podido ayudar, considerando que yo no pude hacer nada.",
  ui_story_5040_50400402_19_dialog_content = "En cualquier caso, estoy seguro de que tu amigo y su amante están felices de que hayas podido encontrar el sello del año pasado.",
  ui_story_5040_50400402_20_dialog_content = "Estás absolutamente en lo correcto. Prácticamente saltaba de alegría cuando se lo di.",
  ui_story_5040_50400402_21_dialog_content = "Me agradeció una y otra vez antes de finalmente correr a casa lo más rápido que pudo para escribir su carta de amor.",
  ui_story_5040_50400402_22_dialog_content = "El comerciante del que lo obtuve tenía muchos artículos interesantes. Estaba en camino a ver más de sus productos cuando me encontré con ustedes dos.",
  ui_story_5040_50400402_23_dialog_content = "... ¿Se siente bien, señor? Te ves un poco pálido... ¿Pasó algo?",
  ui_story_5040_50400402_24_dialog_content = "En realidad yo...",
  ui_story_5040_50400402_25_dialog_content = "Ah... ¡Ya veo! ¡No es de extrañar que sintiera que había algo extraño entre ustedes dos!",
  ui_story_5040_50400402_26_dialog_content = "Así que vas a Illumina, ¿sí? En ese caso, ¿podría preguntarle a la amante de mi amiga si conoce una cura?",
  ui_story_5040_50400402_27_dialog_content = "¿E-Eh?",
  ui_story_5040_50400402_28_dialog_content = "Seré sincero contigo. Trabaja para los Laboratorios Black Umbrella en Gannon City.",
  ui_story_5040_50400402_29_dialog_content = "Si existe un remedio, ¡su conocimiento podría resultarle útil! Solo menciónale mi nombre y ella te ayudará en lo que pueda.",
  ui_story_5040_50400402_30_dialog_content = "No puedo garantizar que tenga las respuestas que buscas, pero referirte a ella es lo mínimo que puedo hacer por ti.",
  ui_story_5040_50400402_31_dialog_content = "¡Eso es más que suficiente! ¡Muchas gracias, señorita Tina!",
  ui_story_5040_50400402_32_dialog_content = "¡Nos aseguraremos de visitarla una vez que estemos allí!",
  ui_story_5040_50400402_33_dialog_content = "¿Ves, Adonis? ¡Aún hay esperanza para ustedes!",
  ui_story_5040_50400402_34_dialog_content = "Le deseo un buen viaje y la mejor de las suertes en su viaje.",
  ui_story_5040_50400402_35_dialog_content = "Yaaaaawn... Empiezo a sentirme un poco cansado. Creo que es hora de ir a casa y descansar un poco...",
  ui_story_5040_50400402_36_dialog_content = "Parece que tu determinación finalmente está comenzando a dar sus frutos, Adonis. Visitaremos a esa dama tan pronto como lleguemos a Gannon City.",
  ui_story_5040_50400402_37_dialog_content = "¡Sí! Gracias de nuevo, PlayerName.",
  ui_story_5040_50400402_38_dialog_content = "<color=#e8d9bb>Esa noche...</color>",
  ui_story_5040_50400402_39_dialog_content = "Suspiro... Este lugar tampoco funcionó, ¿eh?",
  ui_story_5040_50400402_40_dialog_content = "Estoy haciendo mi mejor esfuerzo...",
  ui_story_5040_50400402_41_dialog_content = "Lo siento, no quise estresarte. Sin presiones, tómate todo el tiempo que necesites.",
  ui_story_5040_50400402_42_dialog_content = "Deberíamos regresar, de todos modos. Creo que hemos recorrido suficiente terreno en Umbraton por hoy.",
  ui_story_5040_50400402_43_dialog_content = "Es más seguro en Lumopolis por la noche.",
  ui_story_5040_50400402_44_dialog_content = "Umbra... ton... Lumo... polis...",
  ui_story_5040_50400402_45_dialog_content = "Lumópolis...",
  ui_story_5040_50400402_46_dialog_content = "¿Qué pasa? ¿Por qué estás tan obsesionado con Lumopolis?",
  ui_story_5040_50400402_47_dialog_content = "¿Recordaste algo?",
  ui_story_5040_50400402_48_dialog_content = "Lumópolis... Un largo viaje...",
  ui_story_5040_50400402_49_dialog_content = "Vine aquí... para encontrarme con alguien...",
  ui_story_5040_50400402_50_dialog_content = "Pero quién...? ¿Con quién prometí encontrarme... en Lumopolis...?",
  ui_story_5040_50400402_51_dialog_content = "Él... Él nunca vino...",
  ui_story_5040_50400402_52_dialog_content = "¿Qué? ¿Quieres decir que una vez viniste a Lumopolis desde otro lugar?",
  ui_story_5040_50400402_53_dialog_content = "Sí... yo... lo siento...",
  ui_story_5040_50400402_54_dialog_content = "Eso significa que no eres de por aquí. ¿Recuerdas de dónde vienes?",
  ui_story_5040_50400402_55_dialog_content = "Creo que... muy, muy lejos...",
  ui_story_5040_50400402_56_dialog_content = "Un lugar lejano, ¿eh? Veo...",
  ui_story_5040_50400402_57_dialog_content = "Está bien, no te excedas. Como no eres de Lumopolis, tendremos que ir a otro lado y seguir buscando.",
  ui_story_5040_50400402_58_dialog_content = "Creo PlayerName y los demás van mañana a la ciudad de Gannon. Vamos a etiquetarnos con ellos.",
  ui_story_5040_50400402_59_dialog_content = "Tal vez la Unión de Mensajeros de allí nos dé algunas respuestas.",
  ui_story_5040_50400402_60_dialog_content = "Bien...",
  ui_story_5040_50400402_61_dialog_content = "<color=#e8d9bb>El siguiente día...</color>",
  ui_story_5040_50400402_62_dialog_content = "Muy bien, ¿están todos listos? ¡No olvides nada de lo que puedas necesitar!",
  ui_story_5040_50400402_63_dialog_content = "Jejeje... No he estado en Illumina en mucho tiempo. Me pregunto cómo estarán esos pajaritos.",
  ui_story_5040_50400402_64_dialog_content = "Por favor, no les provoques más problemas, Jeriah.",
  ui_story_5040_50400402_65_dialog_content = "Se supone que la Federación Illumina es una nación altamente militarizada, ¿verdad? Tara me lo contó todo antes... ¡Siempre quise verlo por mí mismo!",
  ui_story_5040_50400402_66_dialog_content = "Estoy bastante interesado en ver sus últimos modelos de camiones.",
  ui_story_5040_50400402_67_dialog_content = "Entonces, ¡vamos!",
  ui_story_5040_50400502_1_dialog_content = "Guau... ¡Así que esto es la ciudad de Gannon!",
  ui_story_5040_50400502_2_dialog_content = "Yo solo he estado aquí una vez.",
  ui_story_5040_50400502_3_dialog_content = "Nunca parece cambiar mucho, ¿verdad?",
  ui_story_5040_50400502_4_dialog_content = "¿Vienes a Illumina a menudo, PlayerName?",
  ui_story_5040_50400502_5_dialog_content = "No, realmente no. Es que uno de mis amigos más cercanos es de aquí, así que vinimos aquí un par de veces.",
  ui_story_5040_50400502_6_dialog_content = "Sin embargo, ahora mismo está de vacaciones. No creo que tengamos la oportunidad de verla hoy.",
  ui_story_5040_50400502_7_dialog_content = "¿Gannon City no celebra el Día de la Corona de la Luna o algo así? No hay una sola decoración a la vista por aquí...",
  ui_story_5040_50400502_8_dialog_content = "Por supuesto que sí, y es igual de importante para ellos también.",
  ui_story_5040_50400502_9_dialog_content = "Diferentes lugares tienen sus propias formas de observar las vacaciones. La Federación Illumina no le da tanta importancia a la pompa, eso es todo.",
  ui_story_5040_50400502_10_dialog_content = "La gente aquí tiende a ser más pragmática y reservada cuando se trata de exhibiciones públicas. Para esta festividad en particular, la mayoría de las damas ofrecen rollos de canela hechos a mano a la persona que les gusta.",
  ui_story_5040_50400502_11_dialog_content = "Los hombres, por otro lado, pintan un pequeño corazón en el interior de sus mangas y escriben en él el nombre de la persona que aman.",
  ui_story_5040_50400502_12_dialog_content = "Eso suena un poco lindo, en realidad.",
  ui_story_5040_50400502_13_dialog_content = "¡Y romántico! ¡Yo también quiero hacerlo!",
  ui_story_5040_50400502_14_dialog_content = "Hey...",
  ui_story_5040_50400502_15_dialog_content = "Seguro que sabes mucho sobre el mundo, Jeriah.",
  ui_story_5040_50400502_16_dialog_content = "Escuché que Jeriah ha viajado a muchos lugares antes, pero rara vez parece mencionarlo.",
  ui_story_5040_50400502_17_dialog_content = "Oh, eso es toda la historia antigua. Ahora bien, si no me equivoco, esa persona de allí...",
  ui_story_5040_50400502_18_dialog_content = "?!?",
  ui_story_5040_50400502_19_dialog_content = "Ese debe ser el pajarito de Illumina.",
  ui_story_5040_50400502_20_dialog_content = "¿Paloma? ¿No deberías estar entregando cartas ahora mismo?",
  ui_story_5040_50400502_21_dialog_content = "Mm, sí, eso es lo que estoy haciendo. No me divertiría solo porque es un día festivo.",
  ui_story_5040_50400502_22_dialog_content = "Solo estoy trabajando a mi propio ritmo, eso es todo.",
  ui_story_5040_50400502_23_dialog_content = "Suenas completamente increíble...",
  ui_story_5040_50400502_24_dialog_content = "Así que eres la famosa Paloma, ¿eh? He oído hablar de ti... aunque no puedo decir que nada de eso haya sido positivo.",
  ui_story_5040_50400502_25_dialog_content = "¿Como pudiste decir eso? ¡Trabajo muy duro! No es mi culpa que haya miles de millones de cartas para entregar durante estas vacaciones.",
  ui_story_5040_50400502_26_dialog_content = "Es imposible entregarlos a todos, realmente me altera las plumas, ¡coo!",
  ui_story_5040_50400502_27_dialog_content = "Entonces, ¿decidiste holgazanear por completo?",
  ui_story_5040_50400502_28_dialog_content = "No importa eso por ahora. ¿Sabes algo sobre el Sello de Plumas del Día de la Corona de Luna?",
  ui_story_5040_50400502_29_dialog_content = "¿El sello de plumas? lo tengo encima",
  ui_story_5040_50400502_30_dialog_content = "¡¿Eh?!",
  ui_story_5040_50400502_31_dialog_content = "Todos mis superiores están tan ocupados haciendo entregas en este momento que me dejaron a cargo de vigilarlo.",
  ui_story_5040_50400502_32_dialog_content = "Suena más como si no tuvieran más remedio que trabajar horas extras porque cierta persona no está haciendo su propio esfuerzo...",
  ui_story_5040_50400502_33_dialog_content = "¡Arrullo! ¡¿Que se supone que significa eso?!",
  ui_story_5040_50400502_34_dialog_content = "A-De todos modos, solo queríamos obtener un sello de Feather Seal del Courier Union of Illumina. Somos una pareja, ya ves...",
  ui_story_5040_50400502_35_dialog_content = "Ah, ya veo.",
  ui_story_5040_50400502_36_dialog_content = "Eso es fácil, solo encárgate del resto de mis entregas por mí.",
  ui_story_5040_50400502_37_dialog_content = "... ¿Eso está permitido?",
  ui_story_5040_50400502_38_dialog_content = "Bueno, soy el único aquí, y también tengo el sello de plumas... Así que básicamente, puedo hacer lo que quiera.",
  ui_story_5040_50400502_39_dialog_content = "Lo siento mucho, pero sería genial si estuvieras dispuesto a ayudarme.",
  ui_story_5040_50400502_40_dialog_content = "¡Lo haremos! ¡Déjanoslo a nosotros!",
  ui_story_5040_50400502_41_dialog_content = "<color=#e8d9bb>Quince minutos después—</color>",
  ui_story_5040_50400502_42_dialog_content = "...",
  ui_story_5040_50400502_43_dialog_content = "...",
  ui_story_5040_50400502_44_dialog_content = "...",
  ui_story_5040_50400502_45_dialog_content = "Eso es un montón de cosas para entregar.",
  ui_story_5040_50400502_46_dialog_content = "\"Solo unos cuantos paquetes más\", ¡mi pie! ¡¿Cómo se las arregló para meter todos estos aquí?!",
  ui_story_5040_50400502_47_dialog_content = "Es imposible que los dos entreguemos todo esto, incluso si trabajáramos sin descanso durante tres días seguidos...",
  ui_story_5040_50400502_48_dialog_content = "Lo siento... No pensé que serían tantos.",
  ui_story_5040_50400502_49_dialog_content = "Supongo que no tenemos elección, chicos. Empecemos...",
  ui_story_5040_50400502_50_dialog_content = "Yo también ayudaré y aprovecharé la oportunidad para traer a Sable por la ciudad.",
  ui_story_5040_50400502_51_dialog_content = "Lo siento... Parece que te volvimos a arrastrar a nuestros propios problemas.",
  ui_story_5040_50400502_52_dialog_content = "Manejaremos la mayor parte de las entregas. Soy bastante bueno en el trabajo físico.",
  ui_story_5040_50400502_53_dialog_content = "Estaré aquí relajándome con mi libro, animando a que se hayan ido.",
  ui_story_5040_50400502_54_dialog_content = "Jeriah... Suspiro, supongo que es probablemente para mejor. No necesitamos que las cosas empeoren más de lo que ya están...",
  ui_story_5040_50400502_55_dialog_content = "¡Está bien! ¡Empecemos, todos!",
  ui_story_5040_50400502_56_dialog_content = "¡Ahhhh!",
  ui_story_5040_50400502_57_dialog_content = "¡Oye, date prisa, Adonis!",
  ui_story_5040_50400502_58_dialog_content = "¡Yo... lo siento! Estas escaleras son tan empinadas...",
  ui_story_5040_50400502_59_dialog_content = "¡Ten un poco más de cuidado, entonces!",
  ui_story_5040_50400502_60_dialog_content = "Aquí, detengámonos y ordenemos nuestras entregas. Tú tomas los más cercanos y yo me encargo de los más lejanos.",
  ui_story_5040_50400502_61_dialog_content = "De ninguna manera, hay demasiado para que lo manejes solo.",
  ui_story_5040_50400502_62_dialog_content = "No te preocupes, estoy acostumbrado a correr así. Hará que las entregas pasen mucho más rápido, confía en mí.",
  ui_story_5040_50400502_63_dialog_content = "Ah, okey.",
  ui_story_5040_50400502_64_dialog_content = "¡D-Entrega para ti, Vivian!",
  ui_story_5040_50400502_65_dialog_content = "Oh mi, si no lo es PlayerName! ¿No sueles estar con V—?",
  ui_story_5040_50400502_66_dialog_content = "Sí, sí. ¡Aquí está tu paquete, hasta luego!",
  ui_story_5040_50400502_67_dialog_content = "Pero, ¿por qué estás entregando correo en primer lugar?",
  ui_story_5040_50400502_68_dialog_content = "... Dove, tu revisión de desempeño va a ser un desastre.",
  ui_story_5040_50400502_69_dialog_content = "¡Hola! ¡Por favor firme esta carta y que tenga un buen día!",
  ui_story_5040_50400502_70_dialog_content = "Lindo. Eso se encarga de las entregas para este piso.",
  ui_story_5040_50400502_71_dialog_content = "Kya... es increíble...",
  ui_story_5040_50400502_72_dialog_content = "¡No precisamente! ¡Soy un mensajero, después de todo!",
  ui_story_5040_50400502_73_dialog_content = "Solo recuerda decirme si ves algo que te refresque la memoria, ¿de acuerdo?",
  ui_story_5040_50400502_74_dialog_content = "<color=#e8d9bb>Unas pocas horas después-</color>",
  ui_story_5040_50400502_75_dialog_content = "Yo... estoy en mi límite...",
  ui_story_5040_50400502_76_dialog_content = "*Jadeo* PlayerName... ¿Ha terminado con sus entregas?",
  ui_story_5040_50400502_77_dialog_content = "Sí... Finalmente...",
  ui_story_5040_50400502_78_dialog_content = "Sé que tuvimos que cubrir mucho terreno, pero ustedes realmente tienen una resistencia mediocre.",
  ui_story_5040_50400502_79_dialog_content = "¡Buen trabajo, todos! Parece que nuestro trabajo aquí está hecho.",
  ui_story_5040_50400502_80_dialog_content = "¿Kya no ha vuelto todavía?",
  ui_story_5040_50400502_81_dialog_content = "Oh, no te preocupes por ella. Terminó sus entregas hace un rato. Los birdies de Northland son los más eficientes.",
  ui_story_5040_50400502_82_dialog_content = "Ella debe estar mostrándole a su amiguita los lugares de interés de Gannon City ahora mismo.",
  ui_story_5040_50400502_83_dialog_content = "¡Ja ja! Sabía que lo tenías en ti, PlayerName!",
  ui_story_5040_50400502_84_dialog_content = "D-Paloma? ¡¿Has estado dando vueltas por aquí todo este tiempo?!",
  ui_story_5040_50400502_85_dialog_content = "\"Pasando el rato\"? Estoy trabajando muy duro en este momento.",
  ui_story_5040_50400502_86_dialog_content = "¿Podemos tener un sello ahora que terminamos el trabajo?",
  ui_story_5040_50400502_87_dialog_content = "Claro, acércate. ¡He aquí el sello de plumas!",
  ui_story_5040_50400502_88_dialog_content = "¡Ta-da!",
  ui_story_5040_50400502_89_dialog_content = "Hah... ¡Ahora también tenemos el sello de Illumina!",
  ui_story_5040_50400502_90_dialog_content = "Sigo sin ver el sentido de todo esto...",
  ui_story_5040_50400502_91_dialog_content = "¡N-No digas eso! Nuestras pequeñas aventuras nos han ido acercando más, ¿no crees?",
  ui_story_5040_50400502_92_dialog_content = "¡¿D-Dice quién?!",
  ui_story_5040_50400502_93_dialog_content = "Ahora que tenemos el sello de plumas de Illumina, ¿hacia dónde vamos ahora?",
  ui_story_5040_50400502_94_dialog_content = "No venimos a Gannon City todos los días. ¡Vamos a probar algo de la comida local y tal vez a ver una película!",
  ui_story_5040_50400502_95_dialog_content = "¡Eso debería ponernos a todos en el espíritu navideño!",
  ui_story_5040_50400502_96_dialog_content = "Sin embargo, podemos comer la comida de Illumina cuando queramos.",
  ui_story_5040_50400502_97_dialog_content = "Mientras entregaba cartas, escuché que un cargamento de rifles de energía cinética acababa de llegar de Entrañas. Quiero ir a verlos descargar esas armas.",
  ui_story_5040_50400502_98_dialog_content = "¿Quieres ir a ver armas el Día de la Corona de Luna? Eso no es muy romántico...",
  ui_story_5040_50400502_99_dialog_content = "Si no quieres ir, siempre puedo ir solo.",
  ui_story_5040_50400502_100_dialog_content = "Yo...",
  ui_story_5040_50400502_101_dialog_content = "Cálmense ustedes dos. Todavía hay un asunto muy importante que atender.",
  ui_story_5040_50400502_102_dialog_content = "¿O ambos han olvidado la razón por la que vinimos aquí en primer lugar?",
  ui_story_5040_50400502_103_dialog_content = "¡Oh sí! ¡Aún tenemos que ir a preguntarle a esa señora de los Laboratorios Black Umbrella sobre la amnesia de Tara!",
  ui_story_5040_50400502_104_dialog_content = "Oh, cierto...",
  ui_story_5040_50400502_105_dialog_content = "...",
  ui_story_5040_50400502_106_dialog_content = "Acabemos con eso antes de que oscurezca. Vamos.",
  ui_story_5040_50400601_1_dialog_content = "(Realmente ha pasado demasiado tiempo.)",
  ui_story_5040_50400601_2_dialog_content = "... Y es por eso que estamos aquí hoy. Lo siento por todos los problemas.",
  ui_story_5040_50400601_3_dialog_content = "¡No es ningún problema en absoluto! ¡Después de todo, le debo tanto a la señorita Tina, como a todos ustedes!",
  ui_story_5040_50400601_4_dialog_content = "Lumopolis e Illumina siempre han tenido sus diferencias, lo que nos ha puesto las cosas muy difíciles a los dos.",
  ui_story_5040_50400601_5_dialog_content = "¡Pero hemos tenido la suerte de contar con la compañía de personas como Miss Tina que nos apoyan!",
  ui_story_5040_50400601_6_dialog_content = "A pesar de ser miembro de la clase noble, siempre ha apoyado nuestro amor.",
  ui_story_5040_50400601_7_dialog_content = "Por lo que entiendo, su cuerpo requiere mucho sueño para poder funcionar correctamente. A pesar de su condición, todavía hizo todo lo posible para encontrar ese sello para nosotros.",
  ui_story_5040_50400601_8_dialog_content = "Sí, no se puede negar que es una persona increíble.",
  ui_story_5040_50400601_9_dialog_content = "Siempre tan amable y educada.",
  ui_story_5040_50400601_10_dialog_content = "Pero sé que ella tiene suficientes problemas con los que lidiar. Escuché que su trabajo en el Salón de Justicia es... interesante, por decir lo menos.",
  ui_story_5040_50400601_11_dialog_content = "No tengo ni idea de cuándo tendremos la oportunidad de volver a vernos. Ojalá supiera más sobre ella.",
  ui_story_5040_50400601_12_dialog_content = "Pero según ella, parece que tú y tu amado ya lo tienen bastante difícil.",
  ui_story_5040_50400601_13_dialog_content = "Sí. ¿Por qué no se han fugado ustedes dos?",
  ui_story_5040_50400601_14_dialog_content = "Porque ambos tenemos cosas que debemos hacer. Puede que seamos amantes, pero nuestras propias responsabilidades siempre serán lo primero.",
  ui_story_5040_50400601_15_dialog_content = "Él y yo tenemos un fuerte sentido del deber, que probablemente sea la razón por la que nos sentimos atraídos el uno por el otro en primer lugar.",
  ui_story_5040_50400601_16_dialog_content = "Si dos personas son completamente sinceras consigo mismas y entre sí, cosas como la distancia se vuelven triviales. Después de todo, nuestros corazones siempre están juntos.",
  ui_story_5040_50400601_17_dialog_content = "Sus corazones... ¿siempre están juntos?",
  ui_story_5040_50400601_18_dialog_content = "Yo también me siento de la misma manera. ¡Ningún problema es demasiado difícil de superar, siempre y cuando se amen!",
  ui_story_5040_50400601_19_dialog_content = "¡Jajaja! Ahora bien, realmente deberíamos volver al trabajo. Tu nombre es Tara, ¿verdad? Creo que entiendo tu dilema, más o menos.",
  ui_story_5040_50400601_20_dialog_content = "Desafortunadamente, solo soy un interno en este momento, pero déjame preguntarle a mis colegas y ver qué piensan. Un momento por favor.",
  ui_story_5040_50400601_21_dialog_content = "¡Gracias de nuevo!",
  ui_story_5040_50400601_22_dialog_content = "<size=33>Jeriah... No creerás que se darán cuenta de que solo estoy fingiendo, ¿verdad?</size>",
  ui_story_5040_50400601_23_dialog_content = "¿No sería mejor sincerarse en este punto?",
  ui_story_5040_50400601_24_dialog_content = "<size=33>¡De ninguna manera! ¡Nunca podría mostrar mi rostro entre los demás si lo hiciera!</size>",
  ui_story_5040_50400601_25_dialog_content = "¿No pensaste en eso cuando se te ocurrió esta loca idea?",
  ui_story_5040_50400601_26_dialog_content = "<size=33>De todos modos, si el secreto sale a la luz, realmente necesitaré que me ayudes a apagar el fuego.</size>",
  ui_story_5040_50400601_27_dialog_content = "...",
  ui_story_5040_50400601_28_dialog_content = "(Sabía que ella solo estaba fingiendo todo este tiempo... Supongo que fingiré que no sé nada).",
  ui_story_5040_50400601_29_dialog_content = "¿De qué están hablando ustedes dos?",
  ui_story_5040_50400601_30_dialog_content = "¡Nada! ¡Solo decíamos lo increíble que se ve este laboratorio!",
  ui_story_5040_50400601_31_dialog_content = "Bueno, sí... Migard está a cargo de este lugar, y está en un nivel totalmente diferente.",
  ui_story_5040_50400601_32_dialog_content = "¿Tara? ¿Por qué estás temblando?",
  ui_story_5040_50400601_33_dialog_content = "¡Oh, sólo está un poco resfriada!",
  ui_story_5040_50400601_34_dialog_content = "¿En realidad? Aquí no se siente mucho frío...",
  ui_story_5040_50400601_35_dialog_content = "¡Lamento haberte hecho esperar! Si todos me siguieran, me gustaría presentarles a uno de los investigadores principales aquí.",
  ui_story_5040_50400601_36_dialog_content = "¡Guía el camino!",
  ui_story_5040_50400601_37_dialog_content = "¿Jola? Esta es Tara, la joven que mencioné antes. Parece que actualmente sufre de un caso de amnesia.",
  ui_story_5040_50400601_38_dialog_content = "¡Apreciaríamos cualquier ayuda que nos puedas brindar!",
  ui_story_5040_50400601_39_dialog_content = "¡Estoy más que feliz de echar una mano! Es lo menos que puedo hacer, después de todo lo que has hecho por mi colega.",
  ui_story_5040_50400601_40_dialog_content = "Ahora bien, señorita Tara... ¿Le importaría si la examino de cerca?",
  ui_story_5040_50400601_41_dialog_content = "G-Adelante...",
  ui_story_5040_50400601_42_dialog_content = "Qué pena que Migard no esté aquí hoy. No soy un experto en estos asuntos, pero aún así haré mi mejor esfuerzo.",
  ui_story_5040_50400601_43_dialog_content = "(¡Gracias a dios!)",
  ui_story_5040_50400601_44_dialog_content = "Hmm... A primera vista, nada parece estar fuera de lo común. Tendremos que realizar una serie de pruebas para determinar el estado de su cuerpo.",
  ui_story_5040_50400601_45_dialog_content = "¿Q-Qué tipo de pruebas...?",
  ui_story_5040_50400601_46_dialog_content = "(Su sonrisa parece siniestra...)",
  ui_story_5040_50400601_47_dialog_content = "¡No te preocupes! Un pequeño pellizco aquí, un pequeño tirón allá, ¡y terminará antes de que te des cuenta!",
  ui_story_5040_50400601_48_dialog_content = "¡Graaah!",
  ui_story_5040_50400601_49_dialog_content = "Oh no...",
  ui_story_5040_50400602_1_dialog_content = "¡Ey! ¡No dijiste nada sobre el uso de Eclipsites para ejecutar tus pruebas!",
  ui_story_5040_50400602_2_dialog_content = "¡¡Una pequeña advertencia hubiera estado bien, ya sabes!!",
  ui_story_5040_50400602_3_dialog_content = "Mis disculpas a todos. ¡Honestamente, no esperaba que te opusieras tanto a mis métodos!",
  ui_story_5040_50400602_4_dialog_content = "Después de todo, ustedes son un grupo bastante peculiar. Un habitante del norte, un habitante del desierto, un mensajero demihumano... y, por supuesto, el último caelestita del mundo.",
  ui_story_5040_50400602_5_dialog_content = "Eso no es relevante en absoluto. ¡Estamos aquí para ayudar a que Tara se mejore!",
  ui_story_5040_50400602_6_dialog_content = "Entonces, ¿qué me pasa exactamente?",
  ui_story_5040_50400602_7_dialog_content = "Bueno, por lo que he visto, pareces estar en perfecta salud física.",
  ui_story_5040_50400602_8_dialog_content = "... ¿Es asi? Entonces, ¿qué más podemos hacer?",
  ui_story_5040_50400602_9_dialog_content = "¿Qué más me puede decir sobre su enfermedad? ¿Sabes qué pudo haberlo causado?",
  ui_story_5040_50400602_10_dialog_content = "Déjame ver... Todo comenzó con esa poción mágica. El psíquico que me lo vendió dijo que estaba hecho con un ingrediente muy especial.",
  ui_story_5040_50400602_11_dialog_content = "Algo sobre un gusano de arena rosa gigante en el desierto de Rediesel... ¿Supongo que se supone que es una criatura extremadamente rara?",
  ui_story_5040_50400602_12_dialog_content = "¿Dijiste... un gusano de arena rosa?",
  ui_story_5040_50400602_13_dialog_content = "¿Sí?",
  ui_story_5040_50400602_14_dialog_content = "Jola, ¿qué sabes tú al respecto?",
  ui_story_5040_50400602_15_dialog_content = "...",
  ui_story_5040_50400602_16_dialog_content = "No puedo creer que el legendario gusano de arena rosa se haya mostrado de nuevo...",
  ui_story_5040_50400602_17_dialog_content = "<size=33>¡¿Qué?! ¡Eso es imposible!</size>",
  ui_story_5040_50400602_18_dialog_content = "<size=33>¿Tara?</size>",
  ui_story_5040_50400602_19_dialog_content = "<size=33>¡Tengo en mis manos la escama rosada del gusano de arena hace mucho tiempo! ¡¿Cómo un psíquico consiguió uno también?!</size>",
  ui_story_5040_50400602_20_dialog_content = "<size=33>Si este gusano de arena rosa realmente existe, ¿realmente es tan sorprendente saber que alguien más tiene una de sus escamas?</size>",
  ui_story_5040_50400602_21_dialog_content = "<size=33>Lo es porque, hasta donde yo sé, ¡solo una escama de gusano de arena rosa ha estado disponible en todo el mercado! Entonces, ¿cómo podría haber otro de repente?</size>",
  ui_story_5040_50400602_22_dialog_content = "Mi experiencia radica en el campo de la botánica. Un día, mientras buscaba una espora en particular, Migard me mencionó el gusano de arena rosa.",
  ui_story_5040_50400602_23_dialog_content = "Esta espora no ha sido investigada en su mayoría a lo largo de los años y solo se menciona en los libros. La razón de esto es que solo crece en las escamas del extremadamente raro gusano de arena rosa.",
  ui_story_5040_50400602_24_dialog_content = "Migard mencionó que hubo informes de testigos presenciales de esta criatura, pero muy pocos han podido probar sus afirmaciones.",
  ui_story_5040_50400602_25_dialog_content = "Es más agresivo que el gusano de arena normal, por lo que es difícil que alguien se acerque a él. Sus escamas son un ingrediente extremadamente raro y precioso. De hecho, creo que solo hay una única báscula disponible en todo el mercado.",
  ui_story_5040_50400602_26_dialog_content = "Si me trajeras una de estas escamas, tal vez podría intentar elaborar una cura.",
  ui_story_5040_50400602_27_dialog_content = "Más allá de eso, me temo que no tengo otras soluciones que ofrecerte.",
  ui_story_5040_50400602_28_dialog_content = "...",
  ui_story_5040_50400602_29_dialog_content = "...",
  ui_story_5040_50400602_30_dialog_content = "Entonces parece que nuestro objetivo ha quedado muy claro para nosotros.",
  ui_story_5040_50400602_31_dialog_content = "¿Jerías?",
  ui_story_5040_50400602_32_dialog_content = "Teniendo en cuenta que nuestro próximo destino es Rediesel Wrench, y yo soy el jefe del Sindicato de Mensajeros allí... entonces haré que conseguir una de esas escamas de gusano de arena rosa sea la prueba de Feather Seal.",
  ui_story_5040_50400602_33_dialog_content = "Oye, ¿hablas en serio?",
  ui_story_5040_50400602_34_dialog_content = "Parece que solo unas pocas personas han visto esta cosa... Nunca he oído hablar de ella a pesar de haber vivido en el desierto toda mi vida. ¿Tiene?",
  ui_story_5040_50400602_35_dialog_content = "Nunca he oído hablar de eso tampoco.",
  ui_story_5040_50400602_36_dialog_content = "¡¿Entonces por qué diablos estás haciendo de este nuestro juicio?!",
  ui_story_5040_50400602_37_dialog_content = "¡Lo haré! Si existe la más mínima posibilidad de restaurar los recuerdos de Tara, estoy dispuesto a intentarlo.",
  ui_story_5040_50400602_38_dialog_content = "¿Ah?",
  ui_story_5040_50400602_39_dialog_content = "¡Adonis! ¡¿Has perdido la cabeza?!",
  ui_story_5040_50400602_40_dialog_content = "Para ser honesto, no me siento seguro en absoluto... porque sé que soy débil y tímido, ni siquiera puedo matar a los insectos en mi propia casa, y mucho menos a un gusano de arena gigante...",
  ui_story_5040_50400602_41_dialog_content = "Pero Tara terminó así por mi culpa, así que tengo que hacer algo al respecto.",
  ui_story_5040_50400602_42_dialog_content = "Sé que mi naturaleza tímida es lo que la frustró tanto en primer lugar... Por eso quiero cambiar.",
  ui_story_5040_50400602_43_dialog_content = "No puedo retroceder pase lo que pase.",
  ui_story_5040_50400602_44_dialog_content = "¡Ese fue un discurso realmente conmovedor!",
  ui_story_5040_50400602_45_dialog_content = "¡Adonis! Yo... En realidad, yo—",
  ui_story_5040_50400602_46_dialog_content = "Menudo discurso conmovedor, Adonis. Entonces, ¿crees que ahora puedes derrotar a este gusano de arena tú solo?",
  ui_story_5040_50400602_47_dialog_content = "¡Por supuesto que no! Necesitaré toda la ayuda que pueda obtener, ¡así que enséñame a pelear!",
  ui_story_5040_50400602_48_dialog_content = "¡Comienzame con Eclipsites si es necesario! ¡Haré lo que sea para ser más fuerte!",
  ui_story_5040_50400602_49_dialog_content = "¿Sabes siquiera pelear?",
  ui_story_5040_50400602_50_dialog_content = "Me parece recordar que tu padre dijo que una vez estudiaste Luminática con Novio... ¿Es así?",
  ui_story_5040_50400602_51_dialog_content = "¡Sí! De niño iba a la biblioteca todo el tiempo y el señor Novio me enseñaba mucho.",
  ui_story_5040_50400602_52_dialog_content = "Mi Luminatic puede no ser muy fuerte, pero tengo una comprensión bastante sólida de cómo usarla.",
  ui_story_5040_50400602_53_dialog_content = "Jejeje... ¡Bien!",
  ui_story_5040_50400602_54_dialog_content = "Jeriah, tu expresión me está asustando.",
  ui_story_5040_50400602_55_dialog_content = "Relájate, ¡todos estamos en el mismo equipo! No es como si fuera a torturarlo o algo así.",
  ui_story_5040_50400602_56_dialog_content = "Esto será fácil. Como tú mismo dijiste, podemos comenzar con Eclipsites...",
  ui_story_5040_50400602_57_dialog_content = "E-Espera... ¿En serio vas a hacerme luchar contra una de esas cosas?",
  ui_story_5040_50400602_58_dialog_content = "¡Oh, cielos, no! ¡Eso sería demasiado cruel! No... tengo una idea aún mejor.",
  ui_story_5040_50400602_59_dialog_content = "Ella es una oponente mucho más adecuada para ti.",
  ui_story_5040_50400701_1_dialog_content = "¿Cómo me llamaste aquí, Lady Jeriah?",
  ui_story_5040_50400701_2_dialog_content = "Jeriah, no querrás decir...",
  ui_story_5040_50400701_3_dialog_content = "Graah...?",
  ui_story_5040_50400701_4_dialog_content = "¡Jeje, sí! El amiguito de Kya es la pareja perfecta para él, ¿no crees? Todo en ella prácticamente grita \"Eclipsite\".",
  ui_story_5040_50400701_5_dialog_content = "¡Creo que sería una maravillosa compañera de entrenamiento para Adonis!",
  ui_story_5040_50400701_6_dialog_content = "Quiero decir, sé que Sable no se parece mucho a otros aurorianos... pero ¿no crees que llamarla Eclipsita es ir demasiado lejos?",
  ui_story_5040_50400701_7_dialog_content = "(Aún así, definitivamente está conectada a los Eclipsites de alguna manera).",
  ui_story_5040_50400701_8_dialog_content = "(Sin embargo, está con Kya y no ha causado ningún problema hasta ahora. Supongo que tendremos que esperar y ver).",
  ui_story_5040_50400701_9_dialog_content = "Sparring...?",
  ui_story_5040_50400701_10_dialog_content = "¡Ella no sabe pelear! ¿Qué pasa si ella se lastima?",
  ui_story_5040_50400701_11_dialog_content = "Relájate, en realidad no pelearán. Esto es solo para ayudar a Adonis a encontrar su coraje, eso es todo.",
  ui_story_5040_50400701_12_dialog_content = "Adonis, ¿qué te parece?",
  ui_story_5040_50400701_13_dialog_content = "P-Parece un poco grosero... pero si Sable está dispuesto a ayudar, estaría muy agradecido.",
  ui_story_5040_50400701_14_dialog_content = "Si tuviera que enfrentarme cara a cara con un Eclipsite en este momento, prácticamente me lo estaría sirviendo en bandeja de plata.",
  ui_story_5040_50400701_15_dialog_content = "Tampoco soy bueno con las Lumináticas, ya que rara vez las uso. Por lo general, solo confío en Tara para que me proteja.",
  ui_story_5040_50400701_16_dialog_content = "No tienes que hacer esto, Adonis. Todos tienen diferentes fortalezas y debilidades.",
  ui_story_5040_50400701_17_dialog_content = "Y ni siquiera pienso en la necesidad de protegerte como una carga.",
  ui_story_5040_50400701_18_dialog_content = "¿Tara?",
  ui_story_5040_50400701_19_dialog_content = "No... pase lo que pase, ¡tengo que hacer esto! Tengo que esforzarme para salir de mi zona de confort.",
  ui_story_5040_50400701_20_dialog_content = "¡Kya, Sable, por favor ayúdenme!",
  ui_story_5040_50400701_21_dialog_content = "Hm... Sable, ¿estás bien con esto?",
  ui_story_5040_50400701_22_dialog_content = "Si eso significa... Puedo ayudar...",
  ui_story_5040_50400701_23_dialog_content = "Entonces... ¡Lo haré!",
  ui_story_5040_50400701_24_dialog_content = "No te esfuerces, ¿de acuerdo? Es solo una pelea fingida, nada más.",
  ui_story_5040_50400701_25_dialog_content = "yo no...",
  ui_story_5040_50400701_26_dialog_content = "Estoy... feliz de ayudar...",
  ui_story_5040_50400701_27_dialog_content = "¡Eres el mejor, Sable!",
  ui_story_5040_50400701_28_dialog_content = "¡Graah! ¡¡Graaah !!",
  ui_story_5040_50400701_29_dialog_content = "¿Soy solo yo, o escuché un Eclipsite real...?",
  ui_story_5040_50400701_30_dialog_content = "¡¿Eh?!",
  ui_story_5040_50400701_31_dialog_content = "<size=45>Graaahh—!</size>",
  ui_story_5040_50400701_32_dialog_content = "¡Cuidado! ¡Hay eclipses aquí!",
  ui_story_5040_50400701_33_dialog_content = "¡¿P-Pero cómo?! ¡¿De dónde vinieron?!",
  ui_story_5040_50400701_34_dialog_content = "¿Dónde, de hecho? Tú y tu pajarito negro siempre parecen atraer a una multitud donde quiera que vayas...",
  ui_story_5040_50400701_35_dialog_content = "¿Podría realmente ser sólo una coincidencia?",
  ui_story_5040_50400701_36_dialog_content = "Mmm.",
  ui_story_5040_50400701_37_dialog_content = "(¿Sable realmente dibujó estos monstruos aquí...?)",
  ui_story_5040_50400701_38_dialog_content = "Eclip... sitios...?",
  ui_story_5040_50400701_39_dialog_content = "Enfocar. Eliminemos estas plagas ante todo.",
  ui_story_5040_50400701_40_dialog_content = "¡Ponte detrás de mí, Adonis!",
  ui_story_5040_50400701_41_dialog_content = "Yo sé.",
  ui_story_5040_50400702_1_dialog_content = "Parece que los tenemos todos. ¿Todos están bien?",
  ui_story_5040_50400702_2_dialog_content = "Por supuesto. Después de todo, solo fueron un par de eclipses.",
  ui_story_5040_50400702_3_dialog_content = "Yo también estoy bien.",
  ui_story_5040_50400702_4_dialog_content = "Eso es genial para vosotras, chicas, pero parece una historia diferente para esos dos de allí.",
  ui_story_5040_50400702_5_dialog_content = "¡Ah!",
  ui_story_5040_50400702_6_dialog_content = "S... tan aterrador...",
  ui_story_5040_50400702_7_dialog_content = "(Me pregunto cuán productivo es que esos dos se entrenen entre sí...)",
  ui_story_5040_50400702_8_dialog_content = "¿Deberíamos continuar con nuestro entrenamiento, o ustedes dos necesitan un descanso?",
  ui_story_5040_50400702_9_dialog_content = "¡Yo puedo seguir!",
  ui_story_5040_50400702_10_dialog_content = "M... ¡Yo también...!",
  ui_story_5040_50400702_11_dialog_content = "No te esfuerces, Sable.",
  ui_story_5040_50400702_12_dialog_content = "Ya que ambos se sienten valientes, continuemos.",
  ui_story_5040_50400702_13_dialog_content = "<color=#e8d9bb>15 minutos despues-</color>",
  ui_story_5040_50400702_14_dialog_content = "...",
  ui_story_5040_50400702_15_dialog_content = "...",
  ui_story_5040_50400702_16_dialog_content = "Uh... ¿vais a empezar pronto? Has estado parado por un tiempo ahora...",
  ui_story_5040_50400702_17_dialog_content = "¡Voy a atacar ahora!",
  ui_story_5040_50400702_18_dialog_content = "¡...!",
  ui_story_5040_50400702_19_dialog_content = "No pareces estar a punto de ir a la batalla en absoluto.",
  ui_story_5040_50400702_20_dialog_content = "¡Realmente lo haré! ¡Será mejor que estés listo!",
  ui_story_5040_50400702_21_dialog_content = "¡O-Está bien...!",
  ui_story_5040_50400702_22_dialog_content = "<color=#e8d9bb>Una hora después...</color>",
  ui_story_5040_50400702_23_dialog_content = "¡Esta vez, te juro que voy a atacar!",
  ui_story_5040_50400702_24_dialog_content = "¡Sólo mira!",
  ui_story_5040_50400702_25_dialog_content = "(Tengo tanto sueño, siento que podría ir a tomar una siesta ahora mismo).",
  ui_story_5040_50400702_26_dialog_content = "Como dije, Adonis, realmente no tienes que hacer esto.",
  ui_story_5040_50400702_27_dialog_content = "¡¡¡Vamos Sable!!!",
  ui_story_5040_50400702_28_dialog_content = "...",
  ui_story_5040_50400702_29_dialog_content = "¿De verdad crees que un Eclipsite se va a quedar quieto durante una hora y esperar a que lo ataques?",
  ui_story_5040_50400702_30_dialog_content = "Recuerda, estás haciendo esto por el bien de Tara.",
  ui_story_5040_50400702_31_dialog_content = "Si ella cayera en la batalla y un Eclipsite la tuviera en la mira, ¿dudarías así?",
  ui_story_5040_50400702_32_dialog_content = "No necesitas que te diga cuál sería el resultado de eso.",
  ui_story_5040_50400702_33_dialog_content = "Yo... Yo...",
  ui_story_5040_50400702_34_dialog_content = "¿O me estás diciendo que no te importa si ella sale lastimada, ya que no estás dispuesto a superar tu vacilación impulsada por la cobardía?",
  ui_story_5040_50400702_35_dialog_content = "¡E-Eso no es cierto en absoluto!",
  ui_story_5040_50400702_36_dialog_content = "Incluso un momento de vacilación podría significar la diferencia entre la vida y la muerte. ¿Quién querría estar con alguien tan poco confiable?",
  ui_story_5040_50400702_37_dialog_content = "<size=33>¡Ey! ¡Estás siendo demasiado duro con él!</size>",
  ui_story_5040_50400702_38_dialog_content = "<size=33>Me siento muy mal por él... Sable, ¿por qué no le das una mano?</size>",
  ui_story_5040_50400702_39_dialog_content = "<size=45>Grah! Graaaaah!</size>",
  ui_story_5040_50400702_40_dialog_content = "<size=55>¡¡¡Aaaahhh!!!</size>",
  ui_story_5040_50400702_41_dialog_content = "<color=#e8d9bb>¡Bonk...!</color>",
  ui_story_5040_50400702_42_dialog_content = "Haaah... Haaah...",
  ui_story_5040_50400702_43_dialog_content = "Ay...",
  ui_story_5040_50400702_44_dialog_content = "S-Sable! ¡¿Estás bien?!",
  ui_story_5040_50400702_45_dialog_content = "Estoy... estoy bien...",
  ui_story_5040_50400702_46_dialog_content = "¿Él realmente la atacó?",
  ui_story_5040_50400702_47_dialog_content = "¡Estás progresando, Adonis! ¡Al menos no te encogiste en la parte de atrás esta vez!",
  ui_story_5040_50400702_48_dialog_content = "Sin duda, fue el ataque menos dañino que he visto en mi vida, pero Caelestite tiene razón.",
  ui_story_5040_50400702_49_dialog_content = "Aún así, no obtendrá un éxito en un Eclipsite real en el corto plazo.",
  ui_story_5040_50400702_50_dialog_content = "¡Lo más importante es que está progresando! ¡Superarse a uno mismo siempre es el paso más difícil!",
  ui_story_5040_50400702_51_dialog_content = "Tara... ¡Gracias!",
  ui_story_5040_50400702_52_dialog_content = "*Sniff* ¡Muchas gracias a todos! ¡Especialmente tú, Sable!",
  ui_story_5040_50400702_53_dialog_content = "Está bien...",
  ui_story_5040_50400702_54_dialog_content = "Bien. Ahora que lo eliminamos, el verdadero entrenamiento puede comenzar.",
  ui_story_5040_50400702_55_dialog_content = "Creo que es suficiente por hoy, Jeriah. Se está haciendo bastante tarde, y estoy seguro de que todos están cansados.",
  ui_story_5040_50400702_56_dialog_content = "Podemos dar un paso a la vez. Volvamos a la ciudad por ahora.",
  ui_story_5040_50400702_57_dialog_content = "Si tú lo dices, pequeña Caelestite.",
  ui_story_5040_50400702_58_dialog_content = "Urgh...",
  ui_story_5040_50400702_59_dialog_content = "¿Eh? ¿Qué pasa, Sable? ¿Estás herido?",
  ui_story_5040_50400702_60_dialog_content = "No... No...",
  ui_story_5040_50400702_61_dialog_content = "Recuerdo...",
  ui_story_5040_50400702_62_dialog_content = "¡¿Eh?!",
  ui_story_5040_50400702_63_dialog_content = "Desierto... desierto...",
  ui_story_5040_50400702_64_dialog_content = "¿Como en el Desierto de Rediesel?",
  ui_story_5040_50400702_65_dialog_content = "no se... pero...",
  ui_story_5040_50400702_66_dialog_content = "Solo recuerdo... el desierto...",
  ui_story_5040_50400702_67_dialog_content = "¿Supongo que Adonis golpeando tu cabeza te refrescó la memoria?",
  ui_story_5040_50400702_68_dialog_content = "Bueno, el Desierto Rediesel es convenientemente nuestra próxima parada.",
  ui_story_5040_50400702_69_dialog_content = "...",
  ui_story_5040_50400702_70_dialog_content = "Todos se ven bastante agotados, así que demos por terminado el día y descansemos un poco.",
  ui_story_5040_50400702_71_dialog_content = "Todo por mi culpa. No sé cómo agradecerles a todos.",
  ui_story_5040_50400702_72_dialog_content = "Este era nuestro problema al principio, pero nos has estado apoyando todo este tiempo... Gracias.",
  ui_story_5040_50400702_73_dialog_content = "¿Por qué no vamos a comprar algunos refrigerios especiales de Illuminan para que todos demuestren nuestro aprecio, Tara? No hay mucho más que podamos hacer.",
  ui_story_5040_50400702_74_dialog_content = "Jaja, ¡ustedes realmente no tienen que hacer eso!",
  ui_story_5040_50400702_75_dialog_content = "(No estoy seguro de que las especialidades de Illumina sean adecuadas como bocadillos...)",
  ui_story_5040_50400702_76_dialog_content = "Es una gran idea. Pongámonos en marcha antes de que sea demasiado tarde.",
  ui_story_5040_50400702_77_dialog_content = "Yo quiero ir...",
  ui_story_5040_50400702_78_dialog_content = "Kya, me gustaría hablar contigo en privado. ¿Tienes un momento?",
  ui_story_5040_50400702_79_dialog_content = "¿Eh? Por qué de repente... sí, Lady Jeriah.",
  ui_story_5040_50400702_80_dialog_content = "¿Pero qué pasa con Sable...?",
  ui_story_5040_50400702_81_dialog_content = "No te preocupes por ella. Ella puede volver con PlayerName.",
  ui_story_5040_50400702_82_dialog_content = "¿A menos que haya algo sobre ella que debamos saber...?",
  ui_story_5040_50400702_83_dialog_content = "N... ¡Para nada!",
  ui_story_5040_50400702_84_dialog_content = "¿Te importaría llevarla de vuelta, PlayerName?",
  ui_story_5040_50400702_85_dialog_content = "¡Por supuesto que no! Vamos, Sablé.",
  ui_story_5040_50400702_86_dialog_content = "Em...",
  ui_story_5040_50400702_87_dialog_content = "¿Qué ocurre?",
  ui_story_5040_50400702_88_dialog_content = "Yo... necesito ir a algún lado...",
  ui_story_5040_50400702_89_dialog_content = "\"Ir a alguna parte\"?",
  ui_story_5040_50400702_90_dialog_content = "¿Todavía hay algún lugar al que quieras ir?",
  ui_story_5040_50400702_91_dialog_content = "Más temprano... recogí... una carta...",
  ui_story_5040_50400702_92_dialog_content = "Quiero... devolverlo...",
  ui_story_5040_50400702_93_dialog_content = "¿Cuándo encontraste una carta? ¿No deberíamos dejarlo en el Courier Union?",
  ui_story_5040_50400702_94_dialog_content = "Fue... después de... nuestro entrenamiento...",
  ui_story_5040_50400702_95_dialog_content = "Oh, ¿así que en algún lugar fuera de la ciudad? Un mensajero debe haberlo dejado caer por accidente.",
  ui_story_5040_50400702_96_dialog_content = "Podemos llevarlo al Sindicato de Mensajeros, ¿de acuerdo?",
  ui_story_5040_50400702_97_dialog_content = "Tiene... una dirección.",
  ui_story_5040_50400702_98_dialog_content = "Deben estar... esperando... mucho tiempo...",
  ui_story_5040_50400702_99_dialog_content = "Verdadero. Es el Día de la Corona de Luna, después de todo. ¿Quieres que llegue al destinatario más rápido, eh?",
  ui_story_5040_50400702_100_dialog_content = "Si Dove fuera la mitad de responsable que tú...",
  ui_story_5040_50400702_101_dialog_content = "Aquí, déjame echar un vistazo a la dirección. Te ayudaré a entregarlo.",
  ui_story_5040_50400702_102_dialog_content = "(Este sobre parece bastante viejo... Algo me dice que no se envió por correo recientemente).",
  ui_story_5040_50400702_103_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc!</color>",
  ui_story_5040_50400702_104_dialog_content = "Debería estar aquí.",
  ui_story_5040_50400702_105_dialog_content = "Sí, la dirección es correcta.",
  ui_story_5040_50400702_106_dialog_content = "¿Hola? ¿Puedo ayudarlo?",
  ui_story_5040_50400702_107_dialog_content = "Lamento molestarlo, pero encontramos esta carta en el suelo antes. Está dirigido a esta casa.",
  ui_story_5040_50400702_108_dialog_content = "¿Es eso así? ¿Puedo echar un vistazo?",
  ui_story_5040_50400702_109_dialog_content = "... ¡E-Esto no puede ser...!",
  ui_story_5040_50400702_110_dialog_content = "Esta es la dirección correcta, ¿verdad?",
  ui_story_5040_50400702_111_dialog_content = "¡¿Dónde exactamente ustedes dos encontraron esta carta?!",
  ui_story_5040_50400702_112_dialog_content = "Mi amigo lo encontró a las afueras de la ciudad. Ella insistió en entregártelo.",
  ui_story_5040_50400702_113_dialog_content = "¿Fui... útil...?",
  ui_story_5040_50400702_114_dialog_content = "No se que decir...",
  ui_story_5040_50400702_115_dialog_content = "Esta es una carta para mi abuela.",
  ui_story_5040_50400702_116_dialog_content = "¿Tu abuela?",
  ui_story_5040_50400702_117_dialog_content = "Esperó esta carta durante mucho tiempo, hasta el momento en que falleció.",
  ui_story_5040_50400702_118_dialog_content = "Es de su primer amor. Por lo que ella me dijo, vivía en Lumopolis. Pero debido a la distancia entre Illumina y allí, nunca terminaron juntos.",
  ui_story_5040_50400702_119_dialog_content = "Mi abuelo falleció hace mucho tiempo, por lo que mi abuela se reencontró con su primer amor.",
  ui_story_5040_50400702_120_dialog_content = "Se hicieron buenos amigos y siempre se enviaban cartas. Prometieron que los seguirían enviando hasta el final.",
  ui_story_5040_50400702_121_dialog_content = "Pero un día, sus cartas dejaron de llegar y, poco tiempo después, mi abuela se enfermó y falleció.",
  ui_story_5040_50400702_122_dialog_content = "Nunca pensé que él...",
  ui_story_5040_50400702_123_dialog_content = "Suspiro, el destino realmente hace tontos a los mortales.",
  ui_story_5040_50400702_124_dialog_content = "Y pensar que había tal historia detrás de esta carta...",
  ui_story_5040_50400702_125_dialog_content = "¡Sable, realmente hiciste algo increíble!",
  ui_story_5040_50400702_126_dialog_content = "¡Estoy muy agradecido! No abriré esta carta. Estaba destinado a mi abuela, así que lo dejaré junto a su tumba para que la acompañe.",
  ui_story_5040_50400702_127_dialog_content = "...",
  ui_story_5040_50400702_128_dialog_content = "Esto debe ser un milagro del Día de la Corona de la Luna... Solo espero que sus palabras aún logren llegar a ella.",
  ui_story_5040_50400702_129_dialog_content = "¿Es esto amor?",
  ui_story_5040_50400702_130_dialog_content = "Buena pregunta. A veces ni yo misma me entiendo. ¿Cómo es el amor tan poderoso?",
  ui_story_5040_50400702_131_dialog_content = "A veces lastima a la gente, a veces salva a la gente.",
  ui_story_5040_50400702_132_dialog_content = "En cualquier caso, ¿cómo podría pagarles a ustedes dos por esta amabilidad?",
  ui_story_5040_50400702_133_dialog_content = "No tienes que agradecerme nada. Gracias Sable aquí en su lugar.",
  ui_story_5040_50400702_134_dialog_content = "Esta bien...",
  ui_story_5040_50400702_135_dialog_content = "Parece que hemos terminado aquí. ¿Listo para volver ahora?",
  ui_story_5040_50400702_136_dialog_content = "Sí...",
  ui_story_5040_50400702_137_dialog_content = "<color=#e8d9bb>Mientras tanto, al otro lado de la ciudad...</color>",
  ui_story_5040_50400702_138_dialog_content = "¿Qué necesitabas discutir conmigo, Lady Jeriah?",
  ui_story_5040_50400702_139_dialog_content = "...",
  ui_story_5040_50400702_140_dialog_content = "Pajarito de Northland, despierta mi curiosidad por un momento. ¿De dónde sacaste a este pariente tuyo?",
  ui_story_5040_50400702_141_dialog_content = "¡¡!!",
  ui_story_5040_50400702_142_dialog_content = "¿Quieres decir... S-Sable?",
  ui_story_5040_50400702_143_dialog_content = "¿De quién más estaría hablando?",
  ui_story_5040_50400702_144_dialog_content = "Em...",
  ui_story_5040_50400702_145_dialog_content = "(¡La atmósfera se siente tan sofocante!)",
  ui_story_5040_50400702_146_dialog_content = "Nunca he sido de andarme por las ramas, así que te lo preguntaré directamente.",
  ui_story_5040_50400702_147_dialog_content = "Ella no es una auroriana, ¿verdad?",
  ui_story_5040_50400702_148_dialog_content = "¡...!",
  ui_story_5040_50400702_149_dialog_content = "Permítanme ser aún más directo: parece ser un Eclipsite que es capaz de hablar Universese.",
  ui_story_5040_50400702_150_dialog_content = "Señora Jeriah...",
  ui_story_5040_50400702_151_dialog_content = "¡Jejeje! Aunque no has sido mensajero por mucho tiempo, debo decir que estoy bastante sorprendido por tu valentía, pequeña.",
  ui_story_5040_50400702_152_dialog_content = "Parece que te subestimé.",
  ui_story_5040_50400702_153_dialog_content = "Sé que está completamente fuera de lugar que yo pregunte, pero... ¿podrías mantener esto en secreto?",
  ui_story_5040_50400702_154_dialog_content = "¿Y por qué debería hacer eso? ¿Qué razón tengo para ayudarte a mantener tu pequeña fachada?",
  ui_story_5040_50400702_155_dialog_content = "Ninguno, no hay razón para que me ayudes. Yo tampoco tengo derecho a pedir este favor.",
  ui_story_5040_50400702_156_dialog_content = "Te lo suplico, eso es todo.",
  ui_story_5040_50400702_157_dialog_content = "...",
  ui_story_5040_50400702_158_dialog_content = "Perdió sus recuerdos y me pidió que la ayudara.",
  ui_story_5040_50400702_159_dialog_content = "Ayudarla no me sirve de nada. En todo caso, nos pone a todos en peligro. Los aurorianos y los eclipses siempre han estado enfrentados; todos sabemos eso.",
  ui_story_5040_50400702_160_dialog_content = "Pero la razón principal por la que me convertí en mensajero fue para poder ayudar a las personas a expresar sus pensamientos y sentimientos entre sí. Eso es todo. Y quiero hacer lo mismo por ella.",
  ui_story_5040_50400702_161_dialog_content = "Dije que la ayudaría sin siquiera pensarlo. Fue imprudente de mi parte hacerlo, pero lo hice de todos modos.",
  ui_story_5040_50400702_162_dialog_content = "Por eso estoy preparado para aceptar toda la responsabilidad de lo que suceda como resultado de mis acciones. Pase lo que pase... te juro que pagaré el precio.",
  ui_story_5040_50400702_163_dialog_content = "Si dijera que quiero lastimar a Sable, ¿te pararías frente a ella?",
  ui_story_5040_50400702_164_dialog_content = "Me gustaría.",
  ui_story_5040_50400702_165_dialog_content = "Bueno Kya, siempre eres serio y terminas lo que empiezas. Del mismo modo, manejaré este asunto apropiadamente.",
  ui_story_5040_50400702_166_dialog_content = "...",
  ui_story_5040_50400702_167_dialog_content = "Eres mucho más interesante de lo que imaginaba. Un poco ingenuo, pero no me disgusta la seriedad.",
  ui_story_5040_50400702_168_dialog_content = "Haré lo que pides por ahora. La mejor de las suertes, Kya.",
  ui_story_5040_50400702_169_dialog_content = "Entonces, ¿eso significa... que me estás ayudando?",
  ui_story_5040_50400702_170_dialog_content = "¡Gracias! Muchas gracias, señora Jeriah.",
  ui_story_5040_50400702_171_dialog_content = "¡Y no te preocupes! Pase lo que pase, asumiré toda la responsabilidad hasta el final.",
  ui_story_5040_50400801_1_dialog_content = "Sable, gracias a ti, pudimos hacer algo realmente significativo en Gannon City. Vamos, regresemos y descansemos un poco ahora.",
  ui_story_5040_50400801_2_dialog_content = "Bien...",
  ui_story_5040_50400801_3_dialog_content = "¿Estás bien? Tu tez se ve un poco apagada.",
  ui_story_5040_50400801_4_dialog_content = "¿Mi cara?",
  ui_story_5040_50400801_5_dialog_content = "Sí. No quiero ser grosero, pero pareces un poco agotado, eso es todo.",
  ui_story_5040_50400801_6_dialog_content = "¿Has estado recibiendo suficientes vitaminas últimamente? ¿O tal vez te sientes un poco mal?",
  ui_story_5040_50400801_7_dialog_content = "Yo... yo no... lo creo...",
  ui_story_5040_50400801_8_dialog_content = "¡Graaah!",
  ui_story_5040_50400801_9_dialog_content = "Graaooh!!",
  ui_story_5040_50400801_10_dialog_content = "¿Qué? ¿Más eclipses?",
  ui_story_5040_50400801_11_dialog_content = "¡Esta es la primera vez que los veo en Gannon City!",
  ui_story_5040_50400801_12_dialog_content = "¡Aaaaaahhh! ¡¡Alguien salveme!!",
  ui_story_5040_50400801_13_dialog_content = "¡H... Agárrate... de mí!",
  ui_story_5040_50400801_14_dialog_content = "N-No tengas... miedo...",
  ui_story_5040_50400801_15_dialog_content = "¡Sable! ¡Llévate al chico y vuelve!",
  ui_story_5040_50400802_1_dialog_content = "Vaya... ¿ustedes dos están bien?",
  ui_story_5040_50400802_2_dialog_content = "S-Sí...",
  ui_story_5040_50400802_3_dialog_content = "¡Waaaah! ¡T-Tienes un aspecto tan aterrador!",
  ui_story_5040_50400802_4_dialog_content = "Yo...",
  ui_story_5040_50400802_5_dialog_content = "No te preocupes por él, Sable. El pobre niño probablemente todavía esté en estado de shock.",
  ui_story_5040_50400802_6_dialog_content = "Aún así, ¿qué están haciendo los eclipses en medio de la ciudad de Gannon?",
  ui_story_5040_50400802_7_dialog_content = "¡Uf! ¡Ustedes dos me hicieron un gran favor!",
  ui_story_5040_50400802_8_dialog_content = "J-Jola?",
  ui_story_5040_50400802_9_dialog_content = "Este es uno de los Eclipsites que utiliza Migard para realizar pruebas. Por alguna razón, se volvió loco y encontró la salida del laboratorio.",
  ui_story_5040_50400802_10_dialog_content = "Gracias a Dios nadie resultó herido... gracias a ustedes dos, por supuesto.",
  ui_story_5040_50400802_11_dialog_content = "¿Un eclipse usado para pruebas? ¿Te refieres a los de hoy?",
  ui_story_5040_50400802_12_dialog_content = "Precisamente. Migard capturó todo tipo de eclipses. No sé la naturaleza precisa de sus experimentos...",
  ui_story_5040_50400802_13_dialog_content = "pero parece que atraviesa los Eclipsites capturados bastante rápido.",
  ui_story_5040_50400802_14_dialog_content = "!",
  ui_story_5040_50400802_15_dialog_content = "¡Ustedes deben tener más cuidado con sus sujetos de prueba! ¿Y si este lograba lastimar a alguien?",
  ui_story_5040_50400802_16_dialog_content = "Bueno, este tipo de cosas nunca ha sucedido antes. Tal vez hay algo en ustedes que lo sacó.",
  ui_story_5040_50400802_17_dialog_content = "Hablando de Sable, podemos hacer que Migard te eche un vistazo. Ella tiene todo tipo de medicamentos en su laboratorio.",
  ui_story_5040_50400802_18_dialog_content = "Si no te sientes bien, ¡estoy seguro de que ella podrá ayudarte!",
  ui_story_5040_50400802_19_dialog_content = "No... ¡No, gracias!",
  ui_story_5040_50400802_20_dialog_content = "Yo... acabo de recordar... ¡algo importante!",
  ui_story_5040_50400802_21_dialog_content = "¡Necesito... ir... a buscar a Kya!",
  ui_story_5040_50400802_22_dialog_content = "¡¿Eh?!",
  ui_story_5040_50400802_23_dialog_content = "Jejeje... Qué amigo tan interesante tienes ahí.",
  ui_story_5040_50400802_24_dialog_content = "(Se está haciendo tarde... Sable y los demás probablemente me estén esperando. Debería irme.)",
  ui_story_5040_50400802_25_dialog_content = "K... Kya!!!",
  ui_story_5040_50400802_26_dialog_content = "¿Sable? ¿Qué estás haciendo aquí? ¿No deberías estar con PlayerName ¿ahora mismo?",
  ui_story_5040_50400802_27_dialog_content = "Quiero... estar contigo... Kya.",
  ui_story_5040_50400802_28_dialog_content = "Ya veo... entonces volvamos juntos.",
  ui_story_5040_50400802_29_dialog_content = "<color=#e8d9bb> Gruñido ... </color>",
  ui_story_5040_50400802_30_dialog_content = "Qué fue eso...?",
  ui_story_5040_50400802_31_dialog_content = "¿Oh eso? Lo siento, eso fue solo mi estómago.",
  ui_story_5040_50400802_32_dialog_content = "No he comido nada en todo el día. ¡Estoy hambriento!",
  ui_story_5040_50400802_33_dialog_content = "M... Yo también...",
  ui_story_5040_50400802_34_dialog_content = "¿Tú también? Vamos, podemos encontrar un buen lugar para comer antes de irnos a dormir.",
  ui_story_5040_50400802_35_dialog_content = "¡No! Yo... miro... La gente está... asustada...",
  ui_story_5040_50400802_36_dialog_content = "Sable...?",
  ui_story_5040_50400802_37_dialog_content = "No digas eso. Puede que no te parezcas a la mayoría de los aurorianos, pero eres amable de todos modos.",
  ui_story_5040_50400802_38_dialog_content = "Sin embargo, podemos comprar algo de pan para llevar. ¿Eso suena bien para usted?",
  ui_story_5040_50400802_39_dialog_content = "Si...",
  ui_story_5040_50400802_40_dialog_content = "Entonces, ¿la Federación Illumina te ha recordado algo más, Sable?",
  ui_story_5040_50400802_41_dialog_content = "No...",
  ui_story_5040_50400802_42_dialog_content = "¡Esta bien! Al menos te acordaste del desierto, ¿verdad? Apuesto a que tendremos mejor suerte una vez que lleguemos allí.",
  ui_story_5040_50400802_43_dialog_content = "No te preocupes.",
  ui_story_5040_50400802_44_dialog_content = "Gracias...",
  ui_story_5040_50400802_45_dialog_content = "Hmm, creo que vi a un comerciante que vendía pan de naranja casero en la estación. Espérame aquí.",
  ui_story_5040_50400802_46_dialog_content = "Volveré pronto, ¡no vayas a ningún lado!",
  ui_story_5040_50400802_47_dialog_content = "¡...!",
  ui_story_5040_50400802_48_dialog_content = "Eso sonaba... familiar...",
  ui_story_5040_50400802_49_dialog_content = "Volveré pronto, ¡solo espérame aquí!",
  ui_story_5040_50400802_50_dialog_content = "No vayas a ningún lado, volveré tan pronto como lo compre.",
  ui_story_5040_50400802_51_dialog_content = "Edward, ¿por qué estás hablando tanto tiempo? ¿Por qué no has vuelto todavía?",
  ui_story_5040_50400802_52_dialog_content = "¿Por qué no regresas?",
  ui_story_5040_50400802_53_dialog_content = "¿Es porque no soy lo suficientemente bueno? ¡¿Porque porque?!",
  ui_story_5040_50400802_54_dialog_content = "<size=45>¡¡¡Regresar!!!</size>",
  ui_story_5040_50400802_55_dialog_content = "¿Sentirse desesperanzado? ¿Como si no hubiera nada de lo que depender en el mundo? Acepta esta semilla, y nunca más tendrás miedo de nada.",
  ui_story_5040_50400802_56_dialog_content = "¡Libérate del sufrimiento de los débiles, porque serás más fuerte de lo que puedas imaginar!",
  ui_story_5040_50400802_57_dialog_content = "Aaaaaahhh!!!",
  ui_story_5040_50400802_58_dialog_content = "¡Mira, Sable! Es el Día de la Corona de la Luna, así que conseguí rollos de canela. Apuesto a que te encantará.",
  ui_story_5040_50400802_59_dialog_content = "Sable...?",
  ui_story_5040_50400802_60_dialog_content = "¡Aaaah! ¡Mira hermana, un eclipse!",
  ui_story_5040_50400802_61_dialog_content = "¡Hay un eclipse en la ciudad!",
  ui_story_5040_50400802_62_dialog_content = "Espera... ¿estás seguro? Tal vez sea otra cosa...",
  ui_story_5040_50400802_63_dialog_content = "¿Deberíamos llamar a la Legión?",
  ui_story_5040_50400802_64_dialog_content = "!",
  ui_story_5040_50400802_65_dialog_content = "¡Fuera del camino!",
  ui_story_5040_50400802_66_dialog_content = "¿Sable? ¡Sable! ¡¿Estás bien?!",
  ui_story_5040_50400802_67_dialog_content = "Ah...",
  ui_story_5040_50400802_68_dialog_content = "¡Vamos, Sablé! ¡Tenemos que salir de aquí!",
  ui_story_5040_50400802_69_dialog_content = "¡Esperad, vosotros dos! ¡Nombraos!",
  ui_story_5040_50400802_70_dialog_content = "Jadeo... Jadeo...",
  ui_story_5040_50400802_71_dialog_content = "¡Tranquilo!",
  ui_story_5040_50400802_72_dialog_content = "Argh...",
  ui_story_5040_50400802_73_dialog_content = "¡Tendremos un gran problema si nos encuentran!",
  ui_story_5040_50400802_74_dialog_content = "¿Viste por casualidad un eclipse de aspecto extraño por aquí? Ella estaba con una chica.",
  ui_story_5040_50400802_75_dialog_content = "Oh, eso suena problemático. Creo que intentaban escapar a la superficie... ¿Debería llamar a más soldados?",
  ui_story_5040_50400802_76_dialog_content = "¿Qué? ¡¿Cómo llegaron allí tan rápido?! ¡Después de ellos!",
  ui_story_5040_50400802_77_dialog_content = "Jeriah... Gracias.",
  ui_story_5040_50400802_78_dialog_content = "Parece que la costa está despejada. ¿Estás herido, Sable? ¡Déjame ver!",
  ui_story_5040_50400802_79_dialog_content = "Estoy bien.",
  ui_story_5040_50400802_80_dialog_content = "Lo siento por... hacer que te preocupes...",
  ui_story_5040_50400802_81_dialog_content = "¿Qué estás diciendo? Nunca podría perdonarme si te lastimaras mientras estaba comprando bocadillos.",
  ui_story_5040_50400802_82_dialog_content = "... Kya.",
  ui_story_5040_50400802_83_dialog_content = "Yo... recordé algo.",
  ui_story_5040_50400802_84_dialog_content = "¿En realidad? ¿Qué recordaste?",
  ui_story_5040_50400802_85_dialog_content = "Una persona... Alguien que... dijo las mismas cosas... que tú.",
  ui_story_5040_50400802_86_dialog_content = "Pero... él nunca... volvió.",
  ui_story_5040_50400802_87_dialog_content = "Fui a algún lugar... a algún lugar lejano... a buscarlo.",
  ui_story_5040_50400802_88_dialog_content = "Me dijo... que le gustaba...",
  ui_story_5040_50400802_89_dialog_content = "Pero... al final... me dejó.",
  ui_story_5040_50400802_90_dialog_content = "Corrí... corrí de casa... tenía miedo...",
  ui_story_5040_50400802_91_dialog_content = "Pero entonces... alguien me dio... una semilla.",
  ui_story_5040_50400802_92_dialog_content = "Me dijo... que me hiciera más fuerte.",
  ui_story_5040_50400802_93_dialog_content = "¡Así que eres un auroriano, después de todo!",
  ui_story_5040_50400802_94_dialog_content = "¡¿Pero cómo pudo pasar algo así?!",
  ui_story_5040_50400802_95_dialog_content = "Esa poción... me despertó...",
  ui_story_5040_50400802_96_dialog_content = "Pero yo... olvidé todo... no confíes en nada...",
  ui_story_5040_50400802_97_dialog_content = "Solo quiero irme a casa.",
  ui_story_5040_50400802_98_dialog_content = "Sable...",
  ui_story_5040_50400802_99_dialog_content = "No te preocupes, Sable. Te prometo que te llevaré de vuelta a tu casa.",
  ui_story_5040_50400802_100_dialog_content = "Partiremos hacia el desierto de Rediesel mañana a primera hora. Ahí podría estar tu casa.",
  ui_story_5040_50400802_101_dialog_content = "Gracias... Kya.",
  ui_story_5040_50400802_102_dialog_content = "Mi mente... últimamente, puedo... sentirla... desvanecerse de nuevo.",
  ui_story_5040_50400802_103_dialog_content = "No sé... cuánto tiempo... podré aguantar.",
  ui_story_5040_50400802_104_dialog_content = "Si yo... lo pierdo... Tendrás que...",
  ui_story_5040_50400802_105_dialog_content = "¡No digas nada más! Me aseguraré de que veas tu casa antes de que eso suceda. ¡Incluso podríamos encontrar una manera de evitar que tu conciencia se desvanezca!",
  ui_story_5040_50400802_106_dialog_content = "¿Recuerdas el gusano de arena rosa? Estoy seguro de que encontraremos una solución.",
  ui_story_5040_50400802_107_dialog_content = "Kya...",
  ui_story_5040_50400802_108_dialog_content = "Nos vamos mañana, no hay tiempo que perder.",
  ui_story_5040_50400802_109_dialog_content = "Te vas a casa, Sable.",
  ui_story_5040_50400901_1_dialog_content = "Aquí estamos. Siéntete como en casa.",
  ui_story_5040_50400901_2_dialog_content = "Así que esta es la división Rediesel Wrench de Courier Union, ¿eh?",
  ui_story_5040_50400901_3_dialog_content = "El exterior puede estar un poco deteriorado, ¡pero es hermoso aquí! Totalmente no es lo que esperaba.",
  ui_story_5040_50400901_X3_dialog_content = "Correcto, ¡sin mencionar que la ubicación es tan difícil de encontrar!",
  ui_story_5040_50400901_X4_dialog_content = "Todos los edificios de la base de la llave inglesa Rediesel están construidos de manera tan desordenada que es difícil incluso encontrar el camino...",
  ui_story_5040_50400901_X5_dialog_content = "¡Tienes que dar vueltas y vueltas por los callejones durante diez minutos antes de llegar a este lugar!",
  ui_story_5040_50400901_X6_dialog_content = "Me tomó años encontrarlo cuando vine aquí por primera vez.",
  ui_story_5040_50400901_X7_dialog_content = "¡Eso significa que tienes un buen sentido de la orientación!",
  ui_story_5040_50400901_X8_dialog_content = "Cuando vine aquí por primera vez, me tomó tanto tiempo encontrarlo que casi me doy por vencido.",
  ui_story_5040_50400901_4_dialog_content = "Aunque esta es la segunda vez que veo estas decoraciones, siguen siendo tan sorprendentes.",
  ui_story_5040_50400901_5_dialog_content = "No es sólo la decoración, tampoco. Hay tantos adornos finos en el interior que es cegador.",
  ui_story_5040_50400901_6_dialog_content = "¡Realmente no parece el estilo de Rediesel Wrench!",
  ui_story_5040_50400901_7_dialog_content = "¿Por qué clase de cretino vulgar me tomas?",
  ui_story_5040_50400901_8_dialog_content = "No me refería a eso...",
  ui_story_5040_50400901_9_dialog_content = "Está bien, estaba bromeando.",
  ui_story_5040_50400901_10_dialog_content = "Jeriah, esperaba echar un vistazo con Sable...",
  ui_story_5040_50400901_11_dialog_content = "Ningún problema. Ve a hurgar donde quieras.",
  ui_story_5040_50400901_12_dialog_content = "¿En serio?",
  ui_story_5040_50400901_13_dialog_content = "Solo recuerda poner todo donde lo encontraste.",
  ui_story_5040_50400901_14_dialog_content = "¡Claro!",
  ui_story_5040_50400901_15_dialog_content = "¡Vamos, Sablé!",
  ui_story_5040_50400901_16_dialog_content = "Debería ir a preparar el auto y las armas también.",
  ui_story_5040_50400901_17_dialog_content = "Pronto será de noche. Deberían descansar aquí esta noche.",
  ui_story_5040_50400901_18_dialog_content = "¿El coche? ¿No sería más rápido usar el Colossus?",
  ui_story_5040_50400901_X18_dialog_content = "Y el Coloso es tan grande. Parece mucho más seguro que un coche.",
  ui_story_5040_50400901_19_dialog_content = "Los gusanos de arena saben moverse por encima y por debajo del suelo.",
  ui_story_5040_50400901_20_dialog_content = "Son pequeños demonios astutos, expertos en navegar por cavernas subterráneas.",
  ui_story_5040_50400901_21_dialog_content = "Si no los agarras en el primer segundo que puedas, se desvanecerán.",
  ui_story_5040_50400901_X21_dialog_content = "¡¿Qué?!",
  ui_story_5040_50400901_X22_dialog_content = "Jerías tiene razón.",
  ui_story_5040_50400901_22_dialog_content = "El Colossus puede ser rápido, pero como pasajero, no hay forma de atacarlos a primera vista.",
  ui_story_5040_50400901_X23_dialog_content = "Lo he experimentado de primera mano, confía en mí.",
  ui_story_5040_50400901_23_dialog_content = "Entiendo...",
  ui_story_5040_50400901_24_dialog_content = "Tienes mucho más que aprender sobre el desierto.",
  ui_story_5040_50400901_25_dialog_content = "Debería irme. Saldremos mañana a primera hora para ir a cazar gusanos de arena.",
  ui_story_5040_50400901_26_dialog_content = "<color=#e8d9bb>*Retumbar*</color>",
  ui_story_5040_50400901_27_dialog_content = "¡Lo siento!",
  ui_story_5040_50400901_28_dialog_content = "Hemos estado tan ocupados que me olvidé por completo de comer.",
  ui_story_5040_50400901_29_dialog_content = "<color=#e8d9bb>*Rrrrrum*</color>",
  ui_story_5040_50400901_30_dialog_content = "Yo también tengo bastante hambre.",
  ui_story_5040_50400901_31_dialog_content = "Bueno, ya que estamos en el desierto, ¡permítanme prepararles algunas especialidades de Rediesel Wrench!",
  ui_story_5040_50400901_32_dialog_content = "¡Déjame encender el fuego afuera y haremos una barbacoa!",
  ui_story_5040_50400901_33_dialog_content = "¡Ayudaré!",
  ui_story_5040_50400901_34_dialog_content = "Y entonces hubo uno.",
  ui_story_5040_50400901_35_dialog_content = "Probablemente no debería ser el tercero de Tara y Adonis, pero tampoco creo que Kya y Sable necesiten ayuda.",
  ui_story_5040_50400901_36_dialog_content = "De todos modos, me pregunto si muchos de nosotros podríamos manejar un gusano de arena tan grande como se rumorea.",
  ui_story_5040_50400901_37_dialog_content = "Jeriah parece bastante fuerte, y Tara es una buena luchadora... pero todavía estoy un poco preocupado.",
  ui_story_5040_50400901_38_dialog_content = "Debería ir a buscar a Jeriah, ver si cree que necesitamos refuerzos.",
  ui_story_5040_50400901_39_dialog_content = "¿Viniste a buscarme porque estabas preocupada, pequeña Caelestite?",
  ui_story_5040_50400901_40_dialog_content = "P-Por favor no me llames así.",
  ui_story_5040_50400901_41_dialog_content = "No hay necesidad de preocuparse. Conozco este desierto como la palma de mi mano.",
  ui_story_5040_50400901_42_dialog_content = "Ya inspeccioné el auto y preparé los suministros. Sólo cuídense y estarán bien.",
  ui_story_5040_50400901_43_dialog_content = "Pero los gusanos de arena son bestias formidables. Me preocupa que no podamos manejarlo solos.",
  ui_story_5040_50400901_44_dialog_content = "¿Deberíamos reclutar a otros para ayudar? ¿Qué pasa con Sinsa, Azure y ese montón?",
  ui_story_5040_50400901_45_dialog_content = "No hay necesidad.",
  ui_story_5040_50400901_46_dialog_content = "Pero...",
  ui_story_5040_50400901_47_dialog_content = "No necesito la ayuda de nadie.",
  ui_story_5040_50400901_48_dialog_content = "Sólo yo solo lo haré. Es solo un gusano de arena, unos cuantos golpes lo derribarán.",
  ui_story_5040_50400901_49_dialog_content = "Ahora, si no necesita nada más, puede regresar.",
  ui_story_5040_50400901_50_dialog_content = "Tengo otras cosas que hacer y no necesito que me molesten las preocupaciones de los niños.",
  ui_story_5040_50400901_51_dialog_content = "...",
  ui_story_5040_50400901_52_dialog_content = "Está bien...",
  ui_story_5040_50400901_S52_dialog_content = "Será mejor que vuelva a Soroz.",
  ui_story_5040_50400901_53_dialog_content = "Wow... Realmente acabo de ser perseguido por Jeriah.",
  ui_story_5040_50400901_54_dialog_content = "Olvídalo. Si ella quiere que me ocupe de mis propios asuntos, ¡eso es lo que haré!",
  ui_story_5040_50400901_55_dialog_content = "...",
  ui_story_5040_50400901_X55_dialog_content = "(Todo este tiempo, Jeriah siempre se ha mostrado como alguien que se divierte viendo cómo se derrumban las cosas).",
  ui_story_5040_50400901_X56_dialog_content = "(Incluso si ella es un miembro senior de Courier Union, todavía no puedo confiar en ella).",
  ui_story_5040_50400901_X57_dialog_content = "(Solo voy a enviar un mensaje de terminal a la gente de Rediesel Wrench para estar seguros).",
  ui_story_5040_50400901_X58_dialog_content = "(Ojalá haya alguien cerca y responda...)",
  ui_story_5040_50400901_56_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_5040_50400901_57_dialog_content = "Hola PlayerName, este es Odi. ¿Copias?",
  ui_story_5040_50400901_58_dialog_content = "Odi!",
  ui_story_5040_50400901_59_dialog_content = "¡Copiar! ¡Esto es genial, en realidad no esperaba que nadie respondiera!",
  ui_story_5040_50400901_60_dialog_content = "¿Qué puedo hacer por ti?",
  ui_story_5040_50400901_61_dialog_content = "¿Sabes algo sobre un gusano de arena rosa?",
  ui_story_5040_50400901_62_dialog_content = "¿Un gusano de arena rosa? Hmm, eso suena una campana.",
  ui_story_5040_50400901_63_dialog_content = "Creo que Sinsa se topó con uno hace como un mes.",
  ui_story_5040_50400901_64_dialog_content = "Nadie había visto un gusano de arena como ese antes, por lo que todos corrieron para tratar de capturarlo, pero se escapó.",
  ui_story_5040_50400901_65_dialog_content = "No tengo los detalles precisos. Déjame llamar al jefe y puedes preguntarle tú mismo.",
  ui_story_5040_50400901_66_dialog_content = "Seguro. ¡Perdón por la molestia!",
  ui_story_5040_50400901_67_dialog_content = "Yo, PlayerName! ¿Qué pasa?",
  ui_story_5040_50400901_68_dialog_content = "¿Odi dice que estabas preguntando por el gusano de arena rosa?",
  ui_story_5040_50400901_69_dialog_content = "Sí. ¿Que me puedes decir?",
  ui_story_5040_50400901_70_dialog_content = "Que quieres saber? Ese bruto es uno de los pocos gusanos de arena que podría escapar de mí.",
  ui_story_5040_50400901_71_dialog_content = "Hace aproximadamente un mes, estaba decidido a cazarlo, pero al final se escapó y solo logré volver a casa con una balanza.",
  ui_story_5040_50400901_72_dialog_content = "Tsk... Qué vergüenza. Esa sola escala se vendió por un centavo. ¡Imagínese lo que podría hacer si atrapara uno entero!",
  ui_story_5040_50400901_73_dialog_content = "Después de todo, nadie había visto antes un gusano de arena rosa. ¿Quién va a decir si no fue el único en todo el mundo? ¡Y sabes que cuanto más raro es algo, más cuesta!",
  ui_story_5040_50400901_74_dialog_content = "¿Por qué buscas un gusano de arena rosa de todos modos? Déjame adivinar, ¿estás con Jeriah?",
  ui_story_5040_50400901_75_dialog_content = "¡¿Como supiste?!",
  ui_story_5040_50400901_76_dialog_content = "Porque ese Portavoz de Jeriah está por todas partes, volando de aquí para allá entre todos los terrenos habituales de los gusanos de arena.",
  ui_story_5040_50400901_77_dialog_content = "Y si estás buscando un gusano de arena en este momento, creo que es muy probable que estés buscando a ese tipo grande y rosado.",
  ui_story_5040_50400901_78_dialog_content = "Es una locura estar usando tanto Luminatics.",
  ui_story_5040_50400901_79_dialog_content = "¿¿Sabes donde está??",
  ui_story_5040_50400901_80_dialog_content = "Por supuesto que sí. Pero esa información te va a costar, chico. ¿Qué tienes a cambio?",
  ui_story_5040_50400901_81_dialog_content = "Eh... yo...",
  ui_story_5040_50400901_82_dialog_content = "Jajaja... ¡Mírate, temblando así! ¿Qué, crees que estoy tratando de estafarte o algo así?",
  ui_story_5040_50400901_83_dialog_content = "Solo recuerda traer un poco de chocolate para Eve la próxima vez que vengas aquí, y estaremos bien.",
  ui_story_5040_50400901_84_dialog_content = "Escuchó que Umbraton tiene un chocolate especial de edición limitada para este festival de la Corona y lo ha estado pidiendo.",
  ui_story_5040_50400901_85_dialog_content = "De todos modos, siempre estás en ese Coloso tuyo volando por todas partes, así que ayúdala a agarrar algo en el camino.",
  ui_story_5040_50400901_86_dialog_content = "Por supuesto.",
  ui_story_5040_50400901_87_dialog_content = "Pues bien, tenemos nosotros mismos un trato.",
  ui_story_5040_50400901_88_dialog_content = "La última vez que luché contra esa maldita cosa, estaba resbaladiza como el infierno, siempre encontrando un lugar para esconderse.",
  ui_story_5040_50400901_89_dialog_content = "Pero le di un buen golpe con mi llave inglesa antes de que se escapara, lo que me arrancó la escama del lado izquierdo.",
  ui_story_5040_50400901_90_dialog_content = "Lo perseguí durante días, pero finalmente perdí el rastro. El último lugar donde lo vi fue en lo profundo del desierto, cerca del Oasis.",
  ui_story_5040_50400901_91_dialog_content = "Sin embargo, no puedo decirte su ubicación precisa.",
  ui_story_5040_50400901_92_dialog_content = "Si está buscando asumirlo, también podría comenzar su búsqueda desde allí.",
  ui_story_5040_50400901_93_dialog_content = "¡Entiendo! Muchas gracias, Sinsa.",
  ui_story_5040_50400901_94_dialog_content = "Si tienes a Jeriah contigo, dudo que eso sea un gran problema. Pero tenga cuidado, es un tramposo cojonudo.",
  ui_story_5040_50400901_95_dialog_content = "¿Qué te hace decir eso? ¿Conoces bien a Jeriah?",
  ui_story_5040_50400901_96_dialog_content = "Yo no diría eso. Se mantiene reservada y no habla mucho con el resto de nosotros.",
  ui_story_5040_50400901_97_dialog_content = "Pero ser capaz de sobrevivir sola en el desierto de Rediesel es una prueba de su fuerza.",
  ui_story_5040_50400901_98_dialog_content = "Además, ella es una de los pocos mensajeros en el desierto, así que realmente confiamos en ella.",
  ui_story_5040_50400901_99_dialog_content = "¡No te preocupes, haz lo que ella dice y estarás bien!",
  ui_story_5040_50400901_100_dialog_content = "Bien...",
  ui_story_5040_50400901_101_dialog_content = "¡Entendido!",
  ui_story_5040_50400901_102_dialog_content = "De todos modos, probablemente debería irme, o Eve me molestará para que vaya a descansar.",
  ui_story_5040_50400901_103_dialog_content = "¡Muy bien, nos vemos!",
  ui_story_5040_50400901_104_dialog_content = "Probablemente no debería ir directamente a Jeriah en este momento. Primero, iré a completar los demás.",
  ui_story_5040_50400901_105_dialog_content = "¡Sin mencionar que también me muero de hambre! ¡Veamos qué hay en el menú de hoy!",
  ui_story_5040_50400901_106_dialog_content = "<color=#e8d9bb>Mientras tanto, en la división Courier Union Rediesel Wrench...</color>",
  ui_story_5040_50400901_107_dialog_content = "Todas las cartas atrasadas deberían estar aquí.",
  ui_story_5040_50400901_108_dialog_content = "Con el vasto desierto y todos los muchachos de Rediesel Wrench corriendo por todos lados, no sorprende que haya mucho correo sin reclamar.",
  ui_story_5040_50400901_109_dialog_content = "Probablemente tomará un tiempo encontrar lo que estamos buscando.",
  ui_story_5040_50400901_110_dialog_content = "Sable... ayudará...",
  ui_story_5040_50400901_111_dialog_content = "¡Trabajaremos juntos! Primero necesitamos ver cuántas letras hay.",
  ui_story_5040_50400901_112_dialog_content = "¡Tantos!",
  ui_story_5040_50400901_113_dialog_content = "Espera, estos tienen notas.",
  ui_story_5040_50400901_114_dialog_content = "\"Destinatario perdido\", \"Destinatario desconocido\", \"Rechazado\"...",
  ui_story_5040_50400901_115_dialog_content = "¿Realmente todos han sido archivados en diferentes categorías?",
  ui_story_5040_50400901_116_dialog_content = "Kya... mira... allí.",
  ui_story_5040_50400901_117_dialog_content = "¡¿Este dice \"Mismo sello\"?!",
  ui_story_5040_50400901_118_dialog_content = "Hay algunas palabras garabateadas debajo que dicen: \"Sospecho que el remitente es la misma persona\".",
  ui_story_5040_50400901_119_dialog_content = "El sello aquí es el mismo que el tuyo, Sable.",
  ui_story_5040_50400901_120_dialog_content = "Estos son mios...",
  ui_story_5040_50400901_121_dialog_content = "No puedo creer que hayamos encontrado lo que buscábamos tan rápido. ¡Gracias a dios!",
  ui_story_5040_50400901_122_dialog_content = "Echemos un vistazo a las letras.",
  ui_story_5040_50400901_123_dialog_content = "Si...",
  ui_story_5040_50400901_124_dialog_content = "\"¡Gracias por aceptar ser mi amigo por correspondencia! Es un placer conocerte\".",
  ui_story_5040_50400901_125_dialog_content = "\"El desierto es demasiado caluroso para la mayoría de la gente, por lo que todos parecen vivir muy lejos. Tenemos que depender de los mensajeros para comunicarnos\".",
  ui_story_5040_50400901_126_dialog_content = "\"Si pudiéramos viajar juntos, estaría feliz de dejar el desierto\".",
  ui_story_5040_50400901_127_dialog_content = "Estas cartas parecen haber sido escritas cuando estabas conociendo al destinatario.",
  ui_story_5040_50400901_128_dialog_content = "La dirección del destinatario siempre es diferente y no hay una dirección del remitente.",
  ui_story_5040_50400901_129_dialog_content = "¿Podría haber estado su casa en el desierto?",
  ui_story_5040_50400901_130_dialog_content = "Mm...",
  ui_story_5040_50400901_131_dialog_content = "¡¡Ah!!",
  ui_story_5040_50400901_132_dialog_content = "¡¿Sable?!",
  ui_story_5040_50400901_133_dialog_content = "Recuerdo...",
  ui_story_5040_50400901_134_dialog_content = "Mi hogar... profundo desierto...",
  ui_story_5040_50400901_135_dialog_content = "Pero... donde... no recuerdo...",
  ui_story_5040_50400901_136_dialog_content = "Eso no importa, esto ya es una pista realmente útil. A continuación, ¡solo tenemos que preguntarle a las personas que viven en el desierto!",
  ui_story_5040_50400901_137_dialog_content = "No se esfuerce demasiado por recordar. Toma un descanso primero.",
  ui_story_5040_50400901_138_dialog_content = "Acepté su solicitud, por lo que el mensajero que hay en mí hará todo lo posible para ayudarlo.",
  ui_story_5040_50400901_139_dialog_content = "Bien...",
  ui_story_5040_50400901_140_dialog_content = "¿Qué pasa, Sable? Pareces un poco apático.",
  ui_story_5040_50400901_141_dialog_content = "Tara, Adonis... Buena relación...",
  ui_story_5040_50400901_142_dialog_content = "Cuídense... unos a otros... ayúdense... unos a otros...",
  ui_story_5040_50400901_143_dialog_content = "Deseo...",
  ui_story_5040_50400901_144_dialog_content = "(Sable no fue tratada bien por la persona que amaba, ni su amor fue correspondido).",
  ui_story_5040_50400901_145_dialog_content = "(Ver a esos dos tan felices debe hacerla sentir triste...)",
  ui_story_5040_50400901_146_dialog_content = "No te sientas mal. ¡Ese tipo que te trató tan mal ahora está en el pasado!",
  ui_story_5040_50400901_147_dialog_content = "Mis mayores siempre me dicen que en su experiencia, el karma siempre llega a aquellos que no tratan bien a los demás.",
  ui_story_5040_50400901_148_dialog_content = "En cuanto a Tara y Adonis, si estar cerca de ellos te molesta, podemos salir de aquí y continuar solos.",
  ui_story_5040_50400901_149_dialog_content = "Está bien...",
  ui_story_5040_50400901_150_dialog_content = "Ellos... me recuerdan... tiempos más felices...",
  ui_story_5040_50400901_151_dialog_content = "Familia... Amigos... Amor...",
  ui_story_5040_50400901_152_dialog_content = "Ese sentimiento cálido... Es todo lo que siempre he querido...",
  ui_story_5040_50400901_153_dialog_content = "Ese calor... es precioso, así que... les deseo lo mejor...",
  ui_story_5040_50400901_154_dialog_content = "Bien...",
  ui_story_5040_50400901_155_dialog_content = "<color=#e8d9bb>*Rrrrrum*</color>",
  ui_story_5040_50400901_156_dialog_content = "Hambrienta...",
  ui_story_5040_50400901_157_dialog_content = "Yo también. ¡Vamos a comer algo!",
  ui_story_5040_50400901_158_dialog_content = "(No me di cuenta de que se había hecho tan tarde, y no sé cómo les está yendo a Tara y a los demás con la cena).",
  ui_story_5040_50400901_159_dialog_content = "¡Achuu!",
  ui_story_5040_50400901_160_dialog_content = "(E-Este sabor acre y especiado solo puede ser... ¡barbacoa Reddiesel!)",
  ui_story_5040_50400901_161_dialog_content = "¿Hmm? Kya, Sable, ¿no estaban ustedes dos explorando?",
  ui_story_5040_50400901_162_dialog_content = "Ya hemos terminado, y como nos morimos de hambre, decidimos volver y ver cómo iba la cena.",
  ui_story_5040_50400901_163_dialog_content = "Si...",
  ui_story_5040_50400901_164_dialog_content = "(No tenía idea de que la acumulación de correo ya había sido separada y clasificada).",
  ui_story_5040_50400901_165_dialog_content = "(¡Incluso fueron organizados juntos por el remitente en función de pequeñas similitudes!)",
  ui_story_5040_50400901_166_dialog_content = "(Fue solo gracias a eso que logramos encontrar el correo de Sable tan rápido).",
  ui_story_5040_50400901_167_dialog_content = "(Supongo que eso fue todo Jeriah.)",
  ui_story_5040_50400901_168_dialog_content = "Seguro que está animado por aquí.",
  ui_story_5040_50400901_169_dialog_content = "Ese olor... ja. Ustedes, la gente de Rediesel Wrench, solo saben cómo cocinar una barbacoa ardiente, ¿eh?",
  ui_story_5040_50400901_170_dialog_content = "Cuando estás en el desierto, comes como un habitante del desierto.",
  ui_story_5040_50400901_171_dialog_content = "¿Terminaste todo, Jeriah?",
  ui_story_5040_50400901_172_dialog_content = "Sí. El auto y los suministros están listos, y también identifiqué el rango activo del gusano de arena.",
  ui_story_5040_50400901_173_dialog_content = "Está herido por un ataque anterior, por lo que actualmente se adentra más en el desierto.",
  ui_story_5040_50400901_174_dialog_content = "(Eso se alinea con lo que me dijo Sinsa).",
  ui_story_5040_50400901_175_dialog_content = "(Mejor no decir nada, en caso de que Jeriah se moleste de nuevo...)",
  ui_story_5040_50400901_176_dialog_content = "¡Tiempo perfecto! La cecina de lagarto está lista, ¡ven y tómate un poco!",
  ui_story_5040_50400901_177_dialog_content = "¿Es esto realmente un pincho? Ni siquiera puedes ver nada debajo de todo el chile.",
  ui_story_5040_50400901_178_dialog_content = "Esto se conoce como cecina de lagarto ultrapicante. Solo los aventureros culinarios más valientes se atreven a probar este pináculo de la cocina Rediesel.",
  ui_story_5040_50400901_179_dialog_content = "Eh, ¿tengo que hacerlo?",
  ui_story_5040_50400901_180_dialog_content = "Tiene tanto chili que con solo mirarlo me arden los ojos.",
  ui_story_5040_50400901_181_dialog_content = "¿Vas a tener alguno o no?",
  ui_story_5040_50400901_182_dialog_content = "¡Sí! Claro que soy yo.",
  ui_story_5040_50400901_183_dialog_content = "No te fuerces, Adonis.",
  ui_story_5040_50400901_184_dialog_content = "*mascar*",
  ui_story_5040_50400901_185_dialog_content = "...",
  ui_story_5040_50400901_186_dialog_content = "Él... ¿Se lo comió todo de una vez?",
  ui_story_5040_50400901_187_dialog_content = "¡...!",
  ui_story_5040_50400901_188_dialog_content = "<color=#e8d9bb>¡Golpear!</color>",
  ui_story_5040_50400901_189_dialog_content = "¡¿A-Adonis?!",
  ui_story_5040_50400901_190_dialog_content = "Jajaja, ¿podrías mirar eso? ¡Se ha puesto totalmente morado!",
  ui_story_5040_50400901_191_dialog_content = "Picante...",
  ui_story_5040_50400901_192_dialog_content = "<size=45>MUY PICANTE!!</size>",
  ui_story_5040_50400901_193_dialog_content = "¡Vaya, parece que está a punto de desmayarse!",
  ui_story_5040_50400901_194_dialog_content = "¡Rápido, que alguien le traiga un poco de leche! ¡Escuché que la leche es buena para contrarrestar la comida picante!",
  ui_story_5040_50400901_195_dialog_content = "¡Iré a mirar!",
  ui_story_5040_50400901_196_dialog_content = "...",
  ui_story_5040_50400901_197_dialog_content = "(¿Por qué se fue? Voy a ir a ver qué pasa.)",
  ui_story_5040_50400901_198_dialog_content = "¡Encontré un poco de leche!",
  ui_story_5040_50400901_199_dialog_content = "¡Adonis, bebe esto!",
  ui_story_5040_50400901_200_dialog_content = "*glug glug glug*",
  ui_story_5040_50400901_201_dialog_content = "Ah... Ahhh... ¿Sigo respirando...?",
  ui_story_5040_50400901_202_dialog_content = "Te acabas de comer una brocheta entera de cecina de lagarto ultrapicante y luego te desmayaste.",
  ui_story_5040_50400901_203_dialog_content = "¿En serio?",
  ui_story_5040_50400901_204_dialog_content = "Urgh... Me duele el estómago, como si me hubiera tragado un trozo de carbón ardiendo...",
  ui_story_5040_50400901_205_dialog_content = "<size=45><anim type=Shake>¡Urgh!</anim></size>",
  ui_story_5040_50400901_206_dialog_content = "¡¡¿Adonis?!!",
  ui_story_5040_50400901_207_dialog_content = "<color=#e8d9bb>Mientras tanto...</color>",
  ui_story_5040_50400901_208_dialog_content = "Tu pequeño novio está vomitando sus sesos allá. ¿No vas a ir a ver si está bien?",
  ui_story_5040_50400901_209_dialog_content = "¿O tienes otra idea brillante?",
  ui_story_5040_50400901_210_dialog_content = "Voy a llevar a Adonis de regreso a Northland tan pronto como se recupere.",
  ui_story_5040_50400901_211_dialog_content = "Estoy agotado. No quiero hacer esto nunca más.",
  ui_story_5040_50400901_212_dialog_content = "No estamos destinados a estar juntos. No somos compatibles.",
  ui_story_5040_50400901_213_dialog_content = "¿Oh?",
  ui_story_5040_50400901_214_dialog_content = "Solía pensar que mientras estuviéramos juntos, podríamos superar cualquier cosa.",
  ui_story_5040_50400901_215_dialog_content = "Siempre quise darle una probada de la vida del Desierto Rediesel, como la parrillada de ahora...",
  ui_story_5040_50400901_216_dialog_content = "pero nunca pensé que las cosas que me gustaban en realidad le causarían daño.",
  ui_story_5040_50400901_217_dialog_content = "Sigue lastimándose, todo porque se está obligando a complacerme.",
  ui_story_5040_50400901_218_dialog_content = "No creo que eso sea amor.",
  ui_story_5040_50400901_X218_dialog_content = "Suspiro... los pajaritos enamorados ciertamente sacan todo tipo de conclusiones sobre asuntos insignificantes.",
  ui_story_5040_50400901_X219_dialog_content = "¿Por qué piensas eso?",
  ui_story_5040_50400901_219_dialog_content = "Hay tal abismo entre nosotros, ya sea en estilo de vida o personalidad. Tal vez sus padres tenían razón.",
  ui_story_5040_50400901_220_dialog_content = "Las aves del norte carecen de plumas finas y no saben cómo excavar en busca de agua, por lo que, por supuesto, no pueden sobrevivir en el desierto.",
  ui_story_5040_50400901_221_dialog_content = "...",
  ui_story_5040_50400901_222_dialog_content = "Esto no es algo que cualquier cantidad de valentía pueda superar. Es una cuestión de diferencias innatas.",
  ui_story_5040_50400901_223_dialog_content = "Lo que es común para las aves del desierto es peligroso para las del norte.",
  ui_story_5040_50400901_224_dialog_content = "Pero...",
  ui_story_5040_50400901_225_dialog_content = "¿Pero qué?",
  ui_story_5040_50400901_226_dialog_content = "Ese pajarito tuyo no puede con nada picante, pero se tragó un pincho de todos modos y terminó en el suelo.",
  ui_story_5040_50400901_227_dialog_content = "Seguramente quería mostrarte, aunque solo sea por un momento, su voluntad de dar un paso al frente y ser valiente.",
  ui_story_5040_50400901_228_dialog_content = "Ustedes pueden encontrar un estilo de vida que funcione para ambos gradualmente.",
  ui_story_5040_50400901_229_dialog_content = "En lugar de limitarse a vivir únicamente el estilo de vida Rediesel.",
  ui_story_5040_50400901_230_dialog_content = "¡...!",
  ui_story_5040_50400901_231_dialog_content = "Eso es todo lo que quería decir.",
  ui_story_5040_50400901_232_dialog_content = "Ya sea que terminen juntos o no, están aquí ahora mismo, así que es mejor que lo disfruten.",
  ui_story_5040_50400901_233_dialog_content = "Relájate, diviértete y no bajes el ambiente.",
  ui_story_5040_50400901_234_dialog_content = "...",
  ui_story_5040_50400901_235_dialog_content = "Mmm.",
  ui_story_5040_50400901_236_dialog_content = "Estoy volviendo.",
  ui_story_5040_50400901_237_dialog_content = "Que interesante pajarito.",
  ui_story_5040_50400901_238_dialog_content = "Tengo curiosidad por lo que traerá el próximo capítulo de su relación.",
  ui_story_5040_50400901_239_dialog_content = "... Ja, ¿qué me ha pasado?",
  ui_story_5040_50400901_240_dialog_content = "No puedo creer que me importe.",
  ui_story_5040_50401001_1_dialog_content = "Ah, ¿ya has venido?",
  ui_story_5040_50401001_2_dialog_content = "Acordamos buscar el gusano de arena hoy, así que me levanté especialmente temprano.",
  ui_story_5040_50401001_3_dialog_content = "Además, nadie fue lo suficientemente valiente como para comerse esos pinchos, así que finalmente tuvimos que ir a buscar algo para comer en Soroz...",
  ui_story_5040_50401001_4_dialog_content = "Ustedes simplemente no aprecian la buena comida. Pero no te preocupes, me comí el resto de la barbacoa.",
  ui_story_5040_50401001_5_dialog_content = "¡Ni un bocado se desperdició!",
  ui_story_5040_50401001_6_dialog_content = "Definitivamente apruebo no desperdiciar comida.",
  ui_story_5040_50401001_7_dialog_content = "Entonces, ¿cómo durmieron todos anoche?",
  ui_story_5040_50401001_8_dialog_content = "Yo personalmente dormí maravillosamente.",
  ui_story_5040_50401001_9_dialog_content = "Hace frío en el desierto por la noche, pero afortunadamente preparaste mantas gruesas, así que Sable y yo estábamos bien.",
  ui_story_5040_50401001_10_dialog_content = "Gracias... Jeriah.",
  ui_story_5040_50401001_11_dialog_content = "Oh, no hay problema en absoluto, Sable.",
  ui_story_5040_50401001_12_dialog_content = "yo, eh...",
  ui_story_5040_50401001_13_dialog_content = "Me dolió el estómago toda la noche...",
  ui_story_5040_50401001_14_dialog_content = "(Debe haber sido Adonis a quien escuché correr al baño varias veces anoche, entonces).",
  ui_story_5040_50401001_15_dialog_content = "¿Quieres descansar un poco antes de salir?",
  ui_story_5040_50401001_16_dialog_content = "¡Estoy bien!",
  ui_story_5040_50401001_17_dialog_content = "¡Estoy totalmente bien, en serio!",
  ui_story_5040_50401001_18_dialog_content = "...",
  ui_story_5040_50401001_19_dialog_content = "(Tara ha tenido una mirada divertida en su rostro desde la cena de anoche. ¿Tiene algo en mente?)",
  ui_story_5040_50401001_20_dialog_content = "Está bien. En ese caso, pongámonos en marcha. Tara puede ocupar el asiento del pasajero y el resto de ustedes el de atrás.",
  ui_story_5040_50401001_21_dialog_content = "<color=#e8d9bb>Algún tiempo después...</color>",
  ui_story_5040_50401001_22_dialog_content = "Esto está cerca del área del desierto profundo habitada por los gusanos de arena.",
  ui_story_5040_50401001_23_dialog_content = "Tomemos nuestro último descanso aquí.",
  ui_story_5040_50401001_24_dialog_content = "Saqué la carpa, los utensilios de cocina y toda la comida del auto con Sable.",
  ui_story_5040_50401001_25_dialog_content = "¡Podemos empezar a cocinar en cualquier momento!",
  ui_story_5040_50401001_26_dialog_content = "Buen trabajo.",
  ui_story_5040_50401001_27_dialog_content = "Ahora que hemos descargado todo el equipaje, volvamos al coche.",
  ui_story_5040_50401001_28_dialog_content = "¿Eh? ¿Por qué? ¿No vamos a descansar?",
  ui_story_5040_50401001_29_dialog_content = "Todavía tenemos una cosa más que hacer antes de eso.",
  ui_story_5040_50401001_30_dialog_content = "Las dunas de arena más adelante son empinadas y en pendiente. Montar esas olas de arena es la manera perfecta de dejarse llevar y relajarse.",
  ui_story_5040_50401001_31_dialog_content = "¿Qué tienen que ver las dunas de arena con la relajación?",
  ui_story_5040_50401001_32_dialog_content = "Lo descubrirás en un momento, pajarito de Northland.",
  ui_story_5040_50401001_X32_dialog_content = "Muy bien, sube al coche.",
  ui_story_5040_50401001_X33_dialog_content = "Pero es...",
  ui_story_5040_50401001_X34_dialog_content = "¡Deja de tartamudear y súbete al auto!",
  ui_story_5040_50401001_X35_dialog_content = "Tú también puedes venir, pequeña Caelestite.",
  ui_story_5040_50401001_X36_dialog_content = "<color=#e8d9bb>en el coche</color>",
  ui_story_5040_50401001_X37_dialog_content = "¿Están todos listos para irse?",
  ui_story_5040_50401001_X38_dialog_content = "Jeriah, ¿qué planeas hacer?",
  ui_story_5040_50401001_X39_dialog_content = "Vaya, voy a hacer algo para hacer feliz a Tara, por supuesto.",
  ui_story_5040_50401001_X40_dialog_content = "Tengo un mal presentimiento sobre esto... ¿¡Puedes dejarme salir de aquí!?",
  ui_story_5040_50401001_X41_dialog_content = "Iré a hacerte el almuerzo—",
  ui_story_5040_50401001_X42_dialog_content = "De ninguna manera. Eres parte indispensable de esta experiencia.",
  ui_story_5040_50401001_33_option_content = "¿¡Indispensable!?",
  ui_story_5040_50401001_34_dialog_content = "Por supuesto. Eres nuestro navegador vital.",
  ui_story_5040_50401001_35_option_content = "¡Creo que paso!",
  ui_story_5040_50401001_36_dialog_content = "Ahora no se acobarde.",
  ui_story_5040_50401001_37_dialog_content = "Recuerda abrocharte el cinturón de seguridad.",
  ui_story_5040_50401001_38_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_5040_50401001_39_dialog_content = "¡Ahhh!",
  ui_story_5040_50401001_40_dialog_content = "¡E-Esto es demasiado rápido!",
  ui_story_5040_50401001_41_dialog_content = "¡GUAUOO! ¡Esto es increíble!",
  ui_story_5040_50401001_42_dialog_content = "¡Más rápido, Jeriah, más rápido!",
  ui_story_5040_50401001_43_dialog_content = "¡Ayuda! ¡Este coche está a punto de despegar!",
  ui_story_5040_50401001_44_dialog_content = "¿Es esto... lo que se siente volar?",
  ui_story_5040_50401001_X44_dialog_content = "¡Detener! No vayas tan rápido... ¡Es peligroso!",
  ui_story_5040_50401001_X45_dialog_content = "Mi estómago... no se siente tan bien...",
  ui_story_5040_50401001_45_dialog_content = "¡Tienes que seguir volando más rápido hasta que estés mirando una tormenta a los ojos para comprender verdaderamente el éxtasis de volar!",
  ui_story_5040_50401001_46_dialog_content = "¡¡¡Gahhhh!!!",
  ui_story_5040_50401001_47_dialog_content = "¡Cuidado! ¡El ruido del motor atrajo a los eclipses!",
  ui_story_5040_50401001_48_dialog_content = "¡Pequeña Caelestite, es hora del espectáculo!",
  ui_story_5040_50401001_49_dialog_content = "¡¿Eh?!",
  ui_story_5040_50401001_50_dialog_content = "No me importa si usas tus ojos o tus habilidades psíquicas, dime exactamente desde dónde atacarán los Eclipsites.",
  ui_story_5040_50401001_51_dialog_content = "¿Cuando vamos tan rápido? ¡Estás haciendo las cosas difíciles a propósito!",
  ui_story_5040_50401001_52_dialog_content = "¡Gahhhh!",
  ui_story_5040_50401001_53_dialog_content = "¡Oh! ¡Desde atrás, lado izquierdo!",
  ui_story_5040_50401001_54_dialog_content = "Bien.",
  ui_story_5040_50401001_55_dialog_content = "<color=#e8d9bb>*Screeeee—!*</color>",
  ui_story_5040_50401001_56_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_5040_50401001_57_dialog_content = "¡Acabamos de enviar un Eclipsite volando!",
  ui_story_5040_50401001_58_dialog_content = "Necesito... Oh, no... ¡*Arcón*!",
  ui_story_5040_50401001_59_dialog_content = "No vomites en mi auto, pajarito de Northland.",
  ui_story_5040_50401001_60_dialog_content = "Mira lo feliz que se ve Tara por una vez.",
  ui_story_5040_50401001_61_dialog_content = "R-¿En serio? Entonces necesito... aguantar... por Tara...",
  ui_story_5040_50401001_62_dialog_content = "...",
  ui_story_5040_50401001_63_dialog_content = "Grahh!!",
  ui_story_5040_50401001_64_dialog_content = "¡Más eclipses, adelante!",
  ui_story_5040_50401001_65_dialog_content = "Mostrémosles nuestra pasión y démosles algo de velocidad.",
  ui_story_5040_50401001_66_dialog_content = "¡Máxima velocidad adelante!",
  ui_story_5040_50401001_67_dialog_content = "Jajaja, esto es genial!",
  ui_story_5040_50401001_68_dialog_content = "¡Oh, no, no, voy a... *Arquear*!",
  ui_story_5040_50401001_69_dialog_content = "Mareado por un viaje tan corto? Supongo que un pájaro de Northland necesita tiempo para acostumbrarse al desierto.",
  ui_story_5040_50401001_70_dialog_content = "Mientras que las aves del desierto solo vuelan libremente cuando son transportadas por los vientos del desierto.",
  ui_story_5040_50401001_71_dialog_content = "Sí...",
  ui_story_5040_50401001_72_dialog_content = "He decidido.",
  ui_story_5040_50401001_73_dialog_content = "¿Tienes ahora? Finalmente.",
  ui_story_5040_50401001_74_dialog_content = "Sí. En realidad, Adonis, yo—",
  ui_story_5040_50401001_75_dialog_content = "¿Ah?",
  ui_story_5040_50401001_76_dialog_content = "<color=#e8d9bb>retumbando—</color>",
  ui_story_5040_50401001_77_dialog_content = "¡Señora Jeriah! ¡Eclipsitos!",
  ui_story_5040_50401001_78_dialog_content = "¡Hay un montón de ellos dirigiéndose directamente hacia nosotros!",
  ui_story_5040_50401001_79_dialog_content = "Estos tipos saben cómo arruinar el estado de ánimo.",
  ui_story_5040_50401001_80_dialog_content = "¡Tú eres el que aceleró el motor antes, Jeriah! ¡El ruido debe haberlos atraído!",
  ui_story_5040_50401001_81_dialog_content = "Continuemos nuestra conversación más tarde, pajaritos.",
  ui_story_5040_50401001_82_dialog_content = "Ahora mismo tenemos que lidiar con estos tipos, luego vamos a tener un buen almuerzo.",
  ui_story_5040_50401001_83_dialog_content = "Suspiro...",
  ui_story_5040_50401001_84_dialog_content = "¡Yo ayudaré!",
  ui_story_5040_50401002_1_dialog_content = "Son más lindos cuando están en el suelo.",
  ui_story_5040_50401002_2_dialog_content = "Graaahh—",
  ui_story_5040_50401002_3_dialog_content = "Asustado...",
  ui_story_5040_50401002_4_dialog_content = "No tengas miedo, ella no... Er, quiero decir, ya nos hemos ocupado de los Eclipsites.",
  ui_story_5040_50401002_5_dialog_content = "Jeriah... no da miedo...",
  ui_story_5040_50401002_6_dialog_content = "Jeriah... buena persona... Protege a todos...",
  ui_story_5040_50401002_7_dialog_content = "¡Pero los eclipses lo destrozaron todo, incluidos todos nuestros suministros de alimentos!",
  ui_story_5040_50401002_8_dialog_content = "Estaba planeando hacer algunos bocadillos al estilo de Umbraton, pero ahora todo se ha puesto patas arriba. ¡Totalmente inutilizable!",
  ui_story_5040_50401002_9_dialog_content = "Oh no, ¿qué deberíamos hacer?",
  ui_story_5040_50401002_10_dialog_content = "(¿Jeriah solo miró a Adonis?)",
  ui_story_5040_50401002_11_dialog_content = "Tengo una idea.",
  ui_story_5040_50401002_12_dialog_content = "¿Sí?",
  ui_story_5040_50401002_13_dialog_content = "Creo que todavía podemos usar estas cosas si las limpiamos.",
  ui_story_5040_50401002_14_dialog_content = "No estoy seguro de que podamos usarlo para lo que estabas planeando, pero definitivamente podríamos preparar un estofado.",
  ui_story_5040_50401002_15_dialog_content = "¡Déjamelo a mí!",
  ui_story_5040_50401002_16_dialog_content = "(¡Adonis realmente se puso manos a la obra!)",
  ui_story_5040_50401002_17_dialog_content = "Primero, corte las partes magulladas o dañadas, y guarde lo que aún se puede usar.",
  ui_story_5040_50401002_18_dialog_content = "Luego córtelos en trozos pequeños y póngalos en agua hirviendo.",
  ui_story_5040_50401002_19_dialog_content = "Tara, ¿podrías pasarme eso, por favor?",
  ui_story_5040_50401002_20_dialog_content = "Aquí.",
  ui_story_5040_50401002_21_dialog_content = "Gracias. Ahora añadimos un poco de sal...",
  ui_story_5040_50401002_22_dialog_content = "¡Huele bien!",
  ui_story_5040_50401002_23_dialog_content = "Aquí hay un cuenco para ti, Tara. Sé que no te gustan los rábanos, así que ya los elegí todos.",
  ui_story_5040_50401002_24_dialog_content = "Gracias...",
  ui_story_5040_50401002_25_dialog_content = "¡Un tazón para mí también, por favor! ¡Y uno para Sable!",
  ui_story_5040_50401002_26_dialog_content = "Está bien, está bien, espera... Prepararé el tuyo.",
  ui_story_5040_50401002_27_dialog_content = "Toma, he traído los tazones.",
  ui_story_5040_50401002_28_dialog_content = "¡Mmm, qué rico almuerzo!",
  ui_story_5040_50401002_29_dialog_content = "Es un poco raro comer estofado caliente en medio del desierto, ¡pero es tan delicioso que ni me importa!",
  ui_story_5040_50401002_30_dialog_content = "¡Eso es lo único que importa!",
  ui_story_5040_50401002_31_dialog_content = "Déjame manejar el lavado.",
  ui_story_5040_50401002_32_dialog_content = "Bueno. Echaré un vistazo rápido a la zona y me aseguraré de que no haya más eclipses.",
  ui_story_5040_50401002_33_dialog_content = "Espera, ¿no estabas diciendo algo antes?",
  ui_story_5040_50401002_34_dialog_content = "Casi lo olvido, con todo el fiasco de Eclipsite.",
  ui_story_5040_50401002_35_dialog_content = "... No, no fue nada. Me voy a patrullar.",
  ui_story_5040_50401002_36_dialog_content = "Voy a dar un paseo con Sable, a ver el paisaje.",
  ui_story_5040_50401002_37_dialog_content = "(Raro... Tara parece estar ocultándome algo).",
  ui_story_5040_50401002_38_dialog_content = "(Y antes, Tara me entregó la sal incluso antes de que la pidiera).",
  ui_story_5040_50401002_39_dialog_content = "(¿Su memoria está comenzando a regresar?)",
  ui_story_5040_50401002_40_dialog_content = "(Dicho esto, ha estado un poco extraña durante todo el viaje).",
  ui_story_5040_50401002_41_dialog_content = "(La forma en que dudó ahora se parecía mucho a cómo solía ser, cuando estaba a punto de disculparse por algo).",
  ui_story_5040_50401002_42_dialog_content = "(Es realmente extraño. ¿Podría ser... que nunca tuvo amnesia?)",
  ui_story_5040_50401002_43_dialog_content = "(¿Pero por qué haría ella esto? Necesito pensar...)",
  ui_story_5040_50401002_44_dialog_content = "(Ella finge perder la memoria, lo que me obliga a dejar Northland... ¿podría haber sido todo esto una artimaña para hacerme más valiente?)",
  ui_story_5040_50401002_45_dialog_content = "(Tara, te probaré lo que soy. ¡Lo prometo!)",
  ui_story_5040_50401002_46_dialog_content = "¿Un centavo por tus pensamientos, Adonis?",
  ui_story_5040_50401002_47_dialog_content = "Ah, no es nada. ¿Qué pasa?",
  ui_story_5040_50401002_48_dialog_content = "¿Puedo ayudar en algo?",
  ui_story_5040_50401002_49_dialog_content = "No, está bien. Puedo arreglarme solo.",
  ui_story_5040_50401002_50_dialog_content = "Puedes ir a hacer otra cosa.",
  ui_story_5040_50401002_51_dialog_content = "Está bien.",
  ui_story_5040_50401002_52_dialog_content = "(Estoy tan aburrido de mí mismo. Desearía que Vice y Carleen estuvieran aquí ahora mismo, extraño hablar con ellos).",
  ui_story_5040_50401002_53_dialog_content = "(Jeriah es un poco solitaria. ¿Nunca se aburre?)",
  ui_story_5040_50401002_54_dialog_content = "(Ojalá ya no esté enojada. Tal vez debería ir a verla).",
  ui_story_5040_50401002_55_dialog_content = "Suspiro, ha sido agotador, pero...",
  ui_story_5040_50401002_56_dialog_content = "Tara, Adonis... Jeje, esos son dos pajaritos interesantes.",
  ui_story_5040_50401002_57_dialog_content = "Jerías!",
  ui_story_5040_50401002_58_dialog_content = "¿Eh? ¡Oh, si no es la joven Caelestite! ¿Qué te trae por aquí?",
  ui_story_5040_50401002_59_dialog_content = "¿Podría ser que te sientes solo sin tus otros jóvenes amigos?",
  ui_story_5040_50401002_60_dialog_content = "¡N-No! ¡Por supuesto que no!",
  ui_story_5040_50401002_61_dialog_content = "¿O tal vez me encontraste lamentable, aquí solo, y pensaste que la compañía sería apreciada?",
  ui_story_5040_50401002_62_dialog_content = "Eso tampoco...",
  ui_story_5040_50401002_63_dialog_content = "Hay algo que quería preguntarte.",
  ui_story_5040_50401002_64_dialog_content = "¿Oh?",
  ui_story_5040_50401002_65_option_content = "¿Estás siendo completamente honesto?",
  ui_story_5040_50401002_66_dialog_content = "¿Qué te hace decir eso?",
  ui_story_5040_50401002_67_dialog_content = "Dijiste esta mañana que dormiste bien.",
  ui_story_5040_50401002_68_dialog_content = "¡Pero eso no cuadra con lo que escuché!",
  ui_story_5040_50401002_69_option_content = "¿Estás poniendo cara de valiente?",
  ui_story_5040_50401002_70_dialog_content = "¿Cara valiente? ¿Y qué te llevó a esa conclusión?",
  ui_story_5040_50401002_71_dialog_content = "Escuché que ayer enviaste a tu Portavoz a recorrer todo el desierto en busca de gusanos de arena.",
  ui_story_5040_50401002_72_dialog_content = "...",
  ui_story_5040_50401002_73_dialog_content = "Incluso si lo hiciera, ¿y qué?",
  ui_story_5040_50401002_74_dialog_content = "¡Fue imprudente!",
  ui_story_5040_50401002_75_dialog_content = "Usar una Luminática tan intensa durante tanto tiempo y luego levantarse tan temprano esta mañana... Apuesto a que no descansaste bien, ¿verdad? Y ahora sigues yendo.",
  ui_story_5040_50401002_76_dialog_content = "¡Estás exagerando!",
  ui_story_5040_50401002_77_dialog_content = "De nuevo... suponiendo que tengas razón, ¿y qué?",
  ui_story_5040_50401002_78_dialog_content = "Solo digo que no es necesario que te esfuerces tanto. Está bien apoyarse en los demás de vez en cuando.",
  ui_story_5040_50401002_79_dialog_content = "Puedo arreglármelas muy bien en el desierto por mi cuenta.",
  ui_story_5040_50401002_80_dialog_content = "Soy perfectamente capaz de rastrear el gusano de arena por mí mismo, mientras completo las tareas de la Unión de Mensajeros y entrego el correo por todo el desierto.",
  ui_story_5040_50401002_81_dialog_content = "¿Qué derecho tienes a dudar de mí de todos modos?",
  ui_story_5040_50401002_82_dialog_content = "¡No estoy dudando de ti!",
  ui_story_5040_50401002_83_dialog_content = "Soy muy consciente de que, como Caelestite, no tengo Luminatics particularmente fuertes. También sé que soy bastante inútil luchando contra los Eclipsites.",
  ui_story_5040_50401002_84_dialog_content = "Es por eso que confío en la fuerza de mis compañeros todo el tiempo.",
  ui_story_5040_50401002_85_dialog_content = "Es porque soy débil que me di cuenta de que nadie puede sobrevivir en este mundo completamente solo.",
  ui_story_5040_50401002_86_dialog_content = "¿Es eso lo que piensas?",
  ui_story_5040_50401002_87_dialog_content = "Por fuerte que seas, inevitablemente encontrarás problemas más allá de lo que puedes manejar.",
  ui_story_5040_50401002_88_dialog_content = "Algunas personas pueden salir adelante, confiando en su propio crecimiento o trabajo duro...",
  ui_story_5040_50401002_89_dialog_content = "pero algunos problemas no esperan a que crezcas, o son demasiados, incluso si trabajas duro.",
  ui_story_5040_50401002_90_dialog_content = "Mi vida está llena de este tipo de problemas porque soy una Caelestita frágil.",
  ui_story_5040_50401002_91_dialog_content = "¿Quieres decir que no hay vergüenza en apoyarse en los demás?",
  ui_story_5040_50401002_92_dialog_content = "Jeje, realmente eres ingenuo.",
  ui_story_5040_50401002_93_dialog_content = "Una o dos veces quizás esté bien, pero demasiadas veces y la cantidad de favores adeudados se convierte en una carga.",
  ui_story_5040_50401002_94_dialog_content = "Como una jaula, esta carga atrapa a un pájaro, impidiéndole volar libremente.",
  ui_story_5040_50401002_95_dialog_content = "Me imagino que debes saber lo que se siente, estar tan agobiado por las cosas que le debes a los demás.",
  ui_story_5040_50401002_96_option_content = "Si",
  ui_story_5040_50401002_97_dialog_content = "Tienes razón, es difícil estar en la posición de deberle favores a la gente.",
  ui_story_5040_50401002_98_dialog_content = "Exactamente. Odio el sentimiento, y no tengo ningún deseo de relacionarme mucho con los demás.",
  ui_story_5040_50401002_99_dialog_content = "¿De verdad puedes decir que vivir solo, pero libre, es algo malo?",
  ui_story_5040_50401002_100_dialog_content = "Es genial tener la libertad de hacer lo que quieras sin tener que pensar demasiado.",
  ui_story_5040_50401002_101_dialog_content = "Pero las interacciones con otros no son transaccionales.",
  ui_story_5040_50401002_102_option_content = "No",
  ui_story_5040_50401002_103_dialog_content = "Es cierto que mucha gente me ha ayudado, pero no siento que sea una carga.",
  ui_story_5040_50401002_104_dialog_content = "¡...!",
  ui_story_5040_50401002_105_dialog_content = "Todos tienen sus propias fortalezas y debilidades, y las personas se complementan entre sí.",
  ui_story_5040_50401002_106_dialog_content = "Mis compañeros pueden estar dotados en Luminatics, pero puedo ver Light Trails. Podemos enfrentarnos a Eclipsites juntos, uno al lado del otro.",
  ui_story_5040_50401002_107_dialog_content = "No sé qué has experimentado que te haya hecho tan reacio a conectarte con la gente.",
  ui_story_5040_50401002_108_dialog_content = "Pero las relaciones son una calle de doble sentido. Sí, podría aceptar la ayuda de otras personas, pero también haré todo lo posible para ayudar a los demás.",
  ui_story_5040_50401002_109_dialog_content = "...",
  ui_story_5040_50401002_110_dialog_content = "Así es como lo ves, ¿eh?",
  ui_story_5040_50401002_111_dialog_content = "Parece que la relación que tienes con tus compañeros es la misma que esos dos pajaritos de allí.",
  ui_story_5040_50401002_112_dialog_content = "¡¿Qué?!",
  ui_story_5040_50401002_113_dialog_content = "¡Sólo somos amigos! No somos tan—",
  ui_story_5040_50401002_114_dialog_content = "¡Vaya, vaya, mira a dónde se ha ido tu mente! No he dicho nada.",
  ui_story_5040_50401002_115_dialog_content = "Tú...",
  ui_story_5040_50401002_116_dialog_content = "Mira esos dos. Se complementan bastante bien, ¿no?",
  ui_story_5040_50401002_117_dialog_content = "Ya estoy de vuelta. No hay rastros de Eclipsites en el área hasta ahora.",
  ui_story_5040_50401002_118_dialog_content = "¡Buen trabajo! Toma, toma un poco de agua y descansa un rato.",
  ui_story_5040_50401002_119_dialog_content = "Sí...",
  ui_story_5040_50401002_120_dialog_content = "Tara es extrovertida y alegre, con mucha experiencia viviendo en la naturaleza y lidiando con eclipses.",
  ui_story_5040_50401002_121_dialog_content = "Adonis es más logístico y lo suficientemente paciente como para lidiar con todo el trabajo que Tara encuentra tedioso y en el que no es muy bueno.",
  ui_story_5040_50401002_122_dialog_content = "Así es. Nunca hubiera pensado que habría una persona que pudiera llevarse bien con un miembro de Rediesel Wrench así.",
  ui_story_5040_50401002_123_dialog_content = "¿No te gustan las llaves Rediesel?",
  ui_story_5040_50401002_124_dialog_content = "¿Disgusto? Decir ah. Tal vez.",
  ui_story_5040_50401002_125_dialog_content = "En lo que a mí respecta, no son más que un montón de bandidos sin cerebro y miopes.",
  ui_story_5040_50401002_126_dialog_content = "Viven una existencia tan hedonista, sin importarles nada más que divertirse.",
  ui_story_5040_50401002_127_dialog_content = "Pero sabes, fue Sinsa quien me contó que usaste tu altavoz para rastrear todo el desierto en busca de gusanos de arena.",
  ui_story_5040_50401002_128_dialog_content = "¿Qué?",
  ui_story_5040_50401002_129_dialog_content = "Ayer, después de que me hicierais marchar, me puse en contacto con Sinsa para preguntarle por el gusano de arena rosa.",
  ui_story_5040_50401002_130_dialog_content = "Me dijo que alguien en Rediesel Wrench te vio usando tu altavoz para buscar gusanos de arena.",
  ui_story_5040_50401002_131_dialog_content = "Todos estaban preocupados por ti.",
  ui_story_5040_50401002_132_dialog_content = "Eso es solo porque soy uno de los pocos mensajeros en el desierto que puede entregarles la información que necesitan.",
  ui_story_5040_50401002_133_dialog_content = "¡No es así!",
  ui_story_5040_50401002_134_dialog_content = "Muy bien, creo que he descansado lo suficiente.",
  ui_story_5040_50401002_135_dialog_content = "¡Oye, Jerías!",
  ui_story_5040_50401002_136_dialog_content = "Junta tus cosas. Es hora de salir.",
  ui_story_5040_50401002_137_dialog_content = "En serio, Jeriah. Solo vete y déjame colgado, ¿por qué no...?",
  ui_story_5040_50401002_138_dialog_content = "¿Tiene el hábito de vivir en negación y fingir que todo está bien?",
  ui_story_5040_50401101_1_dialog_content = "¿Cómo van sus preparativos, pajaritos?",
  ui_story_5040_50401101_2_dialog_content = "Estoy todo empacado y listo para ir cuando sea.",
  ui_story_5040_50401101_3_dialog_content = "Estoy listo también.",
  ui_story_5040_50401101_4_dialog_content = "El fuego ha sido apagado y tenemos todas nuestras pertenencias.",
  ui_story_5040_50401101_5_dialog_content = "¡Eres tan prudente, Kya!",
  ui_story_5040_50401101_6_dialog_content = "¡Gracias! Esmeralda me enseñó bien.",
  ui_story_5040_50401101_7_dialog_content = "¿Quién es Esmeralda?",
  ui_story_5040_50401101_8_dialog_content = "Era una estudiante de último año mía en Courier Union, aunque ahora está jubilada.",
  ui_story_5040_50401101_9_dialog_content = "Antes de convertirme en mensajero, era Emerald quien entregaba las cartas a mi ciudad natal de Faar y a los demás pueblos cercanos.",
  ui_story_5040_50401101_10_dialog_content = "Mi ciudad natal es muy remota, por lo que casi nunca teníamos contacto con el mundo exterior.",
  ui_story_5040_50401101_11_dialog_content = "Nuestra única forma de saber qué estaba pasando era a través de las cartas que trajo Emerald.",
  ui_story_5040_50401101_12_dialog_content = "Ella debe haber sido una persona muy responsable.",
  ui_story_5040_50401101_13_dialog_content = "¡Oh sí! ¡Fue gracias a ella que me inspiré para convertirme en mensajero!",
  ui_story_5040_50401101_14_dialog_content = "Sé de primera mano lo difícil que es para las personas que viven en lugares remotos conectarse con el mundo exterior, por lo que quería convertirme en un puente para otros hacia el exterior.",
  ui_story_5040_50401101_15_dialog_content = "¡Eso es increíble!",
  ui_story_5040_50401101_16_dialog_content = "Jeje, todavía tengo margen de mejora.",
  ui_story_5040_50401101_17_dialog_content = "Incluso con todas las notas que me dio Emerald, sigo estropeando las cosas...",
  ui_story_5040_50401101_18_dialog_content = "Aunque sigo todos los consejos de sus notas con precisión, las cosas de alguna manera siempre resultan diferentes a mis expectativas.",
  ui_story_5040_50401101_19_dialog_content = "No es necesario seguir siempre instrucciones como esa al pie de la letra. A veces, es necesario improvisar y adaptarse a la situación.",
  ui_story_5040_50401101_20_dialog_content = "Eh, no soy muy bueno en eso.",
  ui_story_5040_50401101_21_dialog_content = "¡¡Graaoooooohhh!!",
  ui_story_5040_50401101_22_dialog_content = "¿Se enteró que? ¿Algo en la distancia?",
  ui_story_5040_50401101_23_dialog_content = "Eso es...",
  ui_story_5040_50401101_24_dialog_content = "Graah! ¡Rugido!",
  ui_story_5040_50401101_25_dialog_content = "¡Eclipsitos! Todos, ¡cuidado!",
  ui_story_5040_50401101_26_dialog_content = "¡Tantos de ellos!",
  ui_story_5040_50401101_27_dialog_content = "¡¿De dónde han venido todos ellos esta vez?!",
  ui_story_5040_50401101_28_dialog_content = "¿Otro grupo? Que extraño...",
  ui_story_5040_50401101_29_dialog_content = "Vamos a tratar con ellos primero. Buena suerte y ten cuidado.",
  ui_story_5040_50401102_1_dialog_content = "Graaahh—",
  ui_story_5040_50401102_2_dialog_content = "Extraño, no suelen darse por vencidos tan fácilmente. Sin embargo, simplemente se escaparon...",
  ui_story_5040_50401102_3_dialog_content = "Esta no es un área donde generalmente se sabe que aparecen los eclipses.",
  ui_story_5040_50401102_4_dialog_content = "Pero este fue el segundo grupo con el que nos encontramos en los últimos días. Eso no es normal.",
  ui_story_5040_50401102_5_dialog_content = "Están... corriendo...",
  ui_story_5040_50401102_6_dialog_content = "¿Qué dijiste?",
  ui_story_5040_50401102_7_dialog_content = "¿Sable dijo que parecían estar huyendo, escondiéndose de algo?",
  ui_story_5040_50401102_8_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_5040_50401102_9_dialog_content = "¿Está temblando el suelo?",
  ui_story_5040_50401102_10_dialog_content = "Fuera del camino, todos. ¡Algo viene!",
  ui_story_5040_50401102_11_dialog_content = "¡Cuidado, Tara!",
  ui_story_5040_50401102_12_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5040_50401102_13_dialog_content = "<size=50>¡Roooooooor!</size>",
  ui_story_5040_50401102_14_dialog_content = "¡¡Guau!! ¡¿Es eso realmente un gusano de arena rosa?!",
  ui_story_5040_50401102_15_dialog_content = "¡Pensé que se suponía que se dirigía hacia la parte más profunda del desierto! ¡Eso está, eh, bastante lejos de aquí!",
  ui_story_5040_50401102_16_dialog_content = "Hay otra explicación para su apariencia... Podría ser la hora de comer.",
  ui_story_5040_50401102_17_dialog_content = "¿Estás diciendo que intentaba alimentarse de esos eclipses?",
  ui_story_5040_50401102_18_dialog_content = "Sí... y parece que ahora estamos en el menú.",
  ui_story_5040_50401102_19_dialog_content = "<size=50>¡Rooooooor!</size>",
  ui_story_5040_50401102_20_dialog_content = "¿Por qué tanta prisa, grandote?",
  ui_story_5040_50401102_21_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5040_50401102_22_dialog_content = "¡Esa es una armadura!",
  ui_story_5040_50401102_23_dialog_content = "Jejeje... Supongo que esas escamas rosadas son mucho más fuertes de lo que parecen.",
  ui_story_5040_50401102_24_dialog_content = "Pero pase lo que pase, sigue siendo solo un gusano de arena.",
  ui_story_5040_50401102_25_dialog_content = "¡Adelante, portavoces!",
  ui_story_5040_50401102_26_dialog_content = "rugir—",
  ui_story_5040_50401102_27_dialog_content = "¡Mira, está funcionando!",
  ui_story_5040_50401102_28_dialog_content = "¡Yo también ayudaré!",
  ui_story_5040_50401102_29_dialog_content = "¡Espera, Tara! ¡No te acerques demasiado a él!",
  ui_story_5040_50401102_30_dialog_content = "Mis balas no atravesarán las escamas de este gusano de arena si estoy demasiado lejos.",
  ui_story_5040_50401102_31_dialog_content = "Además, no hay nada que temer. Rosa o no, ¡es solo un gusano de arena!",
  ui_story_5040_50401102_32_dialog_content = "Rrr... Rugido...!",
  ui_story_5040_50401102_33_dialog_content = "A continuación... ¡un tiro en la cabeza!",
  ui_story_5040_50401102_34_dialog_content = "¡Rugido!",
  ui_story_5040_50401102_35_dialog_content = "¡¿Eh?!",
  ui_story_5040_50401102_36_dialog_content = "¡E-Tiene el arma de Tara! ¡¿Hizo eso intencionalmente?!",
  ui_story_5040_50401102_37_dialog_content = "¡Déjalo ir!",
  ui_story_5040_50401102_38_dialog_content = "¿Cómo podría un gusano de arena tener este tipo de conciencia? Algo esta mal...",
  ui_story_5040_50401102_39_dialog_content = "No podremos derrotarlo rápidamente. No con nuestra fuerza actual.",
  ui_story_5040_50401102_40_dialog_content = "¡Está tratando de desgastarnos al alargar la pelea!",
  ui_story_5040_50401102_41_dialog_content = "No podemos permitir que eso suceda. ¡Grimorio, libera tu poder!",
  ui_story_5040_50401102_42_dialog_content = "Rugido-!",
  ui_story_5040_50401102_43_dialog_content = "¡¿Adónde fue?!",
  ui_story_5040_50401102_44_dialog_content = "¡Está excavando bajo la arena! ¡Cuida tu paso!",
  ui_story_5040_50401102_45_dialog_content = "<size=50>¡¡¡Rooooooooooooooooooooooooooooooooooo!!!</size>",
  ui_story_5040_50401102_46_dialog_content = "<color=#e8d9bb>¡Whoosh, golpe!</color>",
  ui_story_5040_50401102_47_dialog_content = "¡Agh-!",
  ui_story_5040_50401102_48_dialog_content = "¡Lanzó a Tara a las dunas de allí!",
  ui_story_5040_50401102_49_dialog_content = "Tara!!!",
  ui_story_5040_50401102_50_dialog_content = "¡Estoy bien!",
  ui_story_5040_50401102_51_dialog_content = "La arena aquí está suelta; está usando eso para enterrarnos y emboscarnos.",
  ui_story_5040_50401102_52_dialog_content = "¡Todos al coche!",
  ui_story_5040_50401102_53_dialog_content = "Hay una parte del desierto donde el suelo es principalmente de piedra. ¡Si podemos llegar allí, el gusano de arena no podrá tendernos una emboscada!",
  ui_story_5040_50401102_54_dialog_content = "¡Entiendo! ¡Vamos Sable, vamos al auto!",
  ui_story_5040_50401102_55_dialog_content = "¡Nos retiramos, Adonis!",
  ui_story_5040_50401102_56_dialog_content = "Tengo... ¡Cuidado, Tara!",
  ui_story_5040_50401102_57_dialog_content = "rugir—",
  ui_story_5040_50401102_58_dialog_content = "Urg-!",
  ui_story_5040_50401102_59_dialog_content = "Tara!!",
  ui_story_5040_50401102_60_dialog_content = "Ay...",
  ui_story_5040_50401102_61_dialog_content = "¡Oh no, la pierna de Tara está herida!",
  ui_story_5040_50401102_62_dialog_content = "¡Rugido!",
  ui_story_5040_50401102_63_dialog_content = "(Maldita sea, no podremos lograrlo. ¿Cómo puedo detenerlo...)",
  ui_story_5040_50401102_64_dialog_content = "¡Deja a Tara en paz, oruga gorda y fea!",
  ui_story_5040_50401102_65_dialog_content = "rugir—",
  ui_story_5040_50401102_66_dialog_content = "¡Por aquí, gusano gigante! ¡Venir a buscarme!",
  ui_story_5040_50401102_67_dialog_content = "¡Adonis llamó la atención del gusano de arena!",
  ui_story_5040_50401102_68_dialog_content = "¡No puedo creer que ese débil ataque suyo haya funcionado!",
  ui_story_5040_50401102_69_dialog_content = "Fíjate bien en el lugar donde Adonis golpeó al gusano de arena... Creo que es una herida que no se ha curado del todo.",
  ui_story_5040_50401102_70_dialog_content = "¡Eso debe ser de su pelea con Sinsa y los demás!",
  ui_story_5040_50401102_71_dialog_content = "¡Rugido!",
  ui_story_5040_50401102_72_dialog_content = "¡Ay!",
  ui_story_5040_50401102_73_dialog_content = "¡El gusano de arena está detrás de Adonis ahora, se está alejando de Tara!",
  ui_story_5040_50401102_74_dialog_content = "¡Ahora es tu oportunidad, Jeriah!",
  ui_story_5040_50401102_75_dialog_content = "Jejeje... Lo sé.",
  ui_story_5040_50401102_76_dialog_content = "¡Vuela, Halcón! ¡Apunta a esa herida!",
  ui_story_5040_50401102_77_dialog_content = "¿Rugido? ¡Roaaarrrr!",
  ui_story_5040_50401102_78_dialog_content = "¡Ahora!",
  ui_story_5040_50401102_79_dialog_content = "¿Estás bien, Tara?",
  ui_story_5040_50401102_80_dialog_content = "¡Estoy bien! ¡Ve a ayudar a Adonis!",
  ui_story_5040_50401102_81_dialog_content = "¡Entendido!",
  ui_story_5040_50401102_82_dialog_content = "¡Yo... ayudaré... también!",
  ui_story_5040_50401102_83_dialog_content = "<color=#e8d9bb>Zumbido-!</color>",
  ui_story_5040_50401102_84_dialog_content = "¡¡¡Rooooooooooooooooooooooooooooooooooooo!!!",
  ui_story_5040_50401102_85_dialog_content = "¡Yo... estoy salvado!",
  ui_story_5040_50401102_86_dialog_content = "¡Ponte detrás de nosotros y no pierdas el equilibrio!",
  ui_story_5040_50401102_87_dialog_content = "¡Rugido!",
  ui_story_5040_50401102_88_dialog_content = "<color=#e8d9bb>Fwooosh!!!</color>",
  ui_story_5040_50401102_89_dialog_content = "¡Guau! ¡¿De dónde vino esta tormenta de arena?!",
  ui_story_5040_50401102_90_dialog_content = "No es una tormenta de arena. El gusano de arena está arrojando arena al aire.",
  ui_story_5040_50401102_91_dialog_content = "¡Está tratando de proteger sus puntos débiles oscureciendo nuestra visión!",
  ui_story_5040_50401102_92_dialog_content = "Oh no... ¡Perdí de vista a Kya ya los demás!",
  ui_story_5040_50401102_93_dialog_content = "¡Tara! ¡¿Dónde estás?!",
  ui_story_5040_50401102_94_dialog_content = "¡Aquí!",
  ui_story_5040_50401102_95_dialog_content = "¡Vamos en camino!",
  ui_story_5040_50401102_96_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_5040_50401102_97_dialog_content = "Ahhh!!!",
  ui_story_5040_50401102_98_dialog_content = "¡¿A-Adonis?!",
  ui_story_5040_50401102_99_dialog_content = "¡Iré a traerlos de vuelta!",
  ui_story_5040_50401102_100_dialog_content = "<size=50>¡¡¡Roooaaar!!!</size>",
  ui_story_5040_50401102_101_dialog_content = "¡¿Eh?!",
  ui_story_5040_50401102_102_dialog_content = "¡Jeriah, se está escapando!",
  ui_story_5040_50401102_103_dialog_content = "¡No en mi reloj!",
  ui_story_5040_50401102_104_dialog_content = "<size=50>¡¡¡Rooooooooooooooooooooooooooooooooooooo!!!</size>",
  ui_story_5040_50401102_105_dialog_content = "¡¡¡Puaj!!!",
  ui_story_5040_50401102_106_dialog_content = "¡¡¡PlayerName!!!",
  ui_story_5040_50401102_107_dialog_content = "Ay...",
  ui_story_5040_50401201_1_dialog_content = "Animarse, PlayerName!",
  ui_story_5040_50401201_2_dialog_content = "Uf... Mi cabeza...",
  ui_story_5040_50401201_3_dialog_content = "*farfullando* ¡Uf, mi boca está llena de arena!",
  ui_story_5040_50401201_4_dialog_content = "Uf... Gracias a Dios que estás bien. ¿Estás herido en alguna parte?",
  ui_story_5040_50401201_5_dialog_content = "*Tose* No, creo que estoy bien. Me duele la cabeza, eso es todo...",
  ui_story_5040_50401201_6_dialog_content = "El gusano de arena te envió volando de cabeza a una duna... Cuando vi tu cuerpo medio enterrado sobresaliendo de la arena, pensé que estabas gravemente herido.",
  ui_story_5040_50401201_7_dialog_content = "No fue fácil para Tara y para mí sacarte, pequeña Caelestite... realmente deberías agradecernos.",
  ui_story_5040_50401201_8_dialog_content = "G-Gracias...",
  ui_story_5040_50401201_9_dialog_content = "Espera, ¿dónde están los demás? ¿Están bien?",
  ui_story_5040_50401201_10_dialog_content = "Corrimos a ayudarte en cuanto vimos que tus piernas sobresalían de la arena.",
  ui_story_5040_50401201_11_dialog_content = "Gracias a esa feroz tormenta de arena, perdimos al gusano de arena y nos separamos de Adonis y los demás.",
  ui_story_5040_50401201_12_dialog_content = "¡Intentaré localizarlos con mis poderes!",
  ui_story_5040_50401201_13_option_content = "Enlace mental!",
  ui_story_5040_50401201_14_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5040_50401201_15_dialog_content = "No siento ningún rastro de ellos cerca...",
  ui_story_5040_50401201_16_dialog_content = "Está bien. Mis altavoces están buscándolos mientras hablamos. A menos que tengan problemas, deberíamos tener noticias de ellos lo suficientemente pronto.",
  ui_story_5040_50401201_17_dialog_content = "Incluso si estuvieran enterrados bajo tierra, Hawk puede detectar hasta el más mínimo movimiento en la superficie de la arena y encontrarlos.",
  ui_story_5040_50401201_18_dialog_content = "Adonis... Por favor, ponte bien...",
  ui_story_5040_50401201_19_dialog_content = "Shreee—!",
  ui_story_5040_50401201_20_dialog_content = "Mi pájaro tiene noticias para nosotros.",
  ui_story_5040_50401201_21_dialog_content = "¿Bien? ¿Los encontraste?",
  ui_story_5040_50401201_22_dialog_content = "Shreee—",
  ui_story_5040_50401201_23_dialog_content = "... ¿Ninguna señal de ellos en absoluto?",
  ui_story_5040_50401201_24_dialog_content = "Inténtelo de nuevo y amplíe su radio de búsqueda esta vez. No se preocupe por la cantidad de Lumina que gastará.",
  ui_story_5040_50401201_25_dialog_content = "¡Ve!",
  ui_story_5040_50401201_26_dialog_content = "Shreee-!",
  ui_story_5040_50401201_27_dialog_content = "Voy a mirar alrededor también.",
  ui_story_5040_50401201_28_dialog_content = "¡Pero todavía te duele la pierna!",
  ui_story_5040_50401201_29_dialog_content = "¡No puedo sentarme aquí y no hacer nada!",
  ui_story_5040_50401201_30_dialog_content = "Solo estarías desperdiciando tu energía. Si los ojos de un halcón no pueden ver algo desde el aire, ¿qué te hace pensar que tus ojos pueden hacerlo mejor?",
  ui_story_5040_50401201_31_dialog_content = "Tu mejor opción es descansar aquí, para que no exacerbes tus lesiones.",
  ui_story_5040_50401201_32_dialog_content = "...",
  ui_story_5040_50401201_33_dialog_content = "Si no fuera por mí fingiendo pérdida de memoria, Adonis ni siquiera estaría en este lío, ¿verdad?",
  ui_story_5040_50401201_34_dialog_content = "... Para ser honesto, descubrí hace años a través de mi habilidad que estabas fingiendo.",
  ui_story_5040_50401201_35_dialog_content = "Es solo que pensé que tenías tus razones, así que no quise intervenir.",
  ui_story_5040_50401201_36_dialog_content = "Si...",
  ui_story_5040_50401201_37_dialog_content = "Pero en retrospectiva, ¡dejar que hagas lo que quieras acaba de ponernos a todos en peligro!",
  ui_story_5040_50401201_38_dialog_content = "¿Qué diablos estabas pensando? ¡¿Cómo pudiste hacerle esto a todos?!",
  ui_story_5040_50401201_39_dialog_content = "Pensé... Pensé que ayudaría a Adonis a superar su miedo al mundo exterior.",
  ui_story_5040_50401201_40_dialog_content = "Siempre ha sido reacio a dejar atrás su vida en Northland... Así que esperaba que estas pruebas le dieran el empujón que necesitaba.",
  ui_story_5040_50401201_41_option_content = "¡Eso es completamente loco!",
  ui_story_5040_50401201_42_dialog_content = "No importa el resto de nosotros. ¿No es Adonis la persona que más significa para ti?",
  ui_story_5040_50401201_43_dialog_content = "¿Cuál es el punto de completar todas estas pruebas, si eso significa poner en peligro al hombre que amas?",
  ui_story_5040_50401201_44_dialog_content = "¡Ahora no está por ningún lado, junto con Kya y Sable! ¡Esto no es una broma, Tara!",
  ui_story_5040_50401201_45_dialog_content = "Lo siento...",
  ui_story_5040_50401201_46_option_content = "... Sé de dónde vienes.",
  ui_story_5040_50401201_47_dialog_content = "A veces, cuando no soy lo suficientemente valiente para hacer algo, necesito que otros me empujen hacia adelante.",
  ui_story_5040_50401201_48_dialog_content = "Tu corazón estaba en el lugar correcto, pero no puedo decir que esté de acuerdo con tus métodos.",
  ui_story_5040_50401201_49_dialog_content = "Si la persona que te importa no es lo suficientemente valiente como para enfrentar un desafío, debes apoyarla.",
  ui_story_5040_50401201_50_dialog_content = "Se supone que debes usar tus palabras y acciones para ayudarlos a encontrar su coraje y enfrentar esos desafíos juntos.",
  ui_story_5040_50401201_51_dialog_content = "Me equivoqué... lo siento. No debí haber sido tan imprudente...",
  ui_story_5040_50401201_52_dialog_content = "Pensé que el gusano de arena rosa sería como cualquier otro gusano de arena, solo que de un color diferente.",
  ui_story_5040_50401201_53_dialog_content = "He lidiado con muchos gusanos de arena regulares antes sin ningún problema. Pensé que podría proteger a Adonis por mi cuenta.",
  ui_story_5040_50401201_54_dialog_content = "No tenía idea de que esa cosa sería tan astuta y poderosa...",
  ui_story_5040_50401201_55_dialog_content = "En parte tengo la culpa de esto.",
  ui_story_5040_50401201_56_dialog_content = "Debería haberme dado cuenta de que para que un gusano de arena tan especial sobreviviera a las duras realidades del desierto durante tanto tiempo, debe ser mucho más tenaz que el resto.",
  ui_story_5040_50401201_57_dialog_content = "Al final del día, soy yo quien presentó este juicio, poniendo a todos en peligro. Me haré responsable de ello y haré todo lo que pueda para rescatarlos.",
  ui_story_5040_50401201_58_dialog_content = "Suspiro, tratemos de encontrar a los demás primero.",
  ui_story_5040_50401201_59_dialog_content = "Espero que estén a salvo...",
  ui_story_5040_50401201_60_dialog_content = "(Esto es preocupante...)",
  ui_story_5040_50401201_61_dialog_content = "(¿Qué debemos hacer si ni siquiera el Portavoz de Jeriah puede encontrarlos...?)",
  ui_story_5040_50401201_62_dialog_content = "Mi pájaro está de vuelta.",
  ui_story_5040_50401201_63_dialog_content = "¿Eh? ¿Donde?",
  ui_story_5040_50401201_64_dialog_content = "¡Halcón, por aquí!",
  ui_story_5040_50401201_65_dialog_content = "Kree—!",
  ui_story_5040_50401201_66_dialog_content = "Graaah...",
  ui_story_5040_50401201_67_dialog_content = "Y parece haber traído algo extra...",
  ui_story_5040_50401201_68_dialog_content = "¡Cuidemos primero estos eclipses!",
  ui_story_5040_50401201_69_dialog_content = "Déjame ayudar. ¡Un rasguño como este... no es nada para alguien que creció en el desierto de Rediesel!",
  ui_story_5040_50401202_1_dialog_content = "*Tos tos*",
  ui_story_5040_50401202_2_dialog_content = "Vaya, no esperaba sentirme tan fatigado.",
  ui_story_5040_50401202_3_dialog_content = "¿Crees que esos eclipses están huyendo del gusano de arena?",
  ui_story_5040_50401202_4_dialog_content = "No, no parecen estar entrando en pánico o buscando refugio...",
  ui_story_5040_50401202_5_dialog_content = "¿Quizás se dieron cuenta de cuánto gastaba Lumina Hawk para buscar a los demás y vieron una oportunidad perfecta para tendernos una emboscada?",
  ui_story_5040_50401202_6_dialog_content = "Ahora bien, mi pajarito... ¿Encontraste algo?",
  ui_story_5040_50401202_7_dialog_content = "Shri!",
  ui_story_5040_50401202_8_dialog_content = "Aún nada...?",
  ui_story_5040_50401202_9_dialog_content = "No hay señales del gusano de arena en ningún lugar cercano. Lo más probable es que se esté moviendo usando túneles subterráneos que creó anteriormente.",
  ui_story_5040_50401202_10_dialog_content = "Si ese es el caso, entonces también es muy probable que llevara consigo a Adonis, Kya y Sable...",
  ui_story_5040_50401202_11_dialog_content = "¡Eso significa que están en grave peligro!",
  ui_story_5040_50401202_12_dialog_content = "¡No hay forma de que esos tres puedan manejar ese gusano de arena solos! ¡Sin mencionar que podrían perderse en esos túneles!",
  ui_story_5040_50401202_13_dialog_content = "¡Tenemos que encontrarlos de inmediato!",
  ui_story_5040_50401202_14_dialog_content = "No te preocupes. Puedo empoderar a Hawk para buscar en todo el desierto.",
  ui_story_5040_50401202_15_dialog_content = "Haw—*Tos*—¡Hawk!",
  ui_story_5040_50401202_16_dialog_content = "¡Basta, Jeriah!",
  ui_story_5040_50401202_17_dialog_content = "¡Te ves tan pálido que claramente estás en tu límite!",
  ui_story_5040_50401202_18_dialog_content = "Jejeje... No me subestimes, pequeña Caelestite. No soy tan delicada.",
  ui_story_5040_50401202_19_dialog_content = "Después de todos estos años, he logrado superar cada problema por mi cuenta.",
  ui_story_5040_50401202_20_dialog_content = "Esta vez no será dif—",
  ui_story_5040_50401202_21_dialog_content = "Deberíamos pedir ayuda a la llave Rediesel.",
  ui_story_5040_50401202_22_dialog_content = "¿Qué?",
  ui_story_5040_50401202_23_dialog_content = "Volvamos a Soroz. Usaré los comunicadores para contactar a Sinsa y al resto de Rediesel Wrench, para que nos ayuden a buscar.",
  ui_story_5040_50401202_24_dialog_content = "Si no podemos encontrarlos solo nosotros tres, ¡entonces tendremos que movilizar a todos en todo el desierto!",
  ui_story_5040_50401202_25_dialog_content = "¡Eres un miembro senior del Sindicato de Mensajeros! ¡Estoy seguro de que todos estarían dispuestos a ayudar si alguien de su estado se lo pidiera!",
  ui_story_5040_50401202_26_dialog_content = "¿\"Alguien de mi estatus\"? Que ingenuo de tu parte, jeje...",
  ui_story_5040_50401202_27_dialog_content = "Siempre he sido un profesional. No ayudo a otros, y no espero ayuda de otros.",
  ui_story_5040_50401202_28_dialog_content = "Además, estoy seguro de que estarían mucho más contentos con otro mensajero mucho más responsable.",
  ui_story_5040_50401202_29_dialog_content = "¡No eres alguien que simplemente puede ser reemplazado!",
  ui_story_5040_50401202_30_dialog_content = "¡Todos en el desierto de Rediesel saben que los mensajeros son los puentes que nos conectan a todos!",
  ui_story_5040_50401202_31_dialog_content = "¡La Unión de Mensajeros fue la única razón por la que Adonis y yo pudimos mantenernos en contacto todo este tiempo!",
  ui_story_5040_50401202_32_dialog_content = "Así es. Las relaciones entre las personas nunca son tan simples, Jeriah.",
  ui_story_5040_50401202_33_dialog_content = "Al entregar las cartas de todos, estoy seguro de que ha hecho conexiones con personas más profundas de lo que cree.",
  ui_story_5040_50401202_34_dialog_content = "...",
  ui_story_5040_50401202_35_dialog_content = "¿Qué se supone que debo hacer con ustedes dos...",
  ui_story_5040_50401202_36_dialog_content = "Bien. Lo haremos a tu manera y pediremos ayuda.",
  ui_story_5040_50401202_37_dialog_content = "Pero no te hagas muchas ilusiones. Es posible que Rediesel Wrench no quiera ayudar a alguien que solo piensa en ellos cuando está en problemas.",
  ui_story_5040_50401202_38_dialog_content = "Nunca lo sabremos a menos que lo intentemos, ¿verdad?",
  ui_story_5040_50401202_39_dialog_content = "¡Volvamos a Soroz!",
  ui_story_5040_50401202_40_dialog_content = "No seas tan apresurado. Puedo llegar a ellos más rápido que sus comunicadores.",
  ui_story_5040_50401202_41_dialog_content = "¿Ah?",
  ui_story_5040_50401202_42_dialog_content = "Es un talento mío, uno que quemará casi toda mi Lumina. Una vez que lo use, no podré volver a hacerlo durante mucho tiempo...",
  ui_story_5040_50401202_43_dialog_content = "pero creo que ahora es el momento perfecto para usarlo.",
  ui_story_5040_50401202_44_dialog_content = "Espera, ¿me estás diciendo que tienes algún tipo de ataque definitivo bajo la manga?",
  ui_story_5040_50401202_45_dialog_content = "No es un ataque, no.",
  ui_story_5040_50401202_46_dialog_content = "Todo lo que hace es permitirme establecer rápidamente una conexión con mis pequeños pajaritos de Courier Union, por lo que es solo para emergencias.",
  ui_story_5040_50401202_47_dialog_content = "Al activar esta habilidad, puedo usar a Hawk para pedirles ayuda. De esta manera, podemos llegar a todos los miembros de Rediesel Wrench en el área.",
  ui_story_5040_50401202_48_dialog_content = "¿Alguna vez lo has hecho antes?",
  ui_story_5040_50401202_49_dialog_content = "¡No! Este es mi primer intento.",
  ui_story_5040_50401202_50_dialog_content = "¡Ven, mi dulce pajarito! ¡Lleva mi mensaje a todos los que quieran escuchar!",
  ui_story_5040_50401202_51_dialog_content = "Shri!",
  ui_story_5040_50401202_52_dialog_content = "¡Ve!",
  ui_story_5040_50401202_53_dialog_content = "Shreee-!",
  ui_story_5040_50401202_54_dialog_content = "Vuelve a casa con buenas noticias, mi hermoso pajarito...",
  ui_story_5040_50401202_55_dialog_content = "<color=#e8d9bb>Minutos después...</color>",
  ui_story_5040_50401202_56_dialog_content = "Todavía no hay respuesta...",
  ui_story_5040_50401202_57_dialog_content = "Hawk puede ser rápido, pero aún necesita tiempo para entregar mi mensaje. Sea paciente.",
  ui_story_5040_50401202_58_dialog_content = "... ¡Mirar! ¡Ahí está!",
  ui_story_5040_50401202_59_dialog_content = "¡Sí! Es el Halcón de Jeriah...",
  ui_story_5040_50401202_60_dialog_content = "Shreee-!",
  ui_story_5040_50401202_61_dialog_content = "Parece que lleva algo en sus garras... ¡Cuidado! ¡Está tirando cosas sobre nosotros!",
  ui_story_5040_50401202_62_dialog_content = "¿Son estas... cartas?",
  ui_story_5040_50401202_63_dialog_content = "¡Ellos son! Mira todas estas letras, cayendo del cielo como nieve...",
  ui_story_5040_50401202_64_dialog_content = "Hay muchos de ellos. Creo que hay notas dentro de ellos.",
  ui_story_5040_50401202_65_dialog_content = "Vaya, ¿qué significa esto? No puedo hacer cara o cruz de esto!",
  ui_story_5040_50401202_66_dialog_content = "Déjame ver.",
  ui_story_5040_50401202_67_dialog_content = "Oh, es solo un mensaje codificado de la llave inglesa Rediesel. Dice que nadie ha visto a nuestros amigos ni a ese gusano de arena en el noroeste del desierto.",
  ui_story_5040_50401202_68_dialog_content = "No todos en Rediesel Wrench saben leer o escribir, por lo que usamos mensajes como estos para comunicarnos la mayor parte del tiempo.",
  ui_story_5040_50401202_69_dialog_content = "Realmente funcionó...",
  ui_story_5040_50401202_70_dialog_content = "Shri!",
  ui_story_5040_50401202_71_dialog_content = "¿Me estás diciendo que estas letras incluyen todos los lugares donde Rediesel Wrench ha detectado el gusano de arena rosa?",
  ui_story_5040_50401202_72_dialog_content = "Entonces, si seguimos sus notas, deberíamos poder encontrar al gusano de arena y a nuestros amigos, ¿verdad?",
  ui_story_5040_50401202_73_dialog_content = "Cierto...",
  ui_story_5040_50401202_74_dialog_content = "entonces que estamos esperando ' ¡Empecemos a repasar estas letras!",
  ui_story_5040_50401202_75_dialog_content = "Nada cerca de Tail Street o Red-Eye Gorge.",
  ui_story_5040_50401202_76_dialog_content = "Nada en dirección a la Federación Illumina tampoco... ¿Hmm?",
  ui_story_5040_50401202_77_dialog_content = "¡Ajá! ¡Te encontré!",
  ui_story_5040_50401202_78_dialog_content = "¡¿Dónde?!",
  ui_story_5040_50401202_79_dialog_content = "Lejos al sur, cerca de un oasis en lo profundo del desierto.",
  ui_story_5040_50401202_80_dialog_content = "El lugar está repleto de gusanos de arena, y Rediesel Wrench va allí de vez en cuando para cazarlos.",
  ui_story_5040_50401202_81_dialog_content = "¡Aparentemente, uno de sus miembros vio un gusano de arena rosado emerger del suelo no hace mucho tiempo!",
  ui_story_5040_50401202_82_dialog_content = "Entonces, ¡vamos! ¡Si nos damos prisa, tal vez podamos localizar a Adonis!",
  ui_story_5040_50401202_83_dialog_content = "¡Súbete!",
  ui_story_5040_50401202_84_dialog_content = "<color=#e8d9bb>Vroom—</color>",
  ui_story_5040_50401202_85_dialog_content = "¡¡¡Bwaaaah!!!",
  ui_story_5040_50401202_86_dialog_content = "JJ-Jeriah! Reduzca la velocidad un poco!!",
  ui_story_5040_50401202_87_dialog_content = "<size=45>¿Qué fue eso?</size>",
  ui_story_5040_50401202_88_dialog_content = "<size=45>no te escuchoooooo!!</size>",
  ui_story_5040_50401202_89_option_content = "¡¡¡Despacio, Jeriaaaaah!!!",
  ui_story_5040_50401202_90_dialog_content = "¿Desacelerar? ¡No tenemos tiempo para reducir la velocidad! ¡Hay vidas en juego!",
  ui_story_5040_50401202_91_option_content = "¡No pases el límite de velocidad!",
  ui_story_5040_50401202_92_dialog_content = "¡Jajaja! Tienes bastante sentido del humor, ¿sabes?",
  ui_story_5040_50401202_93_dialog_content = "¿Limites de velocidad? ¿En el desierto?",
  ui_story_5040_50401202_94_dialog_content = "Graaaaah-!",
  ui_story_5040_50401202_95_dialog_content = "¡Estamos siendo perseguidos por Eclipsites!",
  ui_story_5040_50401202_96_dialog_content = "¡Entonces tendremos que perderlos!",
  ui_story_5040_50401202_97_dialog_content = "¡Agárrate fuerte, pequeña Caelestite! ¡Vamos a ir aún más rápido ahora!",
  ui_story_5040_50401202_98_dialog_content = "<color=#e8d9bb>Vroooom—!!!</color>",
  ui_story_5040_50401301_1_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5040_50401301_2_dialog_content = "¡Ahhhhhh—!",
  ui_story_5040_50401301_3_dialog_content = "¡Eso fue hermoso!",
  ui_story_5040_50401301_4_dialog_content = "¡Probablemente podría darle una oportunidad a los mejores conductores de Rediesel Wrench!",
  ui_story_5040_50401301_5_dialog_content = "¿Ah, de verdad? Lo tomaré como un cumplido.",
  ui_story_5040_50401301_6_dialog_content = "Ya no veo ninguna señal de esos Eclipsites... Creo que los perdimos.",
  ui_story_5040_50401301_7_dialog_content = "Supongo que eso significa que puedo soltar el gas un poco ahora.",
  ui_story_5040_50401301_8_dialog_content = "Uf... por fin ha terminado...",
  ui_story_5040_50401301_9_dialog_content = "¿Estamos casi allí?",
  ui_story_5040_50401301_10_dialog_content = "No, todavía estamos a cierta distancia.",
  ui_story_5040_50401301_11_dialog_content = "Las dunas cambiantes del desierto de Rediesel dificultan que la mayoría de las personas mantengan su sentido de orientación.",
  ui_story_5040_50401301_12_dialog_content = "Pero contigo a la cabeza, estoy seguro de que estaremos bien.",
  ui_story_5040_50401301_13_dialog_content = "¿Por qué siento que he escuchado algo así antes...?",
  ui_story_5040_50401301_14_dialog_content = "¡Simplemente no te preocupes, haz lo que dice y estarás bien!",
  ui_story_5040_50401301_15_dialog_content = "Tenía mis reservas sobre ti ayer, pero creo que ahora puedo confiar en ti.",
  ui_story_5040_50401301_16_dialog_content = "Cuando hablé con Sinsa, dijo que debería confiar en ti de todo corazón.",
  ui_story_5040_50401301_17_dialog_content = "¿Eso es lo que él dijo?",
  ui_story_5040_50401301_18_dialog_content = "Por supuesto, todos los demás en Rediesel Wrench también confían en usted y están agradecidos por todo lo que hace.",
  ui_story_5040_50401301_19_dialog_content = "Por eso me molesta tanto cuando a veces hablas tan mal de ellos.",
  ui_story_5040_50401301_20_dialog_content = "¿Es eso así? Jeje gracias.",
  ui_story_5040_50401301_21_dialog_content = "Eso me recuerda, PlayerName... Debería disculparme por lo de ayer.",
  ui_story_5040_50401301_22_dialog_content = "¿Eh? ¿Por qué ahora, de repente?",
  ui_story_5040_50401301_23_dialog_content = "Cuando me preguntaste si deberíamos pedir ayuda para buscar a los demás, te dejé fuera.",
  ui_story_5040_50401301_24_dialog_content = "¿Oh eso? No estaba tan molesto, para ser honesto...",
  ui_story_5040_50401301_25_dialog_content = "Aunque no entiendo. ¿Por qué te molesta tanto la llave inglesa Rediesel?",
  ui_story_5040_50401301_26_dialog_content = "Sí, supuse que los conocías bien, considerando que naciste aquí.",
  ui_story_5040_50401301_27_dialog_content = "¿Uno de esos tipos inútiles que ignoraron las órdenes de Sinsa saquearon tu aldea?",
  ui_story_5040_50401301_28_dialog_content = "No, nada de eso... Al contrario, mis padres alguna vez fueron miembros de Rediesel Wrench, al igual que yo.",
  ui_story_5040_50401301_29_dialog_content = "Pero corté los lazos con mis padres y la llave inglesa Rediesel hace mucho, mucho tiempo.",
  ui_story_5040_50401301_30_dialog_content = "¿Pero por qué?",
  ui_story_5040_50401301_31_dialog_content = "¿Sueles tener tanta curiosidad por la vida privada de otras personas, o solo soy yo?",
  ui_story_5040_50401301_32_dialog_content = "¡Lo siento, no quise entrometerme! Está bien si no quieres hablar de eso...",
  ui_story_5040_50401301_33_dialog_content = "Jejeje... Realmente no puedes aceptar una broma, ¿verdad?",
  ui_story_5040_50401301_34_dialog_content = "No es un secreto profundo y oscuro ni nada por el estilo. Simplemente no podía estar de acuerdo con su forma de hacer las cosas.",
  ui_story_5040_50401301_35_dialog_content = "Mis padres, al igual que el resto de Rediesel Wrench, valoraban la libertad por encima de todo.",
  ui_story_5040_50401301_36_dialog_content = "Desde que tengo memoria, nunca se preocuparon por mí como padres normales. Todo lo que hicieron fue enseñarme algunas habilidades básicas de supervivencia en el desierto.",
  ui_story_5040_50401301_37_dialog_content = "El resto del tiempo, me dejaban solo.",
  ui_story_5040_50401301_38_dialog_content = "¡¿Todo por ti mismo?!",
  ui_story_5040_50401301_39_dialog_content = "¿Es tan difícil de imaginar?",
  ui_story_5040_50401301_40_option_content = "¡Es!",
  ui_story_5040_50401301_41_dialog_content = "Sí... quiero decir, aunque estuve atrapado bajo tierra la mayor parte de mi vida, al menos tenía a Soroz para que me hiciera compañía.",
  ui_story_5040_50401301_42_dialog_content = "Los días eran largos y aburridos, pero nunca estaba solo.",
  ui_story_5040_50401301_43_dialog_content = "Es por eso que es un poco difícil para mí imaginar una vida así...",
  ui_story_5040_50401301_44_dialog_content = "Debo decir que no puedo evitar sentir una punzada de celos, pequeña Caelestite.",
  ui_story_5040_50401301_45_dialog_content = "Soroz debe haberte cuidado bien, me imagino.",
  ui_story_5040_50401301_46_dialog_content = "Sí... Soroz siempre ha sido como una familia para mí.",
  ui_story_5040_50401301_47_option_content = "Realmente no...",
  ui_story_5040_50401301_48_dialog_content = "Bueno, pasé diecisiete años atrapado bajo tierra, con solo Soroz para hacerme compañía...",
  ui_story_5040_50401301_49_dialog_content = "Soroz fue mi mentor y la única familia que tuve.",
  ui_story_5040_50401301_50_dialog_content = "Sin Soroz, no creo que me hubiera podido convertir en la persona que soy hoy.",
  ui_story_5040_50401301_51_dialog_content = "Ya veo... Soroz debe haber sido un maestro maravilloso.",
  ui_story_5040_50401301_52_dialog_content = "¡Absolutamente!",
  ui_story_5040_50401301_53_dialog_content = "Tuviste suerte, pero no todos pueden ser tan afortunados como tú.",
  ui_story_5040_50401301_54_dialog_content = "Este desierto es tan vasto y vacío, que convierte incluso la distancia entre quienes lo habitan en un mar interminable de dunas.",
  ui_story_5040_50401301_55_dialog_content = "Tal vez porque mis padres estaban tan acostumbrados a sus costumbres del desierto, esperaban que yo pudiera crecer independiente de su cuidado, solo.",
  ui_story_5040_50401301_56_dialog_content = "Incluso cuando yo era solo una niña, ellos estaban más preocupados por vivir rápido y libre que por cuidar de su propia hija.",
  ui_story_5040_50401301_57_dialog_content = "Ciertamente hay más de unas pocas personas así en la llave inglesa Rediesel...",
  ui_story_5040_50401301_58_dialog_content = "Eran demasiado entusiastas cuando se trataba de sus necesidades. Fue solo gracias a la caridad de otras personas que logré crecer sano y salvo.",
  ui_story_5040_50401301_59_dialog_content = "Todos en Rediesel Wrench siempre fueron amables, pero yo siempre estaba celoso de otros niños cuyos padres realmente los cuidaban.",
  ui_story_5040_50401301_60_dialog_content = "Envidié que tuvieran padres en los que confiar, que pudieran llorar y reír sin inhibiciones.",
  ui_story_5040_50401301_61_dialog_content = "Y aunque la vida en Rediesel Wrench siempre estuvo llena de ruido y acción, nunca tuve un espacio personal, siempre rodeado de gente.",
  ui_story_5040_50401301_62_dialog_content = "La vivacidad, el ambiente bullicioso; todo fue demasiado para mí. Todo lo que quería era estar en un lugar tranquilo y silencioso.",
  ui_story_5040_50401301_63_dialog_content = "Entonces, un día, decidí que era hora de dejarlo todo atrás. La llave inglesa Rediesel, mis padres... No quería ser más uno de ellos.",
  ui_story_5040_50401301_64_dialog_content = "Vivo libre como un pájaro, sin lealtad a ninguna facción, sin comprometerme con nadie.",
  ui_story_5040_50401301_65_dialog_content = "En cuanto a Courier Union, trabajar para ellos es solo un medio para un fin. Es un trabajo para mí, y nada más.",
  ui_story_5040_50401301_66_dialog_content = "¿Es así como te sientes...?",
  ui_story_5040_50401301_67_dialog_content = "La primera vez que puse un pie en su oficina, me sorprendió mucho ver todas esas decoraciones.",
  ui_story_5040_50401301_68_dialog_content = "Estaban esparcidos por todo el lugar y cubiertos de polvo por no haberlos limpiado en años.",
  ui_story_5040_50401301_69_dialog_content = "Solo para que lo sepas, no puedes tener ninguno de ellos. Esas cosas son preciosas para mí.",
  ui_story_5040_50401301_70_dialog_content = "¡No estoy interesado en ellos en absoluto! ¡No soy el tipo de persona que quiere todo lo que veo!",
  ui_story_5040_50401301_71_dialog_content = "Todo lo que iba a decir es que aunque dices que los necesitas... Realmente no te preocupas mucho por ellos, ¿verdad?",
  ui_story_5040_50401301_72_dialog_content = "...",
  ui_story_5040_50401301_73_dialog_content = "Ninguna de esas cosas son del desierto de Rediesel, y las usas para convencerte de que no eres parte de Rediesel Wrench.",
  ui_story_5040_50401301_74_dialog_content = "Pero si no perteneces a la llave Rediesel, entonces, ¿a dónde perteneces? No creo que sepas la respuesta a eso tampoco.",
  ui_story_5040_50401301_75_dialog_content = "(Eso explica por qué la oficina de Jeriah está repleta de todas esas decoraciones polvorientas...)",
  ui_story_5040_50401301_76_dialog_content = "(¿Quizás solo está tratando de llenar un vacío en su corazón?)",
  ui_story_5040_50401301_77_dialog_content = "Dime, ¿qué tipo de persona crees que soy?",
  ui_story_5040_50401301_78_dialog_content = "Siempre actúas como si fueras tan enigmático y distante, pero al final del día, solo eres alguien que fue descuidado emocionalmente la mayor parte de tu vida.",
  ui_story_5040_50401301_79_dialog_content = "¡Es por eso que te niegas a amar a alguien y rechazas a cualquiera que pueda preocuparse por ti!",
  ui_story_5040_50401301_80_dialog_content = "¿Esperas que alguien que nunca ha sido amado, alguien que ni siquiera sabe lo que es el amor, ame a los demás?",
  ui_story_5040_50401301_81_dialog_content = "No quise decir eso en absoluto...",
  ui_story_5040_50401301_82_dialog_content = "Oye, Jeriah... ¿no crees que estás siendo demasiado duro contigo mismo?",
  ui_story_5040_50401301_83_dialog_content = "¿A qué te refieres?",
  ui_story_5040_50401301_84_dialog_content = "No creo ni por un segundo que no sepas lo que es el amor.",
  ui_story_5040_50401301_85_dialog_content = "Si realmente no tuvieras idea, no te habrías esforzado tanto para ayudar a Adonis y Tara.",
  ui_story_5040_50401301_86_dialog_content = "Les enseñaste a vender sellos cuando estábamos en Lumopolis.",
  ui_story_5040_50401301_87_dialog_content = "Gracias a ti, pudieron ayudar a Tina y, a cambio... Ella nos señaló ese laboratorio de investigación en Illumina.",
  ui_story_5040_50401301_88_dialog_content = "Y aunque Tara estaba mintiendo sobre su pérdida de memoria, mantuviste su secreto y la ayudaste de todos modos.",
  ui_story_5040_50401301_89_dialog_content = "Tampoco querías ver que su relación se desmoronara, ¿verdad?",
  ui_story_5040_50401301_90_dialog_content = "...",
  ui_story_5040_50401301_91_dialog_content = "Acabo de descubrir que son una pareja interesante. No todos los días dos personas de extremos opuestos de Astra terminan juntas.",
  ui_story_5040_50401301_92_dialog_content = "Es tan curioso como si un pájaro y un conejo se enamoraran.",
  ui_story_5040_50401301_93_dialog_content = "No escuchas historias como esa todos los días, y mucho menos tienes la oportunidad de presenciar cómo se desarrollan, por lo que decidí acompañarlos.",
  ui_story_5040_50401301_94_dialog_content = "Entonces podrías haberte recostado y observado en silencio.",
  ui_story_5040_50401301_95_dialog_content = "Pero eso no es lo que pasó, ¿verdad? De hecho, usted hizo todo lo posible para ayudarlos muchas veces, ya sea que elija admitirlo o no.",
  ui_story_5040_50401301_96_dialog_content = "Es posible que no hayas sido amado de todo corazón en el pasado, pero alguien tan fuerte e impresionante como tú seguramente conocerá personas en el futuro que te amarán.",
  ui_story_5040_50401301_97_dialog_content = "Es eso así...",
  ui_story_5040_50401301_98_dialog_content = "Solo soy un mensajero que se pega a sí mismo.",
  ui_story_5040_50401301_99_dialog_content = "¡No subestimes tu propia importancia!",
  ui_story_5040_50401301_100_dialog_content = "¡Eres un mensajero y alguien de quien la gente del desierto no puede prescindir!",
  ui_story_5040_50401301_101_dialog_content = "¡Importas mucho más de lo que crees!",
  ui_story_5040_50401301_102_dialog_content = "¡...!",
  ui_story_5040_50401301_103_dialog_content = "¡Así es, Jeriah! ¡No tienes idea de lo importante que eres para todos!",
  ui_story_5040_50401301_104_dialog_content = "La vida en el desierto es brutal. ¡La gente solo puede sobrevivir aquí confiando en los demás y ayudándose unos a otros!",
  ui_story_5040_50401301_105_dialog_content = "Cada auroriano aquí es como un pequeño bote que flota en un mar de arena. Por nuestra cuenta, es fácil para nosotros perder el rumbo, o incluso volcar...",
  ui_story_5040_50401301_106_dialog_content = "¡Pero cuando todos nos mantenemos unidos, podemos enfrentar cualquier tormenta que se nos presente!",
  ui_story_5040_50401301_107_dialog_content = "¡Y no hay nadie aquí mejor para mantenernos a todos conectados que Rediesel Desert Courier Union!",
  ui_story_5040_50401301_108_dialog_content = "...",
  ui_story_5040_50401301_109_dialog_content = "Jejeje... Creo que finalmente entiendo por qué Adonis estaba dispuesto a reunir el coraje para dejar Northland.",
  ui_story_5040_50401301_110_dialog_content = "¡¿Qué?!",
  ui_story_5040_50401301_111_dialog_content = "¿En realidad? ¿Por qué?",
  ui_story_5040_50401301_112_dialog_content = "... Dejaré que lo descubras por ti mismo, pequeña Caelestite.",
  ui_story_5040_50401301_113_dialog_content = "¡No seas tan vago y misterioso!",
  ui_story_5040_50401301_114_dialog_content = "Ahora no es el momento. Tenemos asuntos más importantes entre manos...",
  ui_story_5040_50401301_115_dialog_content = "Rugido-!!!",
  ui_story_5040_50401301_116_dialog_content = "¡Eclipsitos! ¿¡Pero de donde vinieron!?",
  ui_story_5040_50401301_117_dialog_content = "Se sabe que los eclipses se refugian en las madrigueras subterráneas que dejan los gusanos de arena...",
  ui_story_5040_50401301_118_dialog_content = "Nos estamos acercando a nuestro destino.",
  ui_story_5040_50401301_119_dialog_content = "¡Está bien! ¡Vamos a eliminarlos a todos de una vez!",
  ui_story_5040_50401302_1_dialog_content = "<color=#e8d9bb>Chirrido-!</color>",
  ui_story_5040_50401302_2_dialog_content = "¿Así que este es el oasis en el que viven esos gusanos de arena?",
  ui_story_5040_50401302_3_dialog_content = "Sí. Este lugar sería perfecto para un asentamiento auroriano si no fuera por todos los gusanos de arena.",
  ui_story_5040_50401302_4_dialog_content = "Debido a ellos, permanece completamente deshabitado.",
  ui_story_5040_50401302_5_dialog_content = "Tal vez sea mejor así, ¿sabes? Después de todo, solo mira lo hermoso que es aquí.",
  ui_story_5040_50401302_6_dialog_content = "¿Qué pasa si te digo que las arenas que rodean este oasis están llenas de restos de aurorianos y animales que fueron víctimas de los gusanos de arena?",
  ui_story_5040_50401302_7_dialog_content = "¡¿Q-Qué?!",
  ui_story_5040_50401302_8_dialog_content = "En el desierto, cuanto más hermoso es algo, más probable es que tenga un lado macabro.",
  ui_story_5040_50401302_9_dialog_content = "No bajes la guardia solo porque se ve bonito. Hay todo tipo de peligros escondidos justo debajo de la superficie.",
  ui_story_5040_50401302_10_dialog_content = "G-Entendido...",
  ui_story_5040_50401302_11_dialog_content = "Sin embargo, es raro. No siento ningún gusano de arena cerca... no hay escamas a la vista.",
  ui_story_5040_50401302_12_dialog_content = "¿Podrían haber emigrado a otro lugar?",
  ui_story_5040_50401302_13_dialog_content = "Hay otra posibilidad.",
  ui_story_5040_50401302_14_dialog_content = "El gusano de arena rosa podría haberlos ahuyentado para reclamar este oasis como propio.",
  ui_story_5040_50401302_15_dialog_content = "¡Entonces debemos darnos prisa y buscar señales de ese gusano de arena!",
  ui_story_5040_50401302_16_dialog_content = "Parece que tengo que molestarte de nuevo, Hawk.",
  ui_story_5040_50401302_17_dialog_content = "Shri!",
  ui_story_5040_50401302_18_dialog_content = "¡Usaré mis habilidades psíquicas para explorar también!",
  ui_story_5040_50401302_19_option_content = "¡Potencia de fuerza!",
  ui_story_5040_50401302_20_dialog_content = "(Por favor, muéstrame algo... Un rastro del gusano de arena rosa, un indicio de la presencia de mis amigos... ¡cualquier cosa!)",
  ui_story_5040_50401302_21_dialog_content = "Espera, ¿eso es...?",
  ui_story_5040_50401302_22_dialog_content = "Jerías! ¡Tara! ¡Creo que acabo de sentir a Adonis y Kya!",
  ui_story_5040_50401302_23_dialog_content = "¿En realidad? Eres incluso más rápido que Hawk...",
  ui_story_5040_50401302_24_dialog_content = "¡¿Dónde están?!",
  ui_story_5040_50401302_25_dialog_content = "¡Por aquí!",
  ui_story_5040_50401302_26_dialog_content = "¿Estás seguro de que los sentiste? No hay nada aquí, a excepción de algunos arbustos...",
  ui_story_5040_50401302_27_dialog_content = "¡Mis poderes aún no me han mentido! Están en algún lugar por aquí, pero parecen estar inconscientes... Por eso no puedo precisar su ubicación.",
  ui_story_5040_50401302_28_dialog_content = "¿Hola?",
  ui_story_5040_50401302_29_dialog_content = "Kya! ¡Adonis! ¡Sable!",
  ui_story_5040_50401302_30_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5040_50401302_31_dialog_content = "Espera... Mira el arbusto de allí. Esas plantas generalmente crecen hacia arriba, ¡pero están tiradas en el suelo!",
  ui_story_5040_50401302_32_dialog_content = "Parece que alguien o algo les hizo esto...",
  ui_story_5040_50401302_33_dialog_content = "¡¿A-Adonis?!",
  ui_story_5040_50401302_34_dialog_content = "¡Y Kya también! Pero, ¿dónde está Sable?",
  ui_story_5040_50401302_35_dialog_content = "Aún respiran... simplemente inconscientes.",
  ui_story_5040_50401302_36_dialog_content = "¡Adonis! ¡Despertar!",
  ui_story_5040_50401302_37_dialog_content = "Urgh... ¿D-dónde estoy...?",
  ui_story_5040_50401302_38_dialog_content = "¡Oh, gracias a Dios que estás bien!",
  ui_story_5040_50401302_39_dialog_content = "¡Ay! ¡Fácil, Tara! Mis costillas se van a romper... o tal vez ya están rotas.",
  ui_story_5040_50401302_40_dialog_content = "Lo siento, estoy tan aliviado de que estés bien.",
  ui_story_5040_50401302_41_dialog_content = "¿Recuerdas cómo llegaste aquí? ¿Por qué Sable no está con ustedes dos?",
  ui_story_5040_50401302_42_dialog_content = "Dame un segundo...",
  ui_story_5040_50401302_43_dialog_content = "Recuerdo esta loca tormenta de arena, y el suelo hundiéndose bajo mis pies... Y luego, ese gusano de arena rosa arremetiendo contra mí...",
  ui_story_5040_50401302_44_dialog_content = "Entré en pánico. No quería que la tormenta me arrastrara ni que me tragara la arena, así que me agarré a una de las escamas del gusano de arena y me aferré a ella para salvar mi vida.",
  ui_story_5040_50401302_45_dialog_content = "Después, me llevó a un lugar completamente oscuro... ¿Creo que era una especie de madriguera?",
  ui_story_5040_50401302_46_dialog_content = "Llamé a Kya y Sable, pero no respondieron.",
  ui_story_5040_50401302_47_dialog_content = "Fue entonces cuando el gusano de arena comenzó a retorcerse. No me atrevía a soltarlo, así que aguanté hasta que finalmente me desmayé.",
  ui_story_5040_50401302_48_dialog_content = "No vuelvas a hacer eso la próxima vez que veas un gusano de arena, Adonis.",
  ui_story_5040_50401302_49_dialog_content = "Es una de las cosas más peligrosas que podrías haber hecho. Eres increíblemente afortunado de estar vivo.",
  ui_story_5040_50401302_50_dialog_content = "Quiero decir, era la primera vez que me encontraba cara a cara con un gusano de arena...",
  ui_story_5040_50401302_51_dialog_content = "En cualquier caso... Estás vivo ya salvo, y eso es todo lo que podría pedir.",
  ui_story_5040_50401302_52_dialog_content = "Sí, gracias a Dios.",
  ui_story_5040_50401302_53_dialog_content = "¡Ah, y tengo esto!",
  ui_story_5040_50401302_54_dialog_content = "¿Es una escama del gusano de arena rosa?",
  ui_story_5040_50401302_55_dialog_content = "¡Sí! Me las arreglé para soltarlo del monstruo mientras me arrastraba por el desierto.",
  ui_story_5040_50401302_56_dialog_content = "Sin embargo, solo tengo uno de ellos... Espero que sea suficiente.",
  ui_story_5040_50401302_57_dialog_content = "(Pero Tara ni siquiera tiene amnesia... ¿Deberíamos decírselo?)",
  ui_story_5040_50401302_58_dialog_content = "En realidad, Adonis... tengo algo que confesarte.",
  ui_story_5040_50401302_59_dialog_content = "¿Qué es?",
  ui_story_5040_50401302_60_dialog_content = "Nunca perdí mis recuerdos en primer lugar.",
  ui_story_5040_50401302_61_dialog_content = "He estado fingiendo todo este tiempo... Sólo quería ver si eras capaz de reunir el coraje para irte de Northland...",
  ui_story_5040_50401302_62_dialog_content = "... Tara, realmente no deberías haber hecho esto.",
  ui_story_5040_50401302_63_dialog_content = "Lo siento...",
  ui_story_5040_50401302_64_dialog_content = "Nunca debí haberte mentido, ni haberte obligado a dejar Northland, ni haberte hecho enfrentar todos esos peligros... tienes todo el derecho de estar molesto conmigo.",
  ui_story_5040_50401302_65_dialog_content = "¡Te prometo que nunca te haré vivir en un lugar donde no quieras volver a vivir! Pasaré el resto de mi vida en Northland, si es necesario...",
  ui_story_5040_50401302_66_dialog_content = "Pero, ¿cómo irás a explorar si vives allí? Viajar en Northland es casi imposible.",
  ui_story_5040_50401302_67_dialog_content = "Yo... dejaré de explorar.",
  ui_story_5040_50401302_68_dialog_content = "Eres mucho más importante para mí que cavar en unas ruinas.",
  ui_story_5040_50401302_69_dialog_content = "...",
  ui_story_5040_50401302_70_dialog_content = "No puedo creerte.",
  ui_story_5040_50401302_71_dialog_content = "¡¿Qué?!",
  ui_story_5040_50401401_1_dialog_content = "Yo... ¡Ni siquiera puedo describir lo enojado que estoy contigo!",
  ui_story_5040_50401401_2_dialog_content = "Lo siento mucho.",
  ui_story_5040_50401401_3_dialog_content = "¡Escucha lo que tengo que decir antes de que empieces a disculparte!",
  ui_story_5040_50401401_4_dialog_content = "Solía ser un debilucho antes... Ni siquiera podía dar un paso fuera de Northland, y mucho menos luchar contra los Eclipsites.",
  ui_story_5040_50401401_5_dialog_content = "No te culpo por hacer lo que hiciste para ayudarme a superar mis miedos... Después de todo, estoy seguro de que estabas al final de tu juicio.",
  ui_story_5040_50401401_6_dialog_content = "Adonis...",
  ui_story_5040_50401401_7_dialog_content = "¿Así que no estás molesto con ella porque mintió sobre tener amnesia?",
  ui_story_5040_50401401_8_dialog_content = "Ya sospechaba que ella no perdió sus recuerdos anoche. No estaba enojado por eso.",
  ui_story_5040_50401401_9_dialog_content = "Por el contrario, sentí una abrumadora sensación de alivio...",
  ui_story_5040_50401401_10_dialog_content = "porque finalmente supe con certeza que Tara no me olvidó porque me odiaba.",
  ui_story_5040_50401401_11_dialog_content = "Entonces, ¿por qué estás tan enojado?",
  ui_story_5040_50401401_12_dialog_content = "¿Probablemente porque se está comprometiendo?",
  ui_story_5040_50401401_13_dialog_content = "¿Comprometer cómo, exactamente?",
  ui_story_5040_50401401_14_dialog_content = "¡Es precisamente por eso, Sra. Jeriah! Me alegro de que alguien vea de dónde vengo.",
  ui_story_5040_50401401_15_dialog_content = "¿Podría alguien decirme de qué estamos hablando?",
  ui_story_5040_50401401_16_dialog_content = "Estoy enojado porque Tara acaba de decir que estaba dispuesta a dejar de explorar el mundo, solo para poder vivir conmigo en Northland.",
  ui_story_5040_50401401_17_option_content = "No querrás que se sienta confinada.",
  ui_story_5040_50401401_18_dialog_content = "¡Es Correcto!",
  ui_story_5040_50401401_19_option_content = "¿Porque ya no te gusta?",
  ui_story_5040_50401401_20_dialog_content = "¡Por supuesto que sí! ¡¿Por qué pensarías eso?!",
  ui_story_5040_50401401_21_dialog_content = "Conozco a Tara mejor que nadie, así que puedo decir sin lugar a dudas que ella nunca se mudaría voluntariamente a Northland y viviría una vida tranquila y pacífica.",
  ui_story_5040_50401401_22_dialog_content = "Aunque ella dice que está dispuesta a vivir allí y estar conmigo... ¡Para mí está claro que está renunciando a sus esperanzas y sueños!",
  ui_story_5040_50401401_23_dialog_content = "Nunca podría dejar que se hiciera eso a sí misma, ¡especialmente no por mí!",
  ui_story_5040_50401401_24_dialog_content = "Adonis, tú...",
  ui_story_5040_50401401_25_dialog_content = "Te amo, Tara. El verdadero tú. El que quiere viajar y explorar las ruinas en todos los rincones del mundo.",
  ui_story_5040_50401401_26_dialog_content = "Sin ti, un cobarde protegido como yo nunca habría aprendido tanto sobre el mundo fuera de Northland.",
  ui_story_5040_50401401_27_dialog_content = "Todavía recuerdo haberte oído describir haber visto la silueta de los muros de la línea de defensa de Illumina en el horizonte desde el desierto de Rediesel.",
  ui_story_5040_50401401_28_dialog_content = "O cómo, desde Lumopolis, podías mirar hacia abajo y ver todas las montañas y llanuras, así como las nubes que pasaban bajo tus pies...",
  ui_story_5040_50401401_29_dialog_content = "Pffft... ¿No te estás olvidando de la parte donde los soldados de Lumopolis me confundieron con un ladrón?",
  ui_story_5040_50401401_30_dialog_content = "Fue tan caótico... ¡Terminé pasando todo el día ayudándolos a atrapar al verdadero criminal!",
  ui_story_5040_50401401_31_dialog_content = "¡Jajaja! ¡Así es, y gracias a Dios que fuiste lo suficientemente rápido para atraparlo! ¡De lo contrario, habrías estado en un verdadero problema!",
  ui_story_5040_50401401_32_dialog_content = "¡Tuve que trabajar muy duro para probar mi inocencia!",
  ui_story_5040_50401401_33_dialog_content = "Tara... Podríamos seguir durante horas, pero lo que realmente quiero decir...",
  ui_story_5040_50401401_34_dialog_content = "es que antes de conocerte, mi mundo entero era tan blanco y vacío como la nieve que cubre Northland.",
  ui_story_5040_50401401_35_dialog_content = "Eres quien trajo color a mi aburrida y monótona vida.",
  ui_story_5040_50401401_36_dialog_content = "Eso es lo que más me gusta de ti. No quiero detenerte o evitar que explores el mundo...",
  ui_story_5040_50401401_37_dialog_content = "por eso voy a hacer todo lo posible para ser más fuerte y ser más valiente, ¡para poder ir contigo!",
  ui_story_5040_50401401_38_dialog_content = "<size=45>Adonis-!</size>",
  ui_story_5040_50401401_39_dialog_content = "Ay-! ¡¡¡Me estás aplastando de nuevo!!!",
  ui_story_5040_50401401_40_dialog_content = "Así es como se sienten, ¿eh?",
  ui_story_5040_50401401_41_dialog_content = "Puede que tengas la capacidad de leer la mente de las personas, pero eso no significa que seas capaz de discernir lo que hay en sus corazones.",
  ui_story_5040_50401401_42_dialog_content = "¡Ey! ¡¡Nunca dije que mis habilidades psíquicas fueran omniscientes!!",
  ui_story_5040_50401401_43_dialog_content = "Efectivamente, porque nadie lo es. Y es por eso que existen malentendidos que crean abismos entre las personas hasta romper gradualmente sus conexiones.",
  ui_story_5040_50401401_44_dialog_content = "Pero si las personas están dispuestas a comunicarse entre sí, pueden salvar los abismos y reconectarse.",
  ui_story_5040_50401401_45_dialog_content = "Y vuelven más fuertes y resistentes que antes.",
  ui_story_5040_50401401_46_dialog_content = "Uf... ¿Qué pasa con todo el alboroto...?",
  ui_story_5040_50401401_47_dialog_content = "Kya! ¡Por fin estás despierto!",
  ui_story_5040_50401401_48_dialog_content = "... PlayerName? ¿Jerías? Tara y Adonis también están aquí... ¿Finalmente se reconciliaron?",
  ui_story_5040_50401401_49_dialog_content = "Pasaron por mucho, pero sí... ¡ahora están bien!",
  ui_story_5040_50401401_50_dialog_content = "Me alegra oírlo... Cuando ese gusano de arena nos barrió a mí ya Sable, estaba realmente preocupado por Adonis.",
  ui_story_5040_50401401_51_dialog_content = "Eso me recuerda... ¿Dónde está Sable?",
  ui_story_5040_50401401_52_dialog_content = "No la hemos visto... Cuando llegamos aquí, solo te encontramos a ti y Adonis desmayados. No puedo sentirla en ningún lugar cercano tampoco...",
  ui_story_5040_50401401_53_dialog_content = "¿Recuerdas lo que pasó antes de que perdieras el conocimiento?",
  ui_story_5040_50401401_54_dialog_content = "Yo... Solo recuerdo que esa tormenta de arena me lanzó al cielo con Sable... Creo que logró agarrar el cuerno del gusano de arena.",
  ui_story_5040_50401401_55_dialog_content = "Después de eso, el gusano de arena nos arrastró bajo tierra, y me golpeé la cabeza con una roca o algo así... Todo se volvió negro después de eso.",
  ui_story_5040_50401401_56_dialog_content = "Así que si Adonis y tú estuvisteis inconscientes todo este tiempo... ¿quién os escondió aquí?",
  ui_story_5040_50401401_57_dialog_content = "A menos que fuera...",
  ui_story_5040_50401401_58_dialog_content = "¡¿Sable?!",
  ui_story_5040_50401401_59_dialog_content = "Pero si ella es la que te escondió aquí, ¿por qué no se la ve por ningún lado?",
  ui_story_5040_50401401_60_dialog_content = "¿Quizás quería alejar al gusano de arena de Kya y Adonis? O quizás...",
  ui_story_5040_50401401_61_dialog_content = "Sintió que ya estaba en su límite.",
  ui_story_5040_50401401_62_dialog_content = "\"Límite\"? ¿Qué \"límite\"? ¿En qué están ustedes dos esta vez?",
  ui_story_5040_50401401_63_dialog_content = "La verdad es que Sable no es un auroriano. O más bien, ella solía ser uno.",
  ui_story_5040_50401401_64_dialog_content = "¡¿Qué?!",
  ui_story_5040_50401401_65_dialog_content = "Lo sabía...",
  ui_story_5040_50401401_66_dialog_content = "No pareces sorprendido en absoluto, Caelestite.",
  ui_story_5040_50401401_67_dialog_content = "Tuve el presentimiento de que ese era el caso. Simplemente nunca tuve ninguna prueba...",
  ui_story_5040_50401401_68_dialog_content = "Fue abandonada por su amante cuando aún era auroriana. En su desesperación, se sintió atraída por el poder de los Eclipsites y se convirtió en el Sable que conocemos ahora.",
  ui_story_5040_50401401_69_dialog_content = "Pero a pesar de que su cuerpo y su mente estaban muy afectados, su conciencia había estado luchando para resistir el impulso de luchar y destruir.",
  ui_story_5040_50401401_70_dialog_content = "Sin embargo, no hace mucho, me dijo que no podía aguantar mucho más...",
  ui_story_5040_50401401_71_dialog_content = "Cómo podría ser esto...?",
  ui_story_5040_50401401_72_dialog_content = "(¿Por qué siento que he visto este tipo de cosas suceder antes...?)",
  ui_story_5040_50401401_73_dialog_content = "Dime, PlayerName. ¿Qué tipo de persona crees que es Sable?",
  ui_story_5040_50401401_74_option_content = "Una buena.",
  ui_story_5040_50401401_75_dialog_content = "Puede que se vea y actúe un poco diferente, pero no ha sido más que amigable con todos. Creo que es una buena persona.",
  ui_story_5040_50401401_76_dialog_content = "Tenemos que hacer todo lo posible para ayudarla.",
  ui_story_5040_50401401_77_option_content = "Realmente no la conozco...",
  ui_story_5040_50401401_78_dialog_content = "Parece muy tímida, así que no hemos hablado mucho... ¡pero eso no me impide creer que es una buena persona!",
  ui_story_5040_50401401_79_dialog_content = "Me encantaría ser su amiga si ella está dispuesta.",
  ui_story_5040_50401401_80_dialog_content = "Entonces hagamos todo lo que esté a nuestro alcance para encontrar a Sable.",
  ui_story_5040_50401401_81_dialog_content = "¡Acordado!",
  ui_story_5040_50401401_82_dialog_content = "Shreee—!",
  ui_story_5040_50401401_83_dialog_content = "Parece que Hawk tiene algo que decirnos. Gracias, pajarito.",
  ui_story_5040_50401401_84_dialog_content = "¡Kree, kree!",
  ui_story_5040_50401401_85_dialog_content = "¿Dices que viste señales de Sable cerca?",
  ui_story_5040_50401401_86_dialog_content = "¡¿Donde esta ella?!",
  ui_story_5040_50401401_87_dialog_content = "Shreee—",
  ui_story_5040_50401401_88_dialog_content = "¿\"Bajo nuestros pies\"?",
  ui_story_5040_50401401_89_dialog_content = "Qué significa eso...?",
  ui_story_5040_50401401_90_dialog_content = "¡Espera, siento algo! Es débil, pero puedo sentir una pequeña cantidad de Darkflow acercándose...",
  ui_story_5040_50401401_91_dialog_content = "<color=#e8d9bb>Boom—!!!</color>",
  ui_story_5040_50401401_92_dialog_content = "¡Gaah! ¡Un temblor! ¡¿P-Podría ser el gusano de arena?!",
  ui_story_5040_50401401_93_dialog_content = "<size=45>¡¡¡Roooaaar!!!</size>",
  ui_story_5040_50401401_94_dialog_content = "¡Cuidado, Tara!",
  ui_story_5040_50401401_95_dialog_content = "Je, sabía que todavía estaba al acecho.",
  ui_story_5040_50401401_96_dialog_content = "<size=45>¡Graaah!</size>",
  ui_story_5040_50401401_97_dialog_content = "¡Parece que algo está persiguiendo al gusano de arena fuera de su túnel! ¿Es eso... Sable?",
  ui_story_5040_50401401_98_dialog_content = "¡¡¡Yo... no... te dejaré!!!",
  ui_story_5040_50401401_99_dialog_content = "¡¿Sable?! Ella se ve como un—",
  ui_story_5040_50401401_100_dialog_content = "¡No importa cómo se vea! ¡Todavía está de nuestro lado!",
  ui_story_5040_50401401_101_dialog_content = "Tienes que ayudarla, PlayerName!",
  ui_story_5040_50401401_102_dialog_content = "...",
  ui_story_5040_50401401_103_dialog_content = "Lo tengo. Haré todo lo que pueda.",
  ui_story_5040_50401401_104_dialog_content = "Creo que es hora de que pongamos esta amenaza rosa en su lugar... ¿Lista, pequeña Caelestite?",
  ui_story_5040_50401401_105_dialog_content = "¿Estarás bien? Hemos estado peleando batallas consecutivas durante mucho tiempo, y quemaste mucho Lumina antes...",
  ui_story_5040_50401401_106_dialog_content = "Madre mía, qué considerado por tu parte.",
  ui_story_5040_50401401_107_dialog_content = "Pero no te preocupes. Recuperé algo de mi Lumina en el viaje hasta aquí.",
  ui_story_5040_50401401_108_dialog_content = "Vamos.",
  ui_story_5040_50401401_109_dialog_content = "Roger! ¡Démosle una mano a Sable con esto!",
  ui_story_5040_50401402_1_dialog_content = "Mis recuerdos... se han vuelto tan confusos...",
  ui_story_5040_50401402_2_dialog_content = "Son como fragmentos dispersos de película, flotando en mi mente, mostrando imágenes incompletas ante mis ojos...",
  ui_story_5040_50401402_3_dialog_content = "Mi primer recuerdo es de un desierto... Es donde nací, donde crecí...",
  ui_story_5040_50401402_4_dialog_content = "Antes de que el mensajero me trajera esa carta, pensaba que era un don nadie común en el mundo.",
  ui_story_5040_50401402_5_dialog_content = "Pero esa carta me abrió los ojos a la belleza del mundo más allá del desierto... Y fue como lo conocí a \"él\"...",
  ui_story_5040_50401402_6_dialog_content = "Su nombre se me escapa ahora, pero recuerdo que mi amor por él se hacía más profundo con cada carta que nos enviábamos.",
  ui_story_5040_50401402_7_dialog_content = "Cuando finalmente le confesé mis sentimientos, y él me los devolvió...",
  ui_story_5040_50401402_8_dialog_content = "mi corazón rebosaba de alegría y emoción.",
  ui_story_5040_50401402_9_dialog_content = "Pero también fue entonces cuando sus cartas comenzaron a llegar con menos frecuencia.",
  ui_story_5040_50401402_10_dialog_content = "Me preocupaba que mis cartas no transmitieran lo suficiente mis sentimientos, así que comencé a enviarle regalos.",
  ui_story_5040_50401402_11_dialog_content = "Al principio, solo enviaba cosas que eran difíciles de conseguir en el desierto, como flores y baratijas antiguas.",
  ui_story_5040_50401402_12_dialog_content = "Mis regalos se hicieron más extravagantes a medida que pasaba el tiempo, hasta que comencé a enviar Nightium.",
  ui_story_5040_50401402_13_dialog_content = "Pero luego, sus cartas se volvieron aún más escasas, y en lugar de las tiernas palabras que solía decirme, solo me pedía que le enviara más regalos.",
  ui_story_5040_50401402_14_dialog_content = "No podía entenderlo, pero nunca dudé de él. De hecho, quería conocerlo. Y así, me envió una dirección.",
  ui_story_5040_50401402_15_dialog_content = "Me armé de valor y salí del desierto por primera vez.",
  ui_story_5040_50401402_16_dialog_content = "Siguiendo sus cartas, fui a Illumina...",
  ui_story_5040_50401402_17_dialog_content = "Y luego Lumópolis...",
  ui_story_5040_50401402_18_dialog_content = "Y finalmente... a las orillas del lago Mirror.",
  ui_story_5040_50401402_19_dialog_content = "Me dijo que nos había preparado un gran banquete de bodas en Northland...",
  ui_story_5040_50401402_20_dialog_content = "... pero él no estaba a la vista.",
  ui_story_5040_50401402_21_dialog_content = "Estaba devastado, llorando, sin idea de adónde ir o si podría regresar a casa.",
  ui_story_5040_50401402_22_dialog_content = "Fue entonces cuando una voz me habló.",
  ui_story_5040_50401402_23_dialog_content = "\"Toma esta semilla\", dijo. \"Te otorgará el poder de hacer realidad todos tus sueños\".",
  ui_story_5040_50401402_24_dialog_content = "Puse toda mi fe en esa \"semilla\", pero al final... lo perdí todo.",
  ui_story_5040_50401402_25_dialog_content = "Mis recuerdos, mi capacidad de pensar... Me convertí en nada más que un monstruo salvaje vagando por la tierra sin un propósito...",
  ui_story_5040_50401402_26_dialog_content = "Hasta que conocí a Adonis y Tara. Sus acciones me demostraron que todavía hay amor en este mundo.",
  ui_story_5040_50401402_27_dialog_content = "Y Kya, quien me mostró que hay personas que cumplen sus promesas.",
  ui_story_5040_50401402_28_dialog_content = "Y aunque a veces actúa fría y distante, Jeriah es una persona increíblemente confiable.",
  ui_story_5040_50401402_29_dialog_content = "De ella, vi lo que significa ser despreocupado.",
  ui_story_5040_50401402_30_dialog_content = "Por eso... con el poco tiempo que me queda...",
  ui_story_5040_50401402_31_dialog_content = "¡¡¡Yo... no dejaré que... te acerques a ellos!!!",
  ui_story_5040_50401402_32_dialog_content = "<size=45>¡¡¡Roooaaar!!!</size>",
  ui_story_5040_50401402_33_dialog_content = "Urg-!",
  ui_story_5040_50401402_34_dialog_content = "¡Sable!",
  ui_story_5040_50401402_35_dialog_content = "¡El gusano de arena tiene Sable! ¡Ve por su cabeza, Jeriah! ¡Tenemos que distraerlo!",
  ui_story_5040_50401402_36_dialog_content = "¡No te preocupes... por mí!",
  ui_story_5040_50401402_37_dialog_content = "Ataque... ¡punto débil!",
  ui_story_5040_50401402_38_dialog_content = "...",
  ui_story_5040_50401402_39_dialog_content = "Lo tengo.",
  ui_story_5040_50401402_40_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5040_50401402_41_dialog_content = "Rugido...",
  ui_story_5040_50401402_42_dialog_content = "¡Agh!",
  ui_story_5040_50401402_43_dialog_content = "(El gusano de arena finalmente ha caído...)",
  ui_story_5040_50401402_44_dialog_content = "(El ataque de Jeriah apuntó a una vieja herida y atravesó su caparazón...)",
  ui_story_5040_50401402_45_dialog_content = "(Pero no antes de que le diera un gran mordisco a Sable y la lanzara por los aires...)",
  ui_story_5040_50401402_46_dialog_content = "¡Sable! ¡¿Estás bien?!",
  ui_story_5040_50401402_47_dialog_content = "Dolor...",
  ui_story_5040_50401402_48_dialog_content = "¡Sable! ¡¡Sable!! ¡¡Animarse!!",
  ui_story_5040_50401402_49_dialog_content = "Esa herida parece grave...",
  ui_story_5040_50401402_50_dialog_content = "Incluso si es tan resistente como un eclipse, no creo...",
  ui_story_5040_50401402_51_dialog_content = "¡Déjame tratar de curarla con mi Luminática!",
  ui_story_5040_50401402_52_dialog_content = "Es... ¡No funciona! ¡¿Pero por qué?!",
  ui_story_5040_50401402_53_dialog_content = "No sirve de nada, Adonis. Esa herida no es algo que tu Luminatics pueda tratar.",
  ui_story_5040_50401402_54_dialog_content = "¡Señora Jeriah! ¡¿Por qué no la ayudaste?!",
  ui_story_5040_50401402_55_dialog_content = "Solo hice lo que ella me pidió que hiciera.",
  ui_story_5040_50401402_56_dialog_content = "Tú también lo entiendes, ¿no? Incluso si la hubiera salvado, se habría convertido en un monstruo sin sentido en poco tiempo.",
  ui_story_5040_50401402_57_dialog_content = "...",
  ui_story_5040_50401402_58_dialog_content = "Kya...",
  ui_story_5040_50401402_59_dialog_content = "¿Sable? ¡Estoy aquí, Sable!",
  ui_story_5040_50401402_60_dialog_content = "Por favor... no culpes... a Jeriah...",
  ui_story_5040_50401402_61_dialog_content = "Yo no... quería lastimarte... así que me fui. Pero entonces... vi... el gusano de arena...",
  ui_story_5040_50401402_62_dialog_content = "Tengo... que verlos... a todos ustedes... una última vez...",
  ui_story_5040_50401402_63_dialog_content = "Y... recordé... yo solía ser... un auroriano.",
  ui_story_5040_50401402_64_dialog_content = "Feliz.",
  ui_story_5040_50401402_65_dialog_content = "¡P-Pero todavía no te he llevado a casa, Sable! ¡Aún no he cumplido con tu pedido!",
  ui_story_5040_50401402_66_dialog_content = "Entonces... voy a cambiar... mi pedido.",
  ui_story_5040_50401402_67_dialog_content = "Por favor... llévate esto... de vuelta a... mi casa.",
  ui_story_5040_50401402_68_dialog_content = "Dile a mi familia... lo siento...",
  ui_story_5040_50401402_69_dialog_content = "...",
  ui_story_5040_50401402_70_dialog_content = "... Mensajero Unión Kya... a su servicio.",
  ui_story_5040_50401402_71_dialog_content = "¡La Unión de Mensajería siempre cumple!",
  ui_story_5040_50401402_72_dialog_content = "Cuento con usted...",
  ui_story_5040_50401402_73_dialog_content = "Sable... No...",
  ui_story_5040_50401402_74_dialog_content = "Está bien, Kya...",
  ui_story_5040_50401402_75_dialog_content = "Iré a buscarte algo para secarte las lágrimas...",
  ui_story_5040_50401402_76_dialog_content = "...",
  ui_story_5040_50401402_77_dialog_content = "Ve y déjalo salir todo.",
  ui_story_5040_50401402_78_dialog_content = "Solo así tu dolor se convertirá en la motivación que necesitas para seguir adelante.",
  ui_story_5040_50401402_79_dialog_content = "¿Jeriah...?",
  ui_story_5040_50401402_80_dialog_content = "¿Estás bien? ¿Por qué te fuiste de repente?",
  ui_story_5040_50401402_81_dialog_content = "Incluso yo necesito algo de tiempo para recomponerme de vez en cuando, pequeña Caelestite.",
  ui_story_5040_50401402_82_dialog_content = "¡Oh! L-Lo siento, Jeriah... Supongo que me acostumbré a verte lidiando con todo de una manera tan despreocupada.",
  ui_story_5040_50401402_83_dialog_content = "Jejeje... Gracias por el cumplido.",
  ui_story_5040_50401402_84_dialog_content = "Sabía hace mucho tiempo que a Sable no le quedaba mucho tiempo.",
  ui_story_5040_50401402_85_dialog_content = "Pensé que sería capaz de mantener mi distancia como siempre... pero no esta vez, parece.",
  ui_story_5040_50401402_86_dialog_content = "¿Sabías de ella? ¿Por qué no le dijiste a nadie?",
  ui_story_5040_50401402_87_dialog_content = "¿Por qué habría de hacer eso?",
  ui_story_5040_50401402_88_dialog_content = "Uh... Bueno, si todos hubiéramos sabido antes, ¡podríamos haberla ayudado aún más!",
  ui_story_5040_50401402_89_dialog_content = "Tara y Adonis también habrían estado de acuerdo con eso.",
  ui_story_5040_50401402_90_dialog_content = "Es posible que hayan podido guardar un secreto, seguro... pero ¿qué pasa con los demás?",
  ui_story_5040_50401402_91_dialog_content = "Cuanta más gente conozca un secreto, más fácil será que salga a la luz.",
  ui_story_5040_50401402_92_dialog_content = "También hay muchos Aurorianos en el mundo que no lo habrían pensado dos veces antes de vengarse de ella.",
  ui_story_5040_50401402_93_dialog_content = "Ese pajarito ya había volado demasiado cerca del sol; no había vuelta atrás para ella.",
  ui_story_5040_50401402_94_dialog_content = "Si se hubiera descubierto su identidad, habría hecho que su precioso \"viaje final\" fuera mucho más difícil de lo que fue.",
  ui_story_5040_50401402_95_dialog_content = "Tienes razón...",
  ui_story_5040_50401402_96_dialog_content = "Por eso, pequeña Caelestite, siempre debes recordar una cosa muy importante.",
  ui_story_5040_50401402_97_dialog_content = "Las relaciones con los demás son importantes, pero tener más de ellas no siempre es algo bueno.",
  ui_story_5040_50401402_98_dialog_content = "De hecho, mantener un nivel adecuado de distancia y discreción a veces es la mejor opción.",
  ui_story_5040_50401402_99_dialog_content = "Deja que tus relaciones sean el viento bajo las alas de tus camaradas, y no la red que los ata.",
  ui_story_5040_50401402_100_dialog_content = "Entiendo...",
  ui_story_5040_50401402_101_dialog_content = "Estoy de vuelta, Lady Jeriah.",
  ui_story_5040_50401402_102_dialog_content = "Siento haber llorado tanto tiempo...",
  ui_story_5040_50401402_103_dialog_content = "¿Qué hay que lamentar? No puedes reprimir emociones así. Siempre es mejor dejarlos salir cuando necesitan salir.",
  ui_story_5040_50401402_104_dialog_content = "Tara tiene razón.",
  ui_story_5040_50401402_105_dialog_content = "Parece que has decidido lo que vas a hacer a continuación, Kya.",
  ui_story_5040_50401402_106_dialog_content = "Sí. He terminado de llorar, porque todavía tengo algo que hacer. Sable me pidió que le llevara esta estampilla a su casa.",
  ui_story_5040_50401402_107_dialog_content = "Puede que no tenga forma de hacerlo ahora, pero una vez que todo haya terminado... voy a enviar una solicitud de transferencia a la división Rediesel Wrench de Courier Union.",
  ui_story_5040_50401402_108_dialog_content = "Mientras trabajo, me familiarizaré con el desierto para poder encontrar algún día la casa de Sable.",
  ui_story_5040_50401402_109_dialog_content = "Nunca me rendiré, incluso si tengo que buscar cada centímetro del Desierto Rediesel.",
  ui_story_5040_50401402_110_dialog_content = "Siempre que tenga un destino, un pajarito siempre puede terminar su viaje sin importar la distancia... ¿No es así, Kya?",
  ui_story_5040_50401402_111_dialog_content = "¡Es Correcto!",
  ui_story_5040_50401402_112_dialog_content = "¿Qué hay de ustedes?",
  ui_story_5040_50401402_113_dialog_content = "Ya no tengo dudas. Sé que realmente amo a Adonis con todo mi corazón.",
  ui_story_5040_50401402_114_dialog_content = "No necesito nada más para demostrarlo.",
  ui_story_5040_50401402_115_dialog_content = "Yo también he tomado mi decisión. El mundo exterior puede ser peligroso, pero no es tan aterrador como pensé que sería.",
  ui_story_5040_50401402_116_dialog_content = "Mi viejo yo en realidad no tenía miedo del mundo exterior... Tenía miedo de lo desconocido.",
  ui_story_5040_50401402_117_dialog_content = "Pero con la ayuda de Tara, finalmente superé mis miedos.",
  ui_story_5040_50401402_118_dialog_content = "Tampoco le voy a pedir nunca más a Adonis que haga locuras más allá de él.",
  ui_story_5040_50401402_119_dialog_content = "Viajamos por todo el continente, enfrentamos innumerables peligros y experimentamos dolor y pérdida...",
  ui_story_5040_50401402_120_dialog_content = "pero al menos al final, ustedes dos finalmente pudieron entenderse.",
  ui_story_5040_50401402_121_dialog_content = "Supongo que uno podría llamar a esto un lado positivo.",
  ui_story_5040_50401402_122_dialog_content = "¿Qué hubieras hecho si Adonis no hubiera podido conseguir esa escama de gusano de arena rosa, Tara?",
  ui_story_5040_50401402_123_dialog_content = "¿Hubieras mantenido tu pequeña farsa?",
  ui_story_5040_50401402_124_dialog_content = "Sobre eso...",
  ui_story_5040_50401402_125_dialog_content = "Apuesto a que tenías un plan alternativo.",
  ui_story_5040_50401402_126_dialog_content = "Jejeje... ¡Nada se te escapa, Jeriah!",
  ui_story_5040_50401402_127_dialog_content = "¡¿Otra escama de gusano de arena rosa?!",
  ui_story_5040_50401402_128_dialog_content = "Esto vino del primer encuentro de Sinsa con el gusano de arena rosa. Tuve que ofrecer una fortuna para comprarlo en una subasta.",
  ui_story_5040_50401402_129_dialog_content = "¡¿Tú eres el que lo compró?!",
  ui_story_5040_50401402_130_dialog_content = "No es de extrañar que supieras que la poción era falsa desde el principio... ¡El \"ingrediente raro\" que mencionó el psíquico estuvo en tus manos todo el tiempo!",
  ui_story_5040_50401402_131_dialog_content = "No fue solo eso... Quiero decir, ¡vamos! ¿Una \"poción de poder ilimitado\"? ¡Ese nombre solo es bastante ridículo!",
  ui_story_5040_50401402_132_dialog_content = "Eres la única persona lo suficientemente ingenua e impulsiva que conozco que se enamoraría de algo así.",
  ui_story_5040_50401402_133_dialog_content = "Yo, eh... Bueno...",
  ui_story_5040_50401402_134_dialog_content = "En realidad, estaba preparado para este resultado cuando decidí fingir amnesia.",
  ui_story_5040_50401402_135_dialog_content = "Si Adonis fallaba en su juicio...",
  ui_story_5040_50401402_135X1_dialog_content = "Iba a darle esta balanza a Jeriah y pedirle que pensara en otra forma de conseguirla.",
  ui_story_5040_50401402_136_dialog_content = "Ya veo... Entonces, ¿por qué compraste algo como esto en primer lugar? ",
  ui_story_5040_50401402_137_dialog_content = "¡...!",
  ui_story_5040_50401402_138_dialog_content = "Er, b-bueno... Es una escama de gusano de arena súper rara, ¿sabes? Además es rosa, así que...",
  ui_story_5040_50401402_139_dialog_content = "Quería mostrárselo a Adonis... así que lo compré por impulso.",
  ui_story_5040_50401402_140_dialog_content = "Originalmente, quería pedirle a un herrero que le hiciera un anillo de bodas.",
  ui_story_5040_50401402_141_dialog_content = "¿Oh? Esa es una idea interesante. Tampoco dejaría que la belleza de la escama del gusano de arena se desperdiciara.",
  ui_story_5040_50401402_142_dialog_content = "Pero si no me equivoco, solo el centro de la escala es lo suficientemente duro para el trabajo... lo que significa que solo se puede hacer un anillo con él, ¿verdad?",
  ui_story_5040_50401402_143_dialog_content = "¿Qué hubieras hecho con tu propio anillo si Adonis no hubiera logrado sacar otra escama de esa bestia hoy?",
  ui_story_5040_50401402_144_dialog_content = "Yo... realmente nunca pensé en eso.",
  ui_story_5040_50401402_145_dialog_content = "Pero no es tan importante. Me podría conformar con cualquier material, la verdad.",
  ui_story_5040_50401402_146_dialog_content = "Nunca has sido de los que se preocupan por este tipo de cosas, ¡pero eso no significa que esté bien!",
  ui_story_5040_50401402_147_dialog_content = "¡Un matrimonio sin un juego de anillos a juego no está bien! Además...",
  ui_story_5040_50401402_148_dialog_content = "¡Ahora tenemos todas las escamas de gusano de arena rosa que podríamos desear!",
  ui_story_5040_50401402_149_dialog_content = "<color=#e8d9bb>chirrido—</color>",
  ui_story_5040_50401402_150_dialog_content = "¿Dónde está el gusano de arena? no lo veo por ningun lado!!",
  ui_story_5040_50401402_151_dialog_content = "Cálmate, Brock. Mira allá.",
  ui_story_5040_50401402_152_dialog_content = "¡Mierda, es real! ¡El gusano de arena rosa es real! ... ¿Pero por qué no se mueve?",
  ui_story_5040_50401402_153_dialog_content = "Espera... ¿¡¿está muerto?!?!",
  ui_story_5040_50401402_154_dialog_content = "Flor? brock? ¿Qué están haciendo ustedes dos aquí?",
  ui_story_5040_50401402_155_dialog_content = "¡Ah, PlayerName! Gracias a Dios que no estás herido.",
  ui_story_5040_50401402_156_dialog_content = "Escuché de Sinsa que tú y tus amigos estaban cazando un gusano de arena rosa, así que, naturalmente, estaba un poco preocupado.",
  ui_story_5040_50401402_157_dialog_content = "Corrí tan pronto como pude, pero parece que mi ayuda ya no es necesaria.",
  ui_story_5040_50401402_158_dialog_content = "No tenía idea de que alguien en Rediesel Wrench pudiera ser tan considerado. Una pena, entonces, que llegaras demasiado tarde.",
  ui_story_5040_50401402_159_dialog_content = "Mejor suerte la próxima vez, supongo... Llámanos si alguna vez necesitas ayuda de nuevo. Llegaremos antes de que puedas decir \"gusano de arena\".",
  ui_story_5040_50401402_160_dialog_content = "Ahora bien, si tienes todo arreglado aquí, deberíamos regresar.",
  ui_story_5040_50401402_161_dialog_content = "Es posible que hayan ganado esta vez, ¡pero les juro que la próxima vez buscaré uno aún más grande, incluso más malo!",
  ui_story_5040_50401402_162_dialog_content = "Hablando de eso, ¿necesitan nuestra ayuda con esto? Escuché que las escamas de gusano de arena rosa se venden por un centavo...",
  ui_story_5040_50401402_163_dialog_content = "Este gusano de arena rosa le costó la vida a la amiga de Kya, así que no podemos entregártelo tan fácilmente.",
  ui_story_5040_50401402_164_dialog_content = "Como mínimo, primero deberías preguntarle a Kya al respecto.",
  ui_story_5040_50401402_165_dialog_content = "... No me importa lo que nadie haga con este gusano de arena.",
  ui_story_5040_50401402_166_dialog_content = "Mientras Tara y Adonis tengan suficientes escamas para hacer sus anillos de boda, ustedes pueden hacer lo que quieran con el resto.",
  ui_story_5040_50401402_167_dialog_content = "Estoy seguro de que Sable también querría eso.",
  ui_story_5040_50401402_168_dialog_content = "No sé qué pasó exactamente aquí, pero... ¡Espero que te sientas mejor pronto!",
  ui_story_5040_50401402_169_dialog_content = "Te prometo que haremos un buen uso de este gusano de arena. ¡No dejaremos que nada de eso se desperdicie!",
  ui_story_5040_50401402_170_dialog_content = "Regresamos para pedir ayuda. Para un gusano de arena tan grande, definitivamente lo vamos a necesitar.",
  ui_story_5040_50401402_171_dialog_content = "Hasta la proxima vez, PlayerName.",
  ui_story_5040_50401402_172_dialog_content = "¡Claro, nos vemos!",
  ui_story_5040_50401402_173_dialog_content = "Ha sido un día bastante ocupado, pero después de todas nuestras amargas luchas, finalmente logramos derrotar al gusano de arena rosa.",
  ui_story_5040_50401402_174_dialog_content = "Lo que significa que Adonis ha pasado oficialmente su prueba final.",
  ui_story_5040_50401402_175_dialog_content = "Solo desearía que las cosas hubieran terminado de manera diferente con Sable...",
  ui_story_5040_50401402_176_dialog_content = "Pero fue gracias a ella ya todos los demás que finalmente llegué a comprender los verdaderos sentimientos de Adonis.",
  ui_story_5040_50401402_177_dialog_content = "Y llegué a entender más a Tara, además de obtener el coraje que finalmente necesitaba para salir al mundo.",
  ui_story_5040_50401402_178_dialog_content = "Dado que todos parecen haber obtenido lo que querían, solo queda una cosa por hacer... Permítame otorgarle su sello.",
  ui_story_5040_50401402_179_dialog_content = "<color=#e8d9bb>¡Estampilla!</color>",
  ui_story_5040_50401402_180_dialog_content = "Felicidades, ustedes dos.",
  ui_story_5040_50401402_181_dialog_content = "¡Sí! ¡Felicidades!",
  ui_story_5040_50401402_182_option_content = "¡Felicidades!",
  ui_story_5040_50401402_183_dialog_content = "¡Gracias!",
  ui_story_5040_50401402_184_dialog_content = "¡Gracias a todos!",
  ui_story_5040_50401402_185_dialog_content = "Si no fuera por todos ustedes, todavía estaría escondido en un rincón en Northland...",
  ui_story_5040_50401402_186_dialog_content = "Pero venciste tus miedos.",
  ui_story_5040_50401402_187_dialog_content = "Sí. Finalmente tengo el coraje de acompañarte por el resto de nuestras vidas.",
  ui_story_5040_50401402_188_dialog_content = "*Ejem* No es que quiera interrumpir este momento privado entre ustedes, pero antes de todo eso, todavía hay algo que debe hacerse.",
  ui_story_5040_50401402_189_dialog_content = "¡...!",
  ui_story_5040_50401402_190_dialog_content = "¡Sí! ¡Y es lo más importante también!",
  ui_story_5040_50401402_191_dialog_content = "Bien, parece que todos los pájaros saben cuál es el tramo final más importante de este viaje.",
  ui_story_5040_50401402_192_dialog_content = "¿Eh? ¿Alguien quiere informarme?",
  ui_story_5040_50401402_193_dialog_content = "¿No es obvio?",
  ui_story_5040_50401402_194_dialog_content = "¡La boda!",
  ui_story_5040_50401501_1_dialog_content = "<color=#e8d9bb>Unos días después en Northland...</color>",
  ui_story_5040_50401501_2_dialog_content = "Adonis y Tara seguro que se están tomando su tiempo...",
  ui_story_5040_50401501_3_dialog_content = "¡Achuu!",
  ui_story_5040_50401501_4_dialog_content = "Hace mucho frío aquí... ¡¿Cuánto más tenemos que esperar?!",
  ui_story_5040_50401501_5_dialog_content = "Paciencia, pequeña Caelestite. Este es uno de los días más importantes de sus vidas, así que démosles un poco más de tiempo para prepararse.",
  ui_story_5040_50401501_6_dialog_content = "Suficiente.",
  ui_story_5040_50401501_7_dialog_content = "Hablando de eso, este no es el lugar donde Adonis originalmente planeó celebrar la boda, ¿verdad?",
  ui_story_5040_50401501_8_dialog_content = "Claro que no.",
  ui_story_5040_50401501_9_dialog_content = "Ya no tienen motivos para fugarse, por lo que tiene sentido que quieran organizar una boda más grande y llamativa.",
  ui_story_5040_50401501_10_dialog_content = "O... ¿quizás prefieres hacer las cosas de forma ilícita?",
  ui_story_5040_50401501_11_dialog_content = "¡N-No, esto está perfectamente bien! ¡Ahora pueden compartir su felicidad con todos sus amigos y familiares sin preocuparse!",
  ui_story_5040_50401501_12_dialog_content = "¿PlayerName?",
  ui_story_5040_50401501_13_dialog_content = "No esperaba verte aquí hoy.",
  ui_story_5040_50401501_14_dialog_content = "¡Hola, Novio! ¿También estás aquí para la boda?",
  ui_story_5040_50401501_15_dialog_content = "En efecto. Recibí una invitación de Adonis y sería negligente de mi parte no asistir. ",
  ui_story_5040_50401501_16_dialog_content = "Como era mi alumno, estoy aquí para extender los mejores deseos del Palacio de Invierno para él y su nueva novia.",
  ui_story_5040_50401501_17_dialog_content = "¡Oh, sí, recuerdo que los padres de Adonis y Naroxel mencionaron algo al respecto!",
  ui_story_5040_50401501_18_dialog_content = "Adonis siempre fue un chico cauteloso e introvertido... Hasta donde yo sabía, nunca había puesto un pie fuera de las fronteras de Northland.",
  ui_story_5040_50401501_19_dialog_content = "Cuando me enteré de que se iba a casar con Tara, una jovencita de Rediesel Wrench... Bueno, me sorprendió, por decir lo menos.",
  ui_story_5040_50401501_20_dialog_content = "Aún así, Su Majestad siempre está complacida de ver a sus sujetos interactuar con el mundo exterior y expandir sus horizontes... Al igual que yo.",
  ui_story_5040_50401501_21_dialog_content = "¡Sí!",
  ui_story_5040_50401501_22_dialog_content = "Por favor, saluda a la Reina Belén cuando regreses al palacio.",
  ui_story_5040_50401501_23_dialog_content = "Por supuesto.",
  ui_story_5040_50401501_24_dialog_content = "Ahora, si me disculpan, todavía tengo que ofrecerle mi regalo de bodas a Adonis.",
  ui_story_5040_50401501_25_dialog_content = "Cosa segura. ¡Hasta pronto, Novio!",
  ui_story_5040_50401501_26_dialog_content = "Hasta la proxima vez, PlayerName.",
  ui_story_5040_50401501_27_dialog_content = "Por cierto, ¿por qué Kya no está aquí todavía?",
  ui_story_5040_50401501_28_dialog_content = "Prácticamente me ordenó que detuviera al Coloso mientras volábamos sobre Umbraton hace unos días, diciendo que tenía que hacer algo...",
  ui_story_5040_50401501_29_dialog_content = "¡No me escuchó cuando le pregunté al respecto, y saltó antes de que tuviera la oportunidad de aterrizar a Soroz correctamente!",
  ui_story_5040_50401501_30_dialog_content = "¿No planea venir a la boda de Tara y Adonis?",
  ui_story_5040_50401501_31_dialog_content = "Kya no es de las que rompen sus promesas.",
  ui_story_5040_50401501_32_dialog_content = "¡¡¡Yo... finalmente lo logré!!!",
  ui_story_5040_50401501_33_dialog_content = "Vaya... Gracias a Dios... ¡No llego demasiado tarde!",
  ui_story_5040_50401501_34_dialog_content = "¡¿K-Kya?! ¿Por qué estás tan sin aliento?",
  ui_story_5040_50401501_35_dialog_content = "Toma, bebe un poco de agua y recupera el aliento. La boda está a punto de comenzar.",
  ui_story_5040_50401501_36_dialog_content = "G... Gracias, Lady Jeriah...",
  ui_story_5040_50401501_37_dialog_content = "<color=#e8d9bb>Glug, glug, glug—</color>",
  ui_story_5040_50401501_38_dialog_content = "Ahh... Estoy tan contenta de haber llegado a tiempo. ¡Nunca me perdonaría si llegara tarde a esto!",
  ui_story_5040_50401501_39_dialog_content = "¿Dónde has estado estos últimos días, Kya?",
  ui_story_5040_50401501_40_dialog_content = "Oh sí, todavía no te lo he dicho.",
  ui_story_5040_50401501_41_dialog_content = "Tara y Adonis me pidieron que llevara sus escamas de gusano de arena a un herrero y las forjara en sus anillos de boda.",
  ui_story_5040_50401501_42_dialog_content = "¡Echar un vistazo!",
  ui_story_5040_50401501_43_dialog_content = "Son hermosos... ¡Ni siquiera se nota que están hechos de escamas de gusano de arena!",
  ui_story_5040_50401501_44_dialog_content = "El herrero tardó mucho más de lo que esperaba en forjar estos anillos.",
  ui_story_5040_50401501_45_dialog_content = "Si no fuera por este atajo que encontré en las notas que me prestó Emerald, ¡habría llegado tarde seguro!",
  ui_story_5040_50401501_46_dialog_content = "¿Oh? ¿Qué atajo sería ese y por qué no he oído hablar de él?",
  ui_story_5040_50401501_47_dialog_content = "¡El cielo, por supuesto! ¡Tuve que volar sin parar durante horas solo para tomar un carruaje a Northland!",
  ui_story_5040_50401501_48_dialog_content = "Mis alas todavía tienen tanto dolor...",
  ui_story_5040_50401501_49_dialog_content = "¿Sabes que el Sindicato de Mensajeros de Umbraton te habría proporcionado transporte si hubieras enviado una solicitud urgente?",
  ui_story_5040_50401501_50_dialog_content = "¡¿Qué?!",
  ui_story_5040_50401501_51_dialog_content = "¡Por qué nadie me dijo eso! Tampoco se menciona en las notas de Emerald...",
  ui_story_5040_50401501_52_dialog_content = "Es un servicio bastante nuevo ofrecido por la división Umbraton. Naturalmente, no encontraría nada al respecto en el cuaderno de su superior.",
  ui_story_5040_50401501_53_dialog_content = "Suspiro... Supongo que todavía tengo mucho que aprender sobre las diferentes divisiones.",
  ui_story_5040_50401501_54_dialog_content = "Aún así, ¡es genial que hayas logrado llegar aquí a tiempo! Todavía estamos esperando que comience la ceremonia, ¡así que descansa un poco, Kya!",
  ui_story_5040_50401501_55_dialog_content = "¡Lo haré!",
  ui_story_5040_50401501_56_dialog_content = "¿Cómo fueron los preparativos mientras estuve fuera?",
  ui_story_5040_50401501_57_dialog_content = "Por favor, dime que encontraste a ese supuesto \"psíquico\" y le diste una lección para que no estafe a más personas.",
  ui_story_5040_50401501_58_dialog_content = "Jejeje... Por supuesto.",
  ui_story_5040_50401501_59_dialog_content = "Fuimos a buscarlo tan pronto como llegamos.",
  ui_story_5040_50401501_60_dialog_content = "¡Ese es el! ¡Ese es el psíquico!",
  ui_story_5040_50401501_61_dialog_content = "¡¿Ah?! ... ¿M-Puedo ayudarlo, amable señor?",
  ui_story_5040_50401501_62_dialog_content = "Me vendiste una \"poción mágica\" de mala calidad hace unos días, ¡pero era una falsificación total!",
  ui_story_5040_50401501_63_dialog_content = "¡Ah, sí! ahora te recuerdo...",
  ui_story_5040_50401501_64_dialog_content = "Debo pedirle que deje de mancillar mi buen nombre con sus ridículas afirmaciones, señor. Te puedo asegurar que mis pociones son 100 por ciento genuinas y efectivas.",
  ui_story_5040_50401501_65_dialog_content = "¡Está hecho de la escama del raro gusano de arena rosa!",
  ui_story_5040_50401501_66_dialog_content = "Y si no recuerdo mal, ¿no fuiste tú quien acudió a mí cuando mi poción hizo que tu prometida perdiera la memoria?",
  ui_story_5040_50401501_67_dialog_content = "Ese soy yo, y me lo estaba inventando todo el tiempo. Tu poción no tuvo efecto en mí en absoluto.",
  ui_story_5040_50401501_68_dialog_content = "No solo eso, ¡nunca usaste una escama de gusano de arena rosa para prepararlo!",
  ui_story_5040_50401501_69_dialog_content = "O-Oh, ¿sí? ¿Dónde está tu prueba entonces?",
  ui_story_5040_50401501_70_dialog_content = "¡Tú primero! ¿De dónde sacaste una escama de gusano de arena rosa en primer lugar?",
  ui_story_5040_50401501_71_dialog_content = "¡Te diré que lo compré en una subasta no hace mucho tiempo! ¡Solo había uno de su tipo en todo Astra!",
  ui_story_5040_50401501_72_dialog_content = "Vaya, qué coincidencia... porque yo también compré una escama rosada de gusano de arena en una subasta hace un tiempo.",
  ui_story_5040_50401501_73_dialog_content = "¡¿Qué?!",
  ui_story_5040_50401501_74_dialog_content = "De hecho, todavía tengo el certificado oficial de venta de cuando lo compré... ¿Te importaría echarle un vistazo?",
  ui_story_5040_50401501_75_dialog_content = "¡¿Fuiste el comprador misterioso que huyó con la escama de gusano de arena en esa subasta?!",
  ui_story_5040_50401501_76_dialog_content = "Mi, mi... Conseguir que te implicaras a ti mismo apenas tomó ningún esfuerzo en absoluto.",
  ui_story_5040_50401501_77_dialog_content = "No estoy del todo familiarizado con cómo Northland castiga a los estafadores, pero...",
  ui_story_5040_50401501_78_dialog_content = "Apuesto a que no quieren saber cómo los castigamos en el Desierto Rediesel.",
  ui_story_5040_50401501_79_dialog_content = "Uh... realmente no tenemos que escucharlo, gracias...",
  ui_story_5040_50401501_80_dialog_content = "¡Lo siento!",
  ui_story_5040_50401501_81_dialog_content = "Aquí, usted puede tener su dinero de vuelta! ¡Me entregaré!",
  ui_story_5040_50401501_82_dialog_content = "Eso es bueno escuchar. Me alegro de que todo saliera bien.",
  ui_story_5040_50401501_83_dialog_content = "Entonces, ¿qué pasa con los padres de Adonis? ¿Estuvieron de acuerdo con el matrimonio?",
  ui_story_5040_50401501_84_dialog_content = "Después de ver cuánto había cambiado Adonis, en realidad no tenían nada más que decir al respecto.",
  ui_story_5040_50401501_85_dialog_content = "¡Estaban más que felices de aprobar el matrimonio de Tara y Adonis!",
  ui_story_5040_50401501_86_dialog_content = "¿En realidad? ¡Eso es casi demasiado bueno para ser verdad!",
  ui_story_5040_50401501_87_dialog_content = "Después de todo, estaban completamente en contra de la idea de que Adonis se fugó con Tara antes.",
  ui_story_5040_50401501_88_dialog_content = "Solo piensas eso porque no lograste ver cómo se sentían realmente.",
  ui_story_5040_50401501_89_dialog_content = "Supongo que si hay una persona que puede ver a través de las personas, eres tú...",
  ui_story_5040_50401501_90_dialog_content = "Si los poderes de Caelestite pudieran leer los corazones de las personas, me imagino que él también podría hacerlo.",
  ui_story_5040_50401501_91_dialog_content = "¡Yo no uso mis habilidades para entrometerme en la mente de las personas! ¡Eso es completamente inapropiado!",
  ui_story_5040_50401501_92_dialog_content = "La mejor manera de entender a los demás es comunicarse con ellos.",
  ui_story_5040_50401501_93_dialog_content = "Entonces, ¿qué estaban pensando los padres de Adonis en ese entonces?",
  ui_story_5040_50401501_94_dialog_content = "Lo mismo que cualquier madre y padre ordinarios pensarían en su posición.",
  ui_story_5040_50401501_95_dialog_content = "Simplemente les preocupaba que su hijo, que nunca había salido de Northland, fuera incapaz de adaptarse al desconocido mundo exterior.",
  ui_story_5040_50401501_96_dialog_content = "Eso, a su vez, los hizo aún más reacios a dejarlo poner un pie fuera de su tierra natal.",
  ui_story_5040_50401501_97_dialog_content = "Eso suena como un círculo vicioso.",
  ui_story_5040_50401501_98_dialog_content = "Eso es cierto, por eso tuve que darles un pequeño empujón para que le dieran una oportunidad a su hijo.",
  ui_story_5040_50401501_99_dialog_content = "¡¿N-No me digas que los amenazaste como lo hiciste con el psíquico?!",
  ui_story_5040_50401501_100_dialog_content = "¿Realmente te parezco ese tipo de persona?",
  ui_story_5040_50401501_101_dialog_content = "N-No...",
  ui_story_5040_50401501_102_dialog_content = "Tienes que emplear diferentes métodos con diferentes personas.",
  ui_story_5040_50401501_103_dialog_content = "Los padres de Adonis son personas perfectamente razonables. Simplemente estaban reacios a perder de vista a su precioso hijo.",
  ui_story_5040_50401501_104_dialog_content = "Todo lo que hice fue señalar el problema de tratarlo así, y rápidamente se dieron cuenta de que dejarlo ir era lo mejor.",
  ui_story_5040_50401501_105_dialog_content = "Lo envidio por tener unos padres así.",
  ui_story_5040_50401501_106_dialog_content = "¡No sabía que hacías tantas cosas detrás de escena!",
  ui_story_5040_50401501_107_dialog_content = "Solo eché una mano aquí y allá... Quería ver cómo terminaría su historia, estos dos amantes de extremos opuestos.",
  ui_story_5040_50401501_108_dialog_content = "Tiene un final bastante satisfactorio, si lo digo yo mismo.",
  ui_story_5040_50401501_109_dialog_content = "¡Mira, están aquí!",
  ui_story_5040_50401501_110_dialog_content = "¡Son Adonis y Tara!",
  ui_story_5040_50401501_111_dialog_content = "¡Sus atuendos se ven increíbles!",
  ui_story_5040_50401501_112_dialog_content = "¡Tara se ve absolutamente impresionante! Y Adonis... ¡No tenía idea de que limpiaba tan bien!",
  ui_story_5040_50401501_113_dialog_content = "Felicidades, ustedes dos.",
  ui_story_5040_50401501_114_dialog_content = "¡Felicidades!",
  ui_story_5040_50401501_115_dialog_content = "¡Felicidades!",
  ui_story_5040_50401501_116_dialog_content = "¡Gracias!",
  ui_story_5040_50401501_117_dialog_content = "¡Muchísimas gracias a todos! ¡Lamento haberlos hecho esperar a todos!",
  ui_story_5040_50401501_118_dialog_content = "¡Somos los recién casados más afortunados de todo Astra por tener a dos de sus mejores mensajeros como testigos de nuestro matrimonio!",
  ui_story_5040_50401501_119_dialog_content = "El sentimiento es mutuo. Ahora bien, comencemos, ¿de acuerdo?",
  ui_story_5040_50401501_120_dialog_content = "Tara, ¿tomas a Adonis como tu legítimo esposo?",
  ui_story_5040_50401501_121_dialog_content = "Tener y conservar desde este día en adelante, en la salud y en la enfermedad, en la riqueza o en la pobreza, a través de todas las tribulaciones:",
  ui_story_5040_50401501_122_dialog_content = "¿Amarlo, honrarlo y aceptarlo, ahora y para siempre, hasta que la muerte los separe?",
  ui_story_5040_50401501_123_dialog_content = "¡Lo hago!",
  ui_story_5040_50401501_124_dialog_content = "Adonis, ¿tomas a Tara como tu legítima esposa?",
  ui_story_5040_50401501_125_dialog_content = "Tener y conservar desde este día en adelante, en la enfermedad y en la salud, en la riqueza o en la pobreza, a través de todas las tribulaciones:",
  ui_story_5040_50401501_126_dialog_content = "¿Amarla, honrarla y aceptarla, ahora y para siempre, hasta que la muerte los separe?",
  ui_story_5040_50401501_127_dialog_content = "¡Lo hago!",
  ui_story_5040_50401501_128_dialog_content = "Tu amor ha atravesado ríos y soportado montañas de diferencias; se ha enfrentado a todo tipo de obstáculos y peligros y ha durado. Ahora bien, mis pajaritos...",
  ui_story_5040_50401501_129_dialog_content = "Les pido que por favor intercambien sus anillos.",
  ui_story_5040_50401501_130_dialog_content = "Vaya... ¡Gracias a Dios que la ceremonia ha terminado!",
  ui_story_5040_50401501_131_dialog_content = "¡Finalmente pudimos deshacernos de esa ropa por algo más cómodo!",
  ui_story_5040_50401501_132_dialog_content = "¿No te gustó tu vestido de novia?",
  ui_story_5040_50401501_133_dialog_content = "¡Por supuesto lo hice! Lo elegimos juntos, ¿no?",
  ui_story_5040_50401501_134_dialog_content = "Estaba un poco cargado al usarlo, es todo... ¡Apenas podía moverme con él!",
  ui_story_5040_50401501_135_dialog_content = "¡Casi me caigo un par de veces cuando me llevabas al altar!",
  ui_story_5040_50401501_136_dialog_content = "Jajajaja! Para ser honesto, fue un poco extraño verte con un vestido tan llamativo.",
  ui_story_5040_50401501_137_dialog_content = "Usar tu ropa favorita y hacer lo que te gusta siempre es lo mejor, ¿no?",
  ui_story_5040_50401501_138_dialog_content = "Sí, pero debo decir que ese traje realmente te quedó genial.",
  ui_story_5040_50401501_139_dialog_content = "También tengo curiosidad, considerando que la ropa formal está muy lejos de tu atuendo habitual.",
  ui_story_5040_50401501_140_dialog_content = "¿Cómo te hiciste lucir tan bien en él?",
  ui_story_5040_50401501_141_dialog_content = "Eh, en realidad...",
  ui_story_5040_50401501_142_dialog_content = "Adonis se ha estado preparando para esta boda en secreto durante mucho, mucho tiempo.",
  ui_story_5040_50401501_143_dialog_content = "¿Padre? ¡¿Madre?!",
  ui_story_5040_50401501_144_dialog_content = "A menudo esperaba hasta que nos durmiéramos tarde en la noche y se lo probaba frente al espejo, trabajando en su estatura.",
  ui_story_5040_50401501_145_dialog_content = "Esta boda significó el mundo para él... Más que nada, quería brindarte una experiencia inolvidable.",
  ui_story_5040_50401501_146_dialog_content = "Aún así, se emocionaba tanto practicando que nos despertaba en medio de la noche...",
  ui_story_5040_50401501_147_dialog_content = "Espera, ¡¿ustedes dos lo supieron todo el tiempo?!",
  ui_story_5040_50401501_148_dialog_content = "Por supuesto que lo hicimos.",
  ui_story_5040_50401501_149_dialog_content = "Nunca nos opusimos de verdad a que te casaras, hijo. Siempre fuiste libre de elegir si lo hacías o no, ya quién.",
  ui_story_5040_50401501_150_dialog_content = "Solo nos preocupaba que te lanzaras de cabeza al matrimonio sin prepararte adecuadamente mental y emocionalmente.",
  ui_story_5040_50401501_151_dialog_content = "Después de todo, no sabías prácticamente nada del mundo exterior. ¡Incluso un estafador que vendía pociones se apoderó de ti!",
  ui_story_5040_50401501_152_dialog_content = "¡Hubiera sido irresponsable de nuestra parte dejar que te casases en ese estado!",
  ui_story_5040_50401501_153_dialog_content = "¡Exactamente! ¿Y si un día te das cuenta de que el mundo exterior no es para ti? Si llegó a arrepentirse de su decisión de dejar Northland,",
  ui_story_5040_50401501_154_dialog_content = "Hubieras responsabilizado a Tara por ser la razón por la que te fuiste.",
  ui_story_5040_50401501_155_dialog_content = "Y eso, hijo mío, no habría sido justo ni para ti ni para Tara. ¿Entiendes ahora?",
  ui_story_5040_50401501_156_dialog_content = "Padre... Madre... Lo siento por ser tan egoísta...",
  ui_story_5040_50401501_157_dialog_content = "Pero ahora puedo decirte, con total certeza, que sé cómo es el mundo exterior, y aun así... Todavía quiero casarme con Tara.",
  ui_story_5040_50401501_158_dialog_content = "Sí, hemos sido testigos de cómo has cambiado, así que ya no nos oponemos a tu matrimonio.",
  ui_story_5040_50401501_159_dialog_content = "Les deseamos a ambos todo el amor y la felicidad del mundo.",
  ui_story_5040_50401501_160_dialog_content = "Esta ya no es solo nuestra casa. Es la casa de Tara también.",
  ui_story_5040_50401501_161_dialog_content = "Si bien tus aventuras sin duda te llevarán a todos los rincones de Astra... Nunca olvides que Northland siempre estará aquí para darte la bienvenida.",
  ui_story_5040_50401501_162_dialog_content = "Madre, Padre... ¡Muchas gracias!",
  ui_story_5040_50401501_163_dialog_content = "A partir de ahora, ¡somos familia!",
  ui_story_5040_50401501_164_dialog_content = "<color=#e8d9bb>Dos días después, a bordo de Soroz...</color>",
  ui_story_5040_50401501_165_dialog_content = "Esa aventura seguro tomó mucho tiempo...",
  ui_story_5040_50401501_166_dialog_content = "Al principio, solo llevaba a algunas personas del desierto de Rediesel a Northland... ¡Nunca esperé viajar por todo Astra por eso!",
  ui_story_5040_50401501_167_dialog_content = "Menos mal que pude terminar todo antes de que Vice y Carleen regresaran de vacaciones... ¡Incluso pude comprar el elegante tocadiscos con el pago que recibí de Naroxel!",
  ui_story_5040_50401501_168_dialog_content = "Siempre me ayudan mucho, ¡pero esta vez les compré una sorpresa yo solo!",
  ui_story_5040_50401501_169_dialog_content = "Estamos de vuelta, PlayerName!",
  ui_story_5040_50401501_170_dialog_content = "El Día de la Corona de Luna fue tan agitado como cualquier otro año, pero gracias a Dios todo permaneció relativamente tranquilo este año.",
  ui_story_5040_50401501_171_dialog_content = "¿Cómo fueron las cosas mientras estuvimos fuera?",
  ui_story_5040_50401501_172_dialog_content = "Ah, igual que siempre.",
  ui_story_5040_50401501_173_dialog_content = "Acabo de volar con Soroz durante unos días y experimenté el Día de la Corona de Luna en algunos lugares diferentes.",
  ui_story_5040_50401501_174_dialog_content = "¡Incluso acepté un trabajo de Courier Union y gané algo de dinero!",
  ui_story_5040_50401501_175_dialog_content = "¡Escuché eso! Jola me preguntó por qué no estaba contigo.",
  ui_story_5040_50401501_176_dialog_content = "Varios soldados de Lumopolis también te vieron ayudando al Sindicato de Mensajeros local hace unos días. Has estado trabajando duro.",
  ui_story_5040_50401501_177_dialog_content = "Oh, no era nada, de verdad.",
  ui_story_5040_50401501_178_dialog_content = "¡Estaba muy ocupado!",
  ui_story_5040_50401501_179_dialog_content = "¡Acepté un trabajo de Courier Union y gané algo de dinero!",
  ui_story_5040_50401501_180_dialog_content = "Se suponía que iba a ser un viaje rápido, pero el trabajo terminó tomando algunos días.",
  ui_story_5040_50401501_181_dialog_content = "Escuché sobre eso, sí. Estuviste en Lumopolis en un momento, luego creo que fuiste a Illumina.",
  ui_story_5040_50401501_182_dialog_content = "¡Escuché que incluso fuiste tan lejos como el desierto de Rediesel y Northland! ¡Ese debe haber sido todo un viaje!",
  ui_story_5040_50401501_183_dialog_content = "Espera un segundo... ¡¿Por qué ustedes dos saben dónde he estado todo este tiempo?!",
  ui_story_5040_50401501_184_dialog_content = "Bueno, Soroz no es precisamente difícil de pasar por alto... ¡Llamas mucho la atención allá donde vuelas!",
  ui_story_5040_50401501_185_dialog_content = "Supongo que eso tiene sentido...",
  ui_story_5040_50401501_186_dialog_content = "De todos modos, ¡utilicé el pago para darles una pequeña sorpresa!",
  ui_story_5040_50401501_187_dialog_content = "¡Ta-da—!",
  ui_story_5040_50401501_188_dialog_content = "¡¿Ese es el tocadiscos de antes?!",
  ui_story_5040_50401501_189_dialog_content = "Era bastante caro, si no recuerdo mal.",
  ui_story_5040_50401501_190_dialog_content = "Cuando fuimos de compras a Umbraton, recuerdo que ustedes dos lo miraron a través de la ventana durante mucho tiempo.",
  ui_story_5040_50401501_191_dialog_content = "Supuse que a ustedes les debe haber gustado mucho, así que miré el precio y realmente me sorprendió.",
  ui_story_5040_50401501_192_dialog_content = "Pero cuando pensé en todas las veces que me ayudaste, me di cuenta de que no había hecho mucho para mostrar mi aprecio...",
  ui_story_5040_50401501_193_dialog_content = "¡Fue entonces cuando decidí comprar ese tocadiscos para ambos!",
  ui_story_5040_50401501_194_dialog_content = "He estado aceptando trabajos ocasionales aquí y allá, ¡y esta vez finalmente pude pagarlo!",
  ui_story_5040_50401501_195_dialog_content = "PlayerName...",
  ui_story_5040_50401501_196_dialog_content = "Hay una razón por la que estuvimos mirando ese tocadiscos durante tanto tiempo...",
  ui_story_5040_50401501_197_dialog_content = "Carleen y yo habíamos estado hablando durante días... Queríamos traerte algo especial.",
  ui_story_5040_50401501_198_dialog_content = "Entonces, cuando ambos vimos ese tocadiscos en Umbraton, inmediatamente supimos que era la elección correcta.",
  ui_story_5040_50401501_199_dialog_content = "Después de todo, los Caelestites siempre han amado la música, ¿verdad? ¡Y qué mejor manera de disfrutarlo que con un tocadiscos de alta calidad!",
  ui_story_5040_50401501_200_dialog_content = "Fue entonces cuando decidimos juntar nuestro dinero para comprártelo.",
  ui_story_5040_50401501_201_dialog_content = "También es la razón por la que volvimos a trabajar para el Día de la Corona de Luna...",
  ui_story_5040_50401501_202_dialog_content = "Trabajar...? Espera, ¡¿entonces ninguno de ustedes se fue de vacaciones?!",
  ui_story_5040_50401501_203_dialog_content = "Sí... No queríamos que te enteraras, así que lo mantuvimos en nuestro pequeño secreto...",
  ui_story_5040_50401501_204_dialog_content = "Pero fue solo después de que llegamos a Umbraton que nos dimos cuenta... alguien ya había comprado el tocadiscos.",
  ui_story_5040_50401501_205_dialog_content = "Todo lo que pudimos hacer fue comprar algunos dulces de Umbraton y algunos libros nuevos para regalarte.",
  ui_story_5040_50401501_206_dialog_content = "¡¿Entonces ustedes dos no querían ese tocadiscos en primer lugar?!",
  ui_story_5040_50401501_207_dialog_content = "Esto es-!",
